'use client';

import { useState, useMemo, Fragment } from 'react';
import { useReports } from '@/hooks/use-reports';
import { useTemplates } from '@/hooks/use-templates';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { ChevronLeft, ChevronRight, FileDown } from 'lucide-react';
import { calculateMonthlyStats } from '@/lib/statistics-utils';
import { STATISTICS_SECTIONS, DEFAULT_STATISTICS_CATEGORIES } from '@/constants/statistics';
import { format } from 'date-fns';
import { es } from 'date-fns/locale';

export default function EstadisticasPage() {
  const { reports, isLoaded: reportsLoaded } = useReports();
  const { templates, configs, isLoaded: templatesLoaded } = useTemplates();

  const [year, setYear] = useState(new Date().getFullYear());
  const [month, setMonth] = useState(new Date().getMonth()); // 0-11

  // Generate years option (current year - 2 to current + 2)
  const years = useMemo(() => {
    const current = new Date().getFullYear();
    return Array.from({ length: 5 }, (_, i) => current - 2 + i);
  }, []);

  const months = [
    'Enero',
    'Febrero',
    'Marzo',
    'Abril',
    'Mayo',
    'Junio',
    'Julio',
    'Agosto',
    'Septiembre',
    'Octubre',
    'Noviembre',
    'Diciembre',
  ];

  const stats = useMemo(() => {
    if (!reportsLoaded || !templatesLoaded) return null;
    return calculateMonthlyStats(reports, templates, configs, month, year);
  }, [reports, templates, configs, month, year, reportsLoaded, templatesLoaded]);

  const daysInMonth = useMemo(() => {
    return new Date(year, month + 1, 0).getDate();
  }, [year, month]);

  const daysArray = Array.from({ length: daysInMonth }, (_, i) => i + 1);

  return (
    <div className="container mx-auto p-4 space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold">Cuadro General de Estad├¡sticas</h1>
          <p className="text-muted-foreground">Control mensual de incidencias y novedades</p>
        </div>
        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            size="icon"
            onClick={() => {
              if (month === 0) {
                setMonth(11);
                setYear((y) => y - 1);
              } else setMonth((m) => m - 1);
            }}
          >
            <ChevronLeft className="h-4 w-4" />
          </Button>
          <Select value={String(month)} onValueChange={(v) => setMonth(parseInt(v))}>
            <SelectTrigger className="w-[140px]">
              <SelectValue>{months[month]}</SelectValue>
            </SelectTrigger>
            <SelectContent>
              {months.map((m, i) => (
                <SelectItem key={i} value={String(i)}>
                  {m}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Select value={String(year)} onValueChange={(v) => setYear(parseInt(v))}>
            <SelectTrigger className="w-[100px]">
              <SelectValue>{year}</SelectValue>
            </SelectTrigger>
            <SelectContent>
              {years.map((y) => (
                <SelectItem key={y} value={String(y)}>
                  {y}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Button
            variant="outline"
            size="icon"
            onClick={() => {
              if (month === 11) {
                setMonth(0);
                setYear((y) => y + 1);
              } else setMonth((m) => m + 1);
            }}
          >
            <ChevronRight className="h-4 w-4" />
          </Button>
          {/* Placeholder for export */}
          <Button variant="secondary" size="icon" title="Exportar (Pr├│ximamente)">
            <FileDown className="h-4 w-4" />
          </Button>
        </div>
      </div>

      <Card className="overflow-hidden border-2">
        <CardHeader className="bg-muted/30 py-4">
          <CardTitle className="text-lg font-medium text-center uppercase tracking-wide">
            Estad├¡stica Mensual - {months[month]} {year}
          </CardTitle>
        </CardHeader>
        <CardContent className="p-0 overflow-x-auto">
          {/* Add a wrapper with min-width to ensure readability on small screens */}
          <div className="min-w-[1200px]">
            <Table>
              <TableHeader>
                <TableRow className="bg-muted/50 hover:bg-muted/50">
                  <TableHead className="w-[50px] font-bold sticky left-0 z-20 bg-background border-r text-center shadow-[inset_-1px_0_0_0_hsl(var(--border))]">
                    NO.
                  </TableHead>
                  <TableHead className="w-[300px] font-bold sticky left-[50px] z-20 bg-background border-r shadow-[2px_0_5px_-2px_rgba(0,0,0,0.1)]">
                    RUBROS / CATEGOR├ìAS
                  </TableHead>
                  {daysArray.map((day) => (
                    <TableHead
                      key={day}
                      className="text-center w-[35px] min-w-[35px] p-0 font-semibold text-xs text-muted-foreground border-r last:border-r-0"
                    >
                      {day}
                    </TableHead>
                  ))}
                  <TableHead className="text-center font-bold bg-muted/20 w-[60px] border-l">
                    TOTAL
                  </TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {STATISTICS_SECTIONS.map((section) => (
                  <Fragment key={section.title}>
                    {/* Section Header */}
                    <TableRow key={section.title} className="hover:bg-muted/10 border-b-2">
                      <TableCell
                        colSpan={2}
                        className="sticky left-0 z-20 font-bold text-[11px] text-center border-r shadow-[2px_0_10px_-2px_rgba(0,0,0,0.1)] py-2"
                        style={{
                          backgroundColor: section.headerColor?.includes('blue')
                            ? 'rgba(59, 130, 246, 0.2)'
                            : section.headerColor?.includes('green')
                              ? 'rgba(34, 197, 94, 0.2)'
                              : section.headerColor?.includes('red') ||
                                  section.headerColor?.includes('orange')
                                ? 'rgba(239, 68, 68, 0.2)'
                                : section.headerColor?.includes('amber') ||
                                    section.headerColor?.includes('yellow')
                                  ? 'rgba(245, 158, 11, 0.2)'
                                  : 'rgba(156, 163, 175, 0.4)',
                        }}
                      >
                        {section.title}
                      </TableCell>
                      {/* Fill remaining cells with same background for visual continuity */}
                      {daysArray.map((day) => (
                        <TableCell
                          key={`hdr-${day}`}
                          className="p-0 border-r"
                          style={{
                            backgroundColor: section.headerColor?.includes('blue')
                              ? 'rgba(59, 130, 246, 0.2)'
                              : section.headerColor?.includes('green')
                                ? 'rgba(34, 197, 94, 0.2)'
                                : section.headerColor?.includes('red') ||
                                    section.headerColor?.includes('orange')
                                  ? 'rgba(239, 68, 68, 0.2)'
                                  : section.headerColor?.includes('amber') ||
                                      section.headerColor?.includes('yellow')
                                    ? 'rgba(245, 158, 11, 0.2)'
                                    : 'rgba(156, 163, 175, 0.4)',
                          }}
                        />
                      ))}
                      <TableCell
                        className="border-l"
                        style={{
                          backgroundColor: section.headerColor?.includes('blue')
                            ? 'rgba(59, 130, 246, 0.2)'
                            : section.headerColor?.includes('green')
                              ? 'rgba(34, 197, 94, 0.2)'
                              : section.headerColor?.includes('red') ||
                                  section.headerColor?.includes('orange')
                                ? 'rgba(239, 68, 68, 0.2)'
                                : section.headerColor?.includes('amber') ||
                                    section.headerColor?.includes('yellow')
                                  ? 'rgba(245, 158, 11, 0.2)'
                                  : 'rgba(156, 163, 175, 0.4)',
                        }}
                      />
                    </TableRow>

                    {/* Items ... code previously updated ... */}

                    {/* Items */}
                    {section.items.map((item) => {
                      const fullKey = `${item.code} ${item.label}`;
                      const catStats = stats?.get(fullKey);
                      let total = 0;

                      if (catStats) {
                        catStats.forEach((val) => (total += val));
                      }

                      // Only render rows with data or keep all but hide zeros?
                      // User said "solo est├® vacio por defecto", implying they want to see the labels but empty values.

                      return (
                        <TableRow key={fullKey} className="hover:bg-muted/5 group">
                          <TableCell className="font-bold text-[10px] py-1.5 sticky left-0 z-10 bg-background border-r text-center shadow-[inset_-1px_0_0_0_hsl(var(--border))] group-hover:bg-muted/10">
                            {item.code}
                          </TableCell>
                          <TableCell
                            className="font-medium text-[10px] py-1.5 sticky left-[50px] z-10 bg-background border-r shadow-[2px_0_5px_-2px_rgba(0,0,0,0.1)] truncate max-w-[300px] group-hover:bg-muted/10"
                            title={item.label}
                          >
                            {item.label}
                          </TableCell>

                          {daysArray.map((day) => {
                            const count = catStats?.get(day) || 0;
                            return (
                              <TableCell
                                key={day}
                                className={`text-center p-0 text-[10px] border-r border-muted/50 ${count > 0 ? 'font-bold text-foreground bg-primary/10' : ''}`}
                              >
                                {count > 0 ? count : ''}
                              </TableCell>
                            );
                          })}
                          <TableCell className="text-center font-bold text-[10px] bg-muted/20 border-l">
                            {total > 0 ? total : ''}
                          </TableCell>
                        </TableRow>
                      );
                    })}
                  </Fragment>
                ))}
                {/* Grand Total Row */}
                <TableRow className="bg-muted/30 font-bold border-t-2">
                  <TableCell className="sticky left-0 z-10 bg-muted/30 border-r text-center">
                    -
                  </TableCell>
                  <TableCell className="sticky left-[50px] z-10 bg-muted/30 border-r shadow-[2px_0_5px_-2px_rgba(0,0,0,0.1)]">
                    TOTAL DIARIO
                  </TableCell>
                  {daysArray.map((day) => {
                    let dailyTotal = 0;
                    if (stats) {
                      stats.forEach((dayMap) => {
                        dailyTotal += dayMap.get(day) || 0;
                      });
                    }
                    return (
                      <TableCell key={day} className="text-center p-0 text-xs border-r">
                        {dailyTotal > 0 ? dailyTotal : ''}
                      </TableCell>
                    );
                  })}
                  <TableCell className="text-center bg-muted/40 border-l">
                    {/* Total Monthly */}
                    {(() => {
                      let grandTotal = 0;
                      if (stats) {
                        stats.forEach((dayMap) => {
                          dayMap.forEach((val) => (grandTotal += val));
                        });
                      }
                      return grandTotal > 0 ? grandTotal : '';
                    })()}
                  </TableCell>
                </TableRow>
              </TableBody>
            </Table>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { useGuardHistory } from '@/hooks/use-guard-history';
import { Button } from '@/components/ui/button';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
  DialogClose,
} from '@/components/ui/dialog';
import { Textarea } from '@/components/ui/textarea';
import { format } from 'date-fns';
import { es } from 'date-fns/locale';
import { Trash2, Eye, Calendar, Clock } from 'lucide-react';
import { Skeleton } from '@/components/ui/skeleton';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from '@/components/ui/alert-dialog';

export default function HistorialPage() {
  const { reports, isLoaded, deleteGuardReport } = useGuardHistory();
  const [selectedReportId, setSelectedReportId] = useState<string | null>(null);
  const [viewDialogOpen, setViewDialogOpen] = useState(false);

  const selectedReport = reports.find((r) => r.id === selectedReportId);

  const handleView = (id: string) => {
    setSelectedReportId(id);
    setViewDialogOpen(true);
  };

  const handleDelete = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    deleteGuardReport(id);
    if (selectedReportId === id) {
      setViewDialogOpen(false);
      setSelectedReportId(null);
    }
  };

  // Sort reports by generatedAt descending (newest first)
  const sortedReports = [...reports].sort(
    (a, b) => new Date(b.generatedAt).getTime() - new Date(a.generatedAt).getTime()
  );

  return (
    <div className="p-4 sm:p-6 lg:p-8">
      <Card className="max-w-5xl mx-auto shadow-lg">
        <CardHeader>
          <CardTitle>Historial de Guardias</CardTitle>
          <CardDescription>Reportes de cierre generados y guardados anteriormente.</CardDescription>
        </CardHeader>
        <CardContent>
          {!isLoaded ? (
            <div className="space-y-4">
              <Skeleton className="h-20 w-full" />
              <Skeleton className="h-20 w-full" />
              <Skeleton className="h-20 w-full" />
            </div>
          ) : reports.length === 0 ? (
            <div className="text-center py-10 text-muted-foreground">
              No hay reportes guardados en el historial.
            </div>
          ) : (
            <div className="grid gap-4">
              {sortedReports.map((report) => (
                <div
                  key={report.id}
                  className="flex flex-col sm:flex-row items-start sm:items-center justify-between p-4 rounded-lg border bg-card hover:bg-accent/50 transition-colors"
                >
                  <div className="space-y-1 mb-4 sm:mb-0">
                    <div className="font-semibold text-lg">
                      {report.summary || 'Reporte sin t├¡tulo'}
                    </div>
                    <div className="flex items-center text-sm text-muted-foreground gap-4">
                      <span className="flex items-center">
                        <Calendar className="h-3 w-3 mr-1" />
                        {format(new Date(report.date), 'PPP', { locale: es })}
                      </span>
                      <span className="flex items-center">
                        <Clock className="h-3 w-3 mr-1" />
                        Generado: {format(new Date(report.generatedAt), 'Pp', { locale: es })}
                      </span>
                      {report.guardGroup && (
                        <span className="px-2 py-0.5 rounded-full bg-primary/10 text-primary text-xs font-medium">
                          {report.guardGroup}
                        </span>
                      )}
                    </div>
                  </div>
                  <div className="flex gap-2 w-full sm:w-auto">
                    <Button
                      variant="outline"
                      size="sm"
                      className="flex-1 sm:flex-none"
                      onClick={() => handleView(report.id)}
                    >
                      <Eye className="h-4 w-4 mr-2" />
                      Ver
                    </Button>

                    <AlertDialog>
                      <AlertDialogTrigger asChild>
                        <Button variant="destructive" size="sm" className="flex-1 sm:flex-none">
                          <Trash2 className="h-4 w-4 mr-2" />
                          Eliminar
                        </Button>
                      </AlertDialogTrigger>
                      <AlertDialogContent>
                        <AlertDialogHeader>
                          <AlertDialogTitle>┬┐Eliminar reporte?</AlertDialogTitle>
                          <AlertDialogDescription>
                            Esta acci├│n no se puede deshacer. El reporte se borrar├í permanentemente
                            del historial de este dispositivo.
                          </AlertDialogDescription>
                        </AlertDialogHeader>
                        <AlertDialogFooter>
                          <AlertDialogCancel>Cancelar</AlertDialogCancel>
                          <AlertDialogAction onClick={(e) => handleDelete(report.id, e as any)}>
                            Eliminar
                          </AlertDialogAction>
                        </AlertDialogFooter>
                      </AlertDialogContent>
                    </AlertDialog>
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      <Dialog open={viewDialogOpen} onOpenChange={setViewDialogOpen}>
        <DialogContent className="max-h-[90vh] max-w-[90vw] sm:max-w-3xl flex flex-col">
          <DialogHeader>
            <DialogTitle>Detalle del Reporte</DialogTitle>
            <DialogDescription>
              {selectedReport && format(new Date(selectedReport.date), 'PPP', { locale: es })}
            </DialogDescription>
          </DialogHeader>
          <div className="flex-1 overflow-y-auto -mx-6 px-6 py-2">
            <Textarea
              readOnly
              value={selectedReport?.content || ''}
              className="w-full h-full min-h-[50vh] text-sm whitespace-pre-wrap font-mono resize-none focus-visible:ring-0"
            />
          </div>
          <DialogFooter>
            <Button
              onClick={() => navigator.clipboard.writeText(selectedReport?.content || '')}
              variant="outline"
            >
              Copiar al portapapeles
            </Button>
            <DialogClose asChild>
              <Button type="button" variant="secondary">
                Cerrar
              </Button>
            </DialogClose>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

