'use client';

import { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { CedulaInput } from '@/components/cedula-input';
import { MultiInput } from '@/components/ui/multi-input';
import type { StaffMember, PersonnelStatus, StaffRole, Department } from '@/types';
import { RANK_OPTIONS, STATUS_OPTIONS } from '@/constants/personnel';
import { toast } from 'sonner';

interface AddEditPersonnelDialogProps {
  open: boolean;
  member: StaffMember | null; // null = add mode
  roles: StaffRole[];
  departments: Department[];
  onSave: (member: Partial<StaffMember>) => void;
  onCancel: () => void;
}

/**
 * Dialog for adding or editing personnel
 *
 * Handles form state, validation, and submission for personnel CRUD operations.
 */
export function AddEditPersonnelDialog({
  open,
  member,
  roles,
  departments,
  onSave,
  onCancel,
}: AddEditPersonnelDialogProps) {
  const isEditMode = member !== null;

  // Form state
  const [name, setName] = useState('');
  const [cedula, setCedula] = useState('');
  const [rank, setRank] = useState('OPC');
  const [roleId, setRoleId] = useState('none');
  const [department, setDepartment] = useState('none');
  const [status, setStatus] = useState<PersonnelStatus>('activo');
  const [specialties, setSpecialties] = useState<string[]>([]);

  // Initialize form with member data when editing
  useEffect(() => {
    if (member) {
      setName(member.name || '');
      setCedula(member.cedula || '');
      setRank(member.rank || 'OPC');
      setRoleId(member.roleId || 'none');
      setDepartment(member.department || 'none');
      setStatus(member.status || 'activo');
      setSpecialties(member.specialties || []);
    } else {
      // Reset form when adding new
      setName('');
      setCedula('');
      setRank('OPC');
      setRoleId('none');
      setDepartment('none');
      setStatus('activo');
      setSpecialties([]);
    }
  }, [member, open]);

  const handleSubmit = () => {
    // Validation
    if (!name.trim()) {
      toast.error('El nombre es obligatorio');
      return;
    }

    // Prepare data
    const data: Partial<StaffMember> = {
      name: name.trim(),
      cedula: cedula || undefined,
      rank,
      roleId: roleId === 'none' ? undefined : roleId,
      department: department === 'none' ? undefined : department,
      status,
      specialties: specialties.length > 0 ? specialties : undefined,
    };

    // Add ID if editing
    if (member) {
      data.id = member.id;
    }

    onSave(data);
    toast.success(isEditMode ? 'Personal actualizado' : 'Personal a├▒adido');
  };

  const handleClose = () => {
    onCancel();
  };

  return (
    <Dialog open={open} onOpenChange={(isOpen) => !isOpen && handleClose()}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{isEditMode ? 'Editar Personal' : 'A├▒adir Personal'}</DialogTitle>
          <DialogDescription>
            {isEditMode
              ? 'Actualiza la informaci├│n del miembro del personal'
              : 'Completa el formulario para a├▒adir un nuevo miembro'}
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {/* Jerarqu├¡a */}
            <div className="space-y-2">
              <Label htmlFor="rank">Jerarqu├¡a *</Label>
              <Select value={rank} onValueChange={setRank}>
                <SelectTrigger id="rank">
                  <SelectValue placeholder="Seleccionar jerarqu├¡a..." />
                </SelectTrigger>
                <SelectContent>
                  {RANK_OPTIONS.map((option) => (
                    <SelectItem key={option.value} value={option.value}>
                      {option.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Nombre */}
            <div className="space-y-2">
              <Label htmlFor="name">Nombre y Apellido *</Label>
              <Input
                id="name"
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="Ej. Juan P├®rez"
                autoComplete="off"
              />
            </div>

            {/* C├®dula */}
            <div className="space-y-2">
              <Label htmlFor="cedula">C├®dula</Label>
              <CedulaInput value={cedula} onChange={setCedula} />
            </div>

            {/* Cargo */}
            <div className="space-y-2">
              <Label htmlFor="role">Cargo Predeterminado</Label>
              <Select value={roleId} onValueChange={setRoleId}>
                <SelectTrigger id="role">
                  <SelectValue placeholder="Seleccionar cargo..." />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="none">Sin cargo asignado</SelectItem>
                  {roles.map((role) => (
                    <SelectItem key={role.name} value={role.name}>
                      {role.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Departamento */}
            <div className="space-y-2">
              <Label htmlFor="department">Departamento</Label>
              <Select value={department} onValueChange={setDepartment}>
                <SelectTrigger id="department">
                  <SelectValue placeholder="Seleccionar departamento..." />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="none">Sin departamento</SelectItem>
                  {departments.map((dept) => (
                    <SelectItem key={dept.id} value={dept.id}>
                      {dept.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Estado */}
            <div className="space-y-2">
              <Label htmlFor="status">Estado</Label>
              <Select value={status} onValueChange={(v) => setStatus(v as PersonnelStatus)}>
                <SelectTrigger id="status">
                  <SelectValue placeholder="Seleccionar estado..." />
                </SelectTrigger>
                <SelectContent>
                  {STATUS_OPTIONS.map((option) => (
                    <SelectItem key={option.value} value={option.value}>
                      {option.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          {/* Especialidades */}
          <div className="space-y-2">
            <Label>Especialidades</Label>
            <MultiInput
              value={specialties}
              onChange={(vals) => setSpecialties(Array.isArray(vals) ? vals : [vals])}
              placeholder="Ej. Primeros Auxilios, Rescate..."
            />
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={handleClose}>
            Cancelar
          </Button>
          <Button onClick={handleSubmit}>{isEditMode ? 'Actualizar' : 'A├▒adir'}</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

'use client';

import { useState, useMemo } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Calendar as CalendarComponent } from '@/components/ui/calendar';
import { CalendarCheck, CheckCircle2, XCircle, Clock } from 'lucide-react';
import type { StaffMember, AttendanceStatus } from '@/types';
import { format } from 'date-fns';
import { es } from 'date-fns/locale';
import { ATTENDANCE_STATUS_CONFIG } from '@/constants/attendance';
import { cn } from '@/lib/utils';

interface AttendanceManagerProps {
  personnel: StaffMember[];
  date: Date;
  onDateChange: (date: Date) => void;
  attendanceRecords: Array<{
    id: string;
    memberId: string;
    date: string;
    status: AttendanceStatus;
    checkInTime?: string;
    note?: string;
  }>;
  onMarkAttendance: (
    memberId: string,
    date: string,
    status: AttendanceStatus,
    checkInTime?: string,
    note?: string
  ) => void;
}

/**
 * Attendance tracking component
 *
 * Allows marking daily attendance for all personnel with status tracking.
 */
export function AttendanceManager({
  personnel,
  date,
  onDateChange,
  attendanceRecords,
  onMarkAttendance,
}: AttendanceManagerProps) {
  const [selectedDate, setSelectedDate] = useState<Date>(date);

  // Get attendance for selected date
  const dateString = format(selectedDate, 'yyyy-MM-dd');
  const todayRecords = useMemo(() => {
    return attendanceRecords.filter((r) => r.date === dateString);
  }, [attendanceRecords, dateString]);

  // Get record for a specific member
  const getRecordForMember = (memberId: string) => {
    return todayRecords.find((r) => r.memberId === memberId);
  };

  // Handle attendance marking
  const handleMark = async (memberId: string, status: AttendanceStatus) => {
    const now = new Date();
    const timeString = format(now, 'HH:mm');
    await onMarkAttendance(memberId, dateString, status, timeString);
  };

  // Calculate stats
  const stats = useMemo(() => {
    const total = personnel.length;
    const presente = todayRecords.filter((r) => r.status === 'presente').length;
    const tarde = todayRecords.filter((r) => r.status === 'tarde').length;
    const ausente = todayRecords.filter((r) => r.status === 'ausente').length;
    const permiso = todayRecords.filter((r) => r.status === 'permiso').length;

    return { total, presente, tarde, ausente, permiso };
  }, [personnel, todayRecords]);

  const handleDateSelect = (newDate: Date | undefined) => {
    if (newDate) {
      setSelectedDate(newDate);
      onDateChange(newDate);
    }
  };

  return (
    <div className="grid lg:grid-cols-[300px_1fr] gap-6">
      {/* Calendar Sidebar */}
      <Card>
        <CardHeader>
          <CardTitle className="text-base">Seleccionar Fecha</CardTitle>
        </CardHeader>
        <CardContent>
          <CalendarComponent
            mode="single"
            selected={selectedDate}
            onSelect={handleDateSelect}
            locale={es}
            className="rounded-md border"
          />

          {/* Stats Summary */}
          <div className="mt-4 space-y-2">
            <div className="text-sm font-medium">Resumen del D├¡a</div>
            <div className="grid grid-cols-2 gap-2 text-xs">
              <div className="flex items-center gap-1">
                <CheckCircle2 className="h-3 w-3 text-green-600" />
                <span>Presente: {stats.presente}</span>
              </div>
              <div className="flex items-center gap-1">
                <Clock className="h-3 w-3 text-amber-600" />
                <span>Tarde: {stats.tarde}</span>
              </div>
              <div className="flex items-center gap-1">
                <XCircle className="h-3 w-3 text-red-600" />
                <span>Ausente: {stats.ausente}</span>
              </div>
              <div className="flex items-center gap-1">
                <CalendarCheck className="h-3 w-3 text-blue-600" />
                <span>Permiso: {stats.permiso}</span>
              </div>
            </div>
            <div className="pt-2 border-t text-sm font-medium">Total: {stats.total}</div>
          </div>
        </CardContent>
      </Card>

      {/* Attendance Grid */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle className="text-base">
              Asistencia - {format(selectedDate, "d 'de' MMMM, yyyy", { locale: es })}
            </CardTitle>
          </div>
        </CardHeader>
        <CardContent>
          <div className="space-y-2">
            {personnel.map((member) => {
              const record = getRecordForMember(member.id);
              const currentStatus = record?.status;

              return (
                <div
                  key={member.id}
                  className="flex items-center justify-between p-3 rounded-lg border bg-card hover:bg-muted/30 transition-colors"
                >
                  <div className="flex-1">
                    <div className="font-medium text-sm">{member.name}</div>
                    <div className="text-xs text-muted-foreground">
                      {member.rank} ÔÇó {member.cedula || 'Sin c├®dula'}
                    </div>
                  </div>

                  {/* Status Buttons */}
                  <div className="flex gap-1">
                    {(Object.keys(ATTENDANCE_STATUS_CONFIG) as AttendanceStatus[]).map((status) => {
                      const config = ATTENDANCE_STATUS_CONFIG[status];
                      const isSelected = currentStatus === status;

                      return (
                        <Button
                          key={status}
                          size="sm"
                          variant={isSelected ? 'default' : 'outline'}
                          className={cn('h-8 px-3 text-xs', isSelected && config.color)}
                          onClick={() => handleMark(member.id, status)}
                        >
                          {config.icon && <config.icon className="h-3 w-3 mr-1" />}
                          {config.label}
                        </Button>
                      );
                    })}
                  </div>

                  {/* Check-in Time */}
                  {record?.checkInTime && (
                    <div className="ml-3 text-xs text-muted-foreground font-mono">
                      {record.checkInTime}
                    </div>
                  )}
                </div>
              );
            })}

            {personnel.length === 0 && (
              <div className="text-center py-8 text-muted-foreground text-sm">
                No hay personal registrado
              </div>
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

/**
 * Example CSV Manager Component
 * Extracted from personal/page.tsx for better organization
 *
 * NOTE: This is a demonstration component showing the refactoring approach.
 * The original personal/page.tsx still contains the full implementation.
 * To use this, you would replace the CSV section in personal/page.tsx with:
 * <CSVManager personnel={personnel} roles={roles} departments={departments} onImport={handleImport} />
 */

'use client';

import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Download, Upload } from 'lucide-react';
import { toast } from 'sonner';
import type { StaffMember, StaffRole, Department } from '@/types';
import { validatePersonnel } from '@/lib/validations/personnel';
import { RANK_OPTIONS } from '@/constants/personnel';
import { generateId } from '@/lib/utils/id';

interface CSVManagerProps {
  personnel: StaffMember[];
  roles: StaffRole[];
  departments: Department[];
  onImport: (members: StaffMember[]) => void;
}

/**
 * CSV Manager for importing and exporting personnel data
 */
export function CSVManager({ personnel, roles, departments, onImport }: CSVManagerProps) {
  const [isImporting, setIsImporting] = useState(false);

  const downloadTemplate = () => {
    const headers = ['Jerarqu├¡a', 'Nombre', 'C├®dula', 'Cargo', 'Departamento'];
    const csvContent = headers.join(',') + '\n';
    const blob = new Blob(['\ufeff' + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'plantilla_personal.csv';
    link.click();
    toast.success('Plantilla descargada');
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsImporting(true);
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const content = e.target?.result as string;
        const lines = content.split('\n');
        const newMembers: StaffMember[] = [];
        const errors: string[] = [];

        // Skip header
        const firstLine = lines[0];
        const startIdx = firstLine && firstLine.toLowerCase().includes('nombre') ? 1 : 0;

        for (let i = startIdx; i < lines.length; i++) {
          const rawLine = lines[i];
          if (!rawLine) continue;
          const line = rawLine.trim();
          if (!line) continue;

          const [rank, name, cedula, role, department] = line.split(',').map((s) => s.trim());

          // Validate using Zod
          const validation = validatePersonnel({
            name,
            cedula,
            rank,
            role,
            department,
          });

          if (!validation.success) {
            errors.push(`Fila ${i + 1}: ${validation.error}`);
            continue;
          }

          // Check role exists
          if (role && !roles.find((r) => r.name.toLowerCase() === role.toLowerCase())) {
            errors.push(`Fila ${i + 1}: Cargo "${role}" no existe.`);
            continue;
          }

          // Check department exists
          if (
            department &&
            !departments.find((d) => d.name.toLowerCase() === department.toLowerCase())
          ) {
            errors.push(`Fila ${i + 1}: Departamento "${department}" no existe.`);
            continue;
          }

          newMembers.push({
            id: generateId('personnel'),
            ...validation.data,
            status: 'activo',
          });
        }

        if (errors.length > 0) {
          toast.error(`Errores encontrados:\n${errors.slice(0, 3).join('\n')}`);
        } else if (newMembers.length > 0) {
          onImport(newMembers);
          toast.success(`${newMembers.length} funcionarios importados`);
        }
      } catch (error) {
        toast.error('Error al procesar el archivo CSV');
      } finally {
        setIsImporting(false);
        event.target.value = '';
      }
    };

    reader.readAsText(file, 'UTF-8');
  };

  const handleExport = () => {
    const headers = ['Jerarqu├¡a', 'Nombre', 'C├®dula', 'Cargo', 'Departamento'];
    const rows = personnel.map((p) => [
      p.rank || '',
      p.name,
      p.cedula || '',
      '', // Role would need to be looked up
      p.department || '',
    ]);

    const csvContent = [headers, ...rows].map((row) => row.join(',')).join('\n');

    const blob = new Blob(['\ufeff' + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `personal_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
    toast.success('Datos exportados');
  };

  return (
    <div className="flex gap-2">
      <Button variant="outline" size="sm" onClick={downloadTemplate}>
        <Download className="mr-2 h-4 w-4" />
        Plantilla
      </Button>
      <label>
        <Button variant="outline" size="sm" disabled={isImporting} asChild>
          <span>
            <Upload className="mr-2 h-4 w-4" />
            {isImporting ? 'Importando...' : 'Importar CSV'}
          </span>
        </Button>
        <input
          type="file"
          accept=".csv"
          onChange={handleFileUpload}
          className="hidden"
          disabled={isImporting}
        />
      </label>
      <Button variant="outline" size="sm" onClick={handleExport}>
        <Download className="mr-2 h-4 w-4" />
        Exportar
      </Button>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { GuardStaffEditor } from '@/components/guard-staff-editor';
import { PlusCircle, Trash2, ShieldCheck, ExternalLink } from 'lucide-react';
import type { Guard, StaffMember, StaffRole, Department } from '@/types';
import { toast } from 'sonner';
import Link from 'next/link';

interface GuardAssignmentPanelProps {
  guards: Guard[];
  personnel: StaffMember[];
  roles: StaffRole[];
  onGuardUpdate: (guards: Guard[]) => void;
}

/**
 * Quick guard assignment panel
 *
 * Simplified interface for managing guard assignments.
 * For full features, users can navigate to the Guardias page.
 */
export function GuardAssignmentPanel({
  guards,
  personnel,
  roles,
  onGuardUpdate,
}: GuardAssignmentPanelProps) {
  const [selectedGuardId, setSelectedGuardId] = useState<string>(guards[0]?.id || '');
  const [newGuardName, setNewGuardName] = useState('');

  const selectedGuard = guards.find((g) => g.id === selectedGuardId);

  const handleAddGuard = async () => {
    if (!newGuardName.trim()) {
      toast.error('El nombre de la guardia es obligatorio');
      return;
    }

    const guardId = newGuardName.toUpperCase();
    if (guards.find((g) => g.id === guardId)) {
      toast.error('Esta guardia ya existe');
      return;
    }

    const newGuard: Guard = {
      id: guardId,
      staff: {},
    };

    const updatedGuards = [...guards, newGuard].sort((a, b) => a.id.localeCompare(b.id));

    await onGuardUpdate(updatedGuards);
    setSelectedGuardId(guardId);
    setNewGuardName('');
    toast.success(`Guardia ${guardId} creada`);
  };

  const handleRemoveGuard = async (guardId: string) => {
    if (window.confirm(`┬┐Eliminar Guardia "${guardId}"?`)) {
      const updatedGuards = guards.filter((g) => g.id !== guardId);
      await onGuardUpdate(updatedGuards);

      // Select first guard if current was deleted
      if (selectedGuardId === guardId && updatedGuards.length > 0) {
        setSelectedGuardId(updatedGuards[0]?.id || '');
      }

      toast.success('Guardia eliminada');
    }
  };

  const handleStaffUpdate = async (updatedGuard: Guard | Department) => {
    await onGuardUpdate(
      guards.map((g) => (g.id === updatedGuard.id ? (updatedGuard as Guard) : g))
    );
  };

  return (
    <div className="space-y-6">
      {/* Guard Management */}
      <div className="grid md:grid-cols-[300px_1fr] gap-6">
        {/* Sidebar */}
        <Card>
          <CardHeader>
            <CardTitle className="text-base">Guardias</CardTitle>
            <CardDescription>Selecciona o crea una guardia</CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            {/* Add New Guard */}
            <div className="space-y-2">
              <Label htmlFor="new-guard">Nueva Guardia</Label>
              <div className="flex gap-2">
                <Input
                  id="new-guard"
                  value={newGuardName}
                  onChange={(e) => setNewGuardName(e.target.value)}
                  placeholder="Ej. A, B, C..."
                  className="uppercase"
                  maxLength={10}
                />
                <Button size="icon" onClick={handleAddGuard}>
                  <PlusCircle className="h-4 w-4" />
                </Button>
              </div>
            </div>

            {/* Guard List */}
            <div className="space-y-1">
              <Label>Guardias Existentes</Label>
              {guards.map((guard) => (
                <div
                  key={guard.id}
                  className="flex items-center justify-between p-2 rounded hover:bg-muted"
                >
                  <Button
                    variant={selectedGuardId === guard.id ? 'default' : 'ghost'}
                    size="sm"
                    className="flex-1 justify-start"
                    onClick={() => setSelectedGuardId(guard.id)}
                  >
                    <ShieldCheck className="h-3 w-3 mr-2" />
                    Guardia {guard.id}
                  </Button>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleRemoveGuard(guard.id)}
                    className="text-destructive h-8 w-8 p-0"
                  >
                    <Trash2 className="h-3 w-3" />
                  </Button>
                </div>
              ))}

              {guards.length === 0 && (
                <div className="text-xs text-muted-foreground text-center py-4">
                  No hay guardias creadas
                </div>
              )}
            </div>
          </CardContent>
        </Card>

        {/* Main Content - Guard Staff Editor */}
        {selectedGuard ? (
          <Card>
            <CardHeader>
              <CardTitle>Guardia {selectedGuard.id}</CardTitle>
              <CardDescription>Asigna personal a esta guardia</CardDescription>
            </CardHeader>
            <CardContent>
              <GuardStaffEditor
                guard={selectedGuard}
                onUpdate={handleStaffUpdate}
                roles={roles}
                onSave={() => toast.success('Personal de guardia actualizado')}
                scopeId="OPERATIONS"
              />
            </CardContent>
          </Card>
        ) : (
          <Card>
            <CardContent className="flex items-center justify-center h-64">
              <div className="text-center text-muted-foreground">
                <ShieldCheck className="h-12 w-12 mx-auto mb-3 opacity-20" />
                <p>Selecciona o crea una guardia para comenzar</p>
              </div>
            </CardContent>
          </Card>
        )}
      </div>
    </div>
  );
}

