          <p className="text-muted-foreground">Cargando datos...</p>
        </div>
        <DataTableSkeleton rows={10} columns={5} />
      </div>
    );
  }

  // Handlers
  const handleEdit = (member: StaffMember) => {
    setEditingMember(member);
    setIsDialogOpen(true);
  };

  const handleAddNew = () => {
    setEditingMember(null);
    setIsDialogOpen(true);
  };

  const handleSave = async (data: Partial<StaffMember>) => {
    // Validation: C├®dula duplicate
    if (data.cedula && isCedulaDuplicate(data.cedula, editingMember?.id)) {
      toast.error('Ya existe una persona registrada con esta c├®dula');
      return;
    }

    if (editingMember) {
      // Update existing
      await updateMember(editingMember.id, data);
      toast.success('Cambios guardados');
    } else {
      // Add new - ensure name is provided
      if (data.name) {
        const newMemberData: Omit<StaffMember, 'id'> = {
          name: data.name,
          cedula: data.cedula || '',
          rank: data.rank || '',
          department: data.department || '',
        };
        await addMember(newMemberData);
        toast.success('Personal a├▒adido');
      }
    }
    setIsDialogOpen(false);
    setEditingMember(null);
  };

  const handleCancel = () => {
    setIsDialogOpen(false);
    setEditingMember(null);
  };

  const handleDelete = (id: string) => {
    removeMember(id);
    setSelectedIds((prev) => prev.filter((selectedId) => selectedId !== id));
    toast.success('Personal eliminado');
  };

  const handleBulkDelete = () => {
    if (selectedIds.length === 0) return;
    removeMembers(selectedIds);
    setSelectedIds([]);
    setIsBulkDeleteConfirmOpen(false);
    toast.success(`${selectedIds.length} personas eliminadas`);
  };

  const handleViewHistory = (member: StaffMember) => {
    setViewHistoryMember(member);
    setIsHistoryDialogOpen(true);
  };



  return (
    <div className="container mx-auto p-8 space-y-6">
      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-3xl font-bold mb-2">Personal</h1>
          <p className="text-muted-foreground">
            Administra el personal, sus cargos y la conformaci├│n de las guardias.
          </p>
        </div>
        {selectedIds.length > 0 && (
          <Button
            variant="destructive"
            onClick={() => setIsBulkDeleteConfirmOpen(true)}
            className="shadow-sm"
          >
            <Trash2 className="mr-2 h-4 w-4" />
            Borrar seleccionados ({selectedIds.length})
          </Button>
        )}
      </div>

      {/* Main Tabs */}
      <Tabs defaultValue="personnel" className="space-y-6">
        <div className="overflow-x-auto pb-1 -mx-4 px-4 sm:mx-0 sm:px-0">
          <TabsList className="flex w-max sm:grid sm:w-full sm:grid-cols-4 sm:max-w-2xl">
            <TabsTrigger value="personnel" className="flex items-center gap-1.5 px-3">
              <User className="h-3.5 w-3.5" />
              <span className="text-xs sm:text-sm">Funcionarios</span>
            </TabsTrigger>
            <TabsTrigger value="structure" className="flex items-center gap-1.5 px-3">
              <LayoutGrid className="h-3.5 w-3.5" />
              <span className="text-xs sm:text-sm">Estructura</span>
            </TabsTrigger>
            <TabsTrigger value="guards" className="flex items-center gap-1.5 px-3">
              <ShieldCheck className="h-3.5 w-3.5" />
              <span className="text-xs sm:text-sm">Guardias</span>
            </TabsTrigger>
            <TabsTrigger value="attendance" className="flex items-center gap-1.5 px-3">
              <CalendarCheck className="h-3.5 w-3.5" />
              <span className="text-xs sm:text-sm">Asistencia</span>
            </TabsTrigger>
          </TabsList>
        </div>

        {/* Personnel Tab */}
        <TabsContent value="personnel" className="space-y-6 mt-0">
          <div className="flex flex-wrap items-center justify-end gap-2">
            <Button size="sm" onClick={handleAddNew} className="h-8 text-xs shadow-sm">
              <PlusCircle className="mr-1.5 h-3.5 w-3.5" />
              Personal
            </Button>
          </div>

          <Card>
            <CardContent className="pt-6">
              <PersonnelTable
                personnel={personnel}
                onEdit={handleEdit}
                onDelete={handleDelete}
                onViewHistory={handleViewHistory}
                selectedIds={selectedIds}
                onSelectionChange={setSelectedIds}
              />
            </CardContent>
          </Card>
        </TabsContent>

        {/* Structure Tab */}
        <TabsContent value="structure">
          <StructureManager
            roles={roles}
            departments={departments}
            onRolesChange={saveRoles}
            onDepartmentsChange={saveDepartments}
            onSave={() => { }}
          />
        </TabsContent>

        {/* Guards Tab */}
        <TabsContent value="guards">
          <GuardAssignmentPanel
            guards={guards}
            personnel={personnel}
            roles={roles}
            onGuardUpdate={saveGuards}
          />
        </TabsContent>

        {/* Attendance Tab */}
        <TabsContent value="attendance">
          <AttendanceManager
            personnel={personnel}
            date={attendanceDate}
            onDateChange={setAttendanceDate}
            attendanceRecords={records}
            onMarkAttendance={markAttendance}
          />
        </TabsContent>
      </Tabs>

      {/* Add/Edit Dialog */}
      <AddEditPersonnelDialog
        open={isDialogOpen}
        member={editingMember}
        roles={roles}
        departments={departments}
        onSave={handleSave}
        onCancel={handleCancel}
      />

      <ConfirmDialog
        open={isBulkDeleteConfirmOpen}
        onOpenChange={setIsBulkDeleteConfirmOpen}
        title="┬┐Eliminar personal seleccionado?"
        message={`Est├ís a punto de eliminar a ${selectedIds.length} personas. Esta acci├│n no se puede deshacer.`}
        onConfirm={handleBulkDelete}
        variant="destructive"
      />
      <PersonnelHistoryDialog
        member={viewHistoryMember}
        isOpen={isHistoryDialogOpen}
        onClose={() => {
          setIsHistoryDialogOpen(false);
          setViewHistoryMember(null);
        }}
      />
    </div>
  );
}

export default function PersonnelPage() {
  return (
    <FeatureErrorBoundary featureName="Personal">
      <PersonnelPageContent />
    </FeatureErrorBoundary>
  );
}

'use client';

import { useState, useRef, useMemo } from 'react';
import Link from 'next/link';
import { Button } from '@/components/ui/button';
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { ScrollArea } from '@/components/ui/scroll-area';
import {
  Upload,
  FileText,
  Trash2,
  HelpCircle,
  PlusCircle,
  AlertTriangle,
  Download,
  Pencil,
  ChevronLeft,
} from 'lucide-react';
import { useTemplates } from '@/hooks/use-templates';
import type { Template } from '@/types';
import { TemplateEditor } from '@/components/template/template-editor';
import { cn } from '@/lib/utils';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogClose,
} from '@/components/ui/dialog';
import { Switch } from '@/components/ui/switch';
import { Label } from '@/components/ui/label';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';

import { parseTemplate } from '@/lib/template-parser';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';
import { TemplateBuilder } from '@/components/template/template-builder';
import { Badge } from '@/components/ui/badge';
import { generateId } from '@/lib/utils/id';

export default function PlantillasPage() {
  const {
    templates,
    addTemplate,
    removeTemplate,
    updateTemplate,
    configs,
    updateTemplateConfig,
    toggleTemplateActive,
    clearAllTemplates,
  } = useTemplates();
  const [selectedTemplateId, setSelectedTemplateId] = useState<string | null>(null);
  const [templateToDelete, setTemplateToDelete] = useState<string | null>(null);
  const [isInfoDialogOpen, setIsInfoDialogOpen] = useState(false);
  const [editingTemplate, setEditingTemplate] = useState<Template | null>(null);
  const [activeTab, setActiveTab] = useState('builder');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        const content = e.target?.result as string;
        const newTemplate: Template = {
          id: generateId('template'),
          name: file.name.replace(/\.txt$/, ''),
          content,
          type: 'normal',
        };
        addTemplate(newTemplate);
      };
      reader.readAsText(file);
    }
  };

  const handleUploadClick = () => {
    fileInputRef.current?.click();
  };

  const handleDeleteClick = (e: React.MouseEvent, templateId: string) => {
    e.stopPropagation();
    setTemplateToDelete(templateId);
  };

  const handleDownloadTemplate = (e: React.MouseEvent, template: Template) => {
    e.stopPropagation();
    const blob = new Blob([template.content], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `${template.name}.txt`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleEditContentClick = (e: React.MouseEvent, template: Template) => {
    e.stopPropagation();
    setEditingTemplate(template);
    setActiveTab('builder');
  };

  const handleConfirmDelete = () => {
    if (!templateToDelete) return;

    if (templateToDelete === 'ALL') {
      clearAllTemplates();
      setSelectedTemplateId(null);
    } else {
      if (selectedTemplateId === templateToDelete) {
        setSelectedTemplateId(null);
      }
      removeTemplate(templateToDelete);
    }
    setTemplateToDelete(null);
  };

  const handleUpdateTemplateContent = (id: string, updates: Partial<Template>) => {
    const currentTemplate = templates.find((t) => t.id === id);
    if (currentTemplate) {
      updateTemplate({ ...currentTemplate, ...updates });
    }
    setEditingTemplate(null);
  };

  const handleCancelEdit = () => {
    setEditingTemplate(null);
    // Optional: switch back to list if desired, but maybe user wants to create new one?
    // let's stay in builder but reset
  };

  const selectedTemplate = templates.find((t) => t.id === selectedTemplateId) || null;

  return (
    <>
      <div className="flex flex-col h-[calc(100vh-3.5rem)] sm:h-screen bg-muted/30 overflow-hidden">
        <Tabs
          value={activeTab}
          onValueChange={setActiveTab}
          className="flex-1 flex flex-col min-h-0"
        >
          <div className="p-4 sm:px-6 sm:py-4 border-b bg-background flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
            <div className="flex flex-col">
              <h1 className="text-xl font-bold">Plantillas</h1>
              <p className="text-sm text-muted-foreground">
                Gestiona y construye plantillas para reportes.
              </p>
            </div>
            <TabsList className="w-full sm:w-auto">
              <TabsTrigger value="builder" className="flex-1 sm:flex-initial">
                Constructor
              </TabsTrigger>
              <TabsTrigger value="editor" className="flex-1 sm:flex-initial">
                Gestionar
              </TabsTrigger>
            </TabsList>
          </div>

          <TabsContent
            value="builder"
            className="flex-1 h-full min-h-0 m-0 p-0 overflow-hidden data-[state=active]:flex data-[state=active]:flex-col"
          >
            <div className="flex-1 flex flex-col min-h-0 overflow-hidden p-4 sm:p-6 lg:p-8">
              <TemplateBuilder
                onOpenInfoDialog={() => setIsInfoDialogOpen(true)}
                initialTemplate={editingTemplate}
                onUpdate={handleUpdateTemplateContent}
                onAdd={addTemplate}
                onCancel={handleCancelEdit}
              />
            </div>
          </TabsContent>

          <TabsContent
            value="editor"
            className="flex-1 h-full min-h-0 m-0 p-0 overflow-hidden data-[state=active]:flex data-[state=active]:flex-col"
          >
            <div className="flex flex-1 min-h-0 overflow-hidden h-full sm:p-4 gap-6">
              <aside
                className={cn(
                  'h-full w-full sm:w-96 flex-col bg-card flex sm:rounded-lg border sm:shadow-sm shrink-0 min-h-0',
                  selectedTemplateId ? 'hidden sm:flex' : 'flex'
                )}
              >
                <CardHeader className="p-4 sm:p-6">
                  <CardTitle>Plantillas</CardTitle>
                  <CardDescription>Sube y gestiona tus plantillas de reportes.</CardDescription>
                </CardHeader>
                <div className="p-4 pt-0 space-y-2">
                  <Button className="w-full" onClick={handleUploadClick}>
                    <Upload className="mr-2 h-4 w-4" />
                    Subir Plantilla (.txt)
                  </Button>
                  <input
                    type="file"
                    ref={fileInputRef}
                    onChange={handleFileChange}
                    className="hidden"
                    accept=".txt"
                  />
                </div>
                <ScrollArea className="flex-1">
                  <TooltipProvider>
                    <div className="space-y-1 p-4 pt-0">
                      {templates.map((template, index) => {
                        const { layout, fieldNames, errors } = parseTemplate(template.content);
                        const isValid =
                          (layout.length > 0 || fieldNames.size > 0) && errors.length === 0;

                        return (
                          <div
                            key={`${template.id}-${index}`}
                            className={cn(
                              'group w-full flex items-center justify-between rounded-md p-3 text-left transition-colors hover:bg-muted',
                              selectedTemplateId === template.id && 'bg-muted'
                            )}
                          >
                            <div
                              className="flex items-center gap-3 flex-grow cursor-pointer"
                              onClick={() => setSelectedTemplateId(template.id)}
                            >
                              <FileText
                                className={cn(
                                  'h-4 w-4 text-primary',
                                  !isValid && 'text-destructive'
                                )}
                              />
                              <span className="flex-1 font-medium">{template.name}</span>
                              {!isValid && (
                                <AlertTriangle className="h-4 w-4 text-destructive flex-shrink-0" />
                              )}
                            </div>
                            <div className="flex items-center gap-1 flex-shrink-0">
                              <Tooltip>
                                <TooltipTrigger asChild>
                                  <Button
                                    variant="ghost"
                                    size="icon"
                                    className="h-7 w-7 text-muted-foreground hover:text-foreground"
                                    onClick={(e) => handleEditContentClick(e, template)}
                                    aria-label={`Editar contenido de ${template.name}`}
                                  >
                                    <Pencil className="h-4 w-4" />
                                  </Button>
                                </TooltipTrigger>
                                <TooltipContent>
                                  <p>Editar Contenido</p>
                                </TooltipContent>
                              </Tooltip>
                              <Tooltip>
                                <TooltipTrigger asChild>
                                  <Button
                                    variant="ghost"
                                    size="icon"
                                    className="h-7 w-7 text-muted-foreground hover:text-foreground"
                                    onClick={(e) => handleDownloadTemplate(e, template)}
                                    aria-label={`Exportar plantilla ${template.name}`}
                                  >
                                    <Download className="h-4 w-4" />
                                  </Button>
                                </TooltipTrigger>
                                <TooltipContent>
                                  <p>Exportar</p>
                                </TooltipContent>
                              </Tooltip>
                              <Tooltip>
                                <TooltipTrigger asChild>
                                  <div className="flex items-center">
                                    <Switch
                                      checked={template.isActive && isValid}
                                      onCheckedChange={() => toggleTemplateActive(template.id)}
                                      disabled={!isValid}
                                      onClick={(e) => e.stopPropagation()}
                                      aria-label={`Activar/Desactivar plantilla ${template.name}`}
                                    />
                                  </div>
                                </TooltipTrigger>
                                <TooltipContent className="max-w-xs">
                                  {isValid ? (
                                    <p>Activar/Desactivar</p>
                                  ) : (
                                    <div className="text-xs">
                                      <p className="font-semibold mb-1">Plantilla inv├ílida:</p>
                                      <ul className="list-disc pl-3 space-y-1">
                                        {errors.length > 0 ? (
                                          errors.slice(0, 3).map((err, i) => <li key={i}>{err}</li>)
                                        ) : (
                                          <li>La plantilla est├í vac├¡a o mal formada.</li>
                                        )}
                                        {errors.length > 3 && (
                                          <li>...y {errors.length - 3} m├ís.</li>
                                        )}
                                      </ul>
                                    </div>
                                  )}
                                </TooltipContent>
                              </Tooltip>
                              <Tooltip>
                                <TooltipTrigger asChild>
                                  <Button
                                    variant="ghost"
                                    size="icon"
                                    className="h-7 w-7 text-destructive"
                                    onClick={(e) => handleDeleteClick(e, template.id)}
                                    aria-label={`Eliminar plantilla ${template.name}`}
                                  >
                                    <Trash2 className="h-4 w-4" />
                                  </Button>
                                </TooltipTrigger>
                                <TooltipContent>
                                  <p>Eliminar</p>
                                </TooltipContent>
                              </Tooltip>
                            </div>
                          </div>
                        );
                      })}
                      {templates.length === 0 && (
                        <div className="p-4 text-center text-sm text-muted-foreground">
                          No has subido ninguna plantilla.
                        </div>
                      )}
                    </div>
                  </TooltipProvider>
                </ScrollArea>
              </aside>

              <main
                className={cn(
                  'flex-1 overflow-hidden',
                  !selectedTemplateId ? 'hidden sm:block' : 'block'
                )}
              >
                {selectedTemplateId && (
                  <div className="sm:hidden border-b p-2 bg-card">
                    <Button variant="ghost" size="sm" onClick={() => setSelectedTemplateId(null)}>
                      <ChevronLeft className="mr-2 h-4 w-4" />
                      Volver a la lista
                    </Button>
                  </div>
                )}
                {selectedTemplate ? (
                  <TemplateEditor
                    key={selectedTemplate.id}
                    template={selectedTemplate}
                    config={
                      (configs[selectedTemplate.id] || {
                        fields: {},
                        sections: [],
                        layout: [],
                      }) as any
                    }
                    onConfigChange={(config) => updateTemplateConfig(selectedTemplate.id, config)}
                    onTemplateChange={updateTemplate}
                  />
                ) : (
                  <Card className="h-full flex items-center justify-center sm:rounded-lg">
                    <CardContent className="text-center space-y-4 p-12">
                      <FileText className="h-16 w-16 mx-auto text-muted-foreground/50" />
                      <div>
                        <h3 className="text-lg font-semibold">No hay plantilla seleccionada</h3>
                        <p className="text-sm text-muted-foreground mt-2">
                          Selecciona una plantilla de la lista o sube una nueva para comenzar.
                        </p>
                      </div>
                    </CardContent>
                  </Card>
                )}
              </main>
            </div>
          </TabsContent>
        </Tabs>
      </div>

      <AlertDialog
        open={!!templateToDelete}
        onOpenChange={(open) => !open && setTemplateToDelete(null)}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>┬┐Est├ís seguro?</AlertDialogTitle>
            <AlertDialogDescription>
              {templateToDelete === 'ALL'
                ? 'Esta acci├│n no se puede deshacer. Se eliminar├ín permanentemente TODAS las plantillas y sus configuraciones.'
                : 'Esta acci├│n no se puede deshacer. La plantilla ser├í eliminada permanentemente.'}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel onClick={() => setTemplateToDelete(null)}>
              Cancelar
            </AlertDialogCancel>
            <AlertDialogAction onClick={handleConfirmDelete}>S├¡, eliminar</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      <Dialog open={isInfoDialogOpen} onOpenChange={setIsInfoDialogOpen}>
        <DialogContent className="sm:max-w-2xl">
          <DialogHeader>
            <DialogTitle>Gu├¡a para Crear Plantillas de Texto</DialogTitle>
            <DialogDescription>
              Usa esta sintaxis en tus archivos `.txt` para crear formularios din├ímicos y flexibles.
            </DialogDescription>
          </DialogHeader>
          <div className="py-4 space-y-6 text-sm max-h-[70vh] overflow-y-auto pr-4">
            <div>
              <h4 className="font-semibold text-base mb-2">1. Lo B├ísico: Campos de Formulario</h4>
              <p>
                Para definir un campo que el usuario deber├í rellenar, enci├®rralo entre llaves{' '}
                <code>{`{ }`}</code>. Cada campo que definas se convertir├í en un elemento del
                formulario (un campo de texto, un selector de fecha, etc.).
              </p>
              <div className="mt-2 p-3 bg-muted rounded-md text-xs font-mono">
                <p>
                  Siendo las {`{Hora}`}, se present├│ una novedad en {`{Lugar}`}.
                </p>
              </div>
            </div>
            <div>
              <h4 className="font-semibold text-base mb-2">2. Organizando con Secciones</h4>
              <p>
                Puedes agrupar campos y organizar la estructura de tu formulario y reporte usando
                secciones. Se definen con corchetes <code>[ ]</code>.
              </p>

              <div className="mt-4 space-y-4">
                <div>
                  <h5 className="font-medium mb-1">a) Secci├│n Simple (T├¡tulo y Campos)</h5>
                  <p className="text-muted-foreground">
                    ├Üsala para agrupar campos bajo un mismo t├¡tulo.
                  </p>
                  <div className="mt-2 p-3 bg-muted rounded-md text-xs font-mono">
                    <p>
                      ["Datos de la Unidad" {`{Unidad a Cargo}`} {`{PAB}`}]
                    </p>
                  </div>
                  <p className="mt-2 text-xs text-muted-foreground">
                    <strong>Tip:</strong> Si omites los campos y dejas solo el t├¡tulo,{' '}
                    <code>["T├¡tulo Informativo"]</code>, la secci├│n actuar├í como un simple
                    encabezado en el formulario y en el reporte final (ej:{' '}
                    <span className="font-mono">- *T├¡tulo Informativo*</span>).
                  </p>
                </div>

                <div>
                  <h5 className="font-medium mb-1">b) Secci├│n Repetible (Listas)</h5>
                  <p className="text-muted-foreground">
                    A├▒ade un asterisco <code>*</code> despu├®s de la secci├│n para que los usuarios
                    puedan a├▒adir m├║ltiples entradas de esa secci├│n (como una lista de veh├¡culos o
                    personal).
                  </p>
                  <div className="mt-2 p-3 bg-muted rounded-md text-xs font-mono">
                    <p>
                      ["Veh├¡culos Involucrados"]* {`{Placa}`} {`{Modelo}`}
                    </p>
                  </div>
                </div>

                <div>
                  <h5 className="font-medium mb-1">c) Separador Visual</h5>
                  <p className="text-muted-foreground">
                    Para crear una l├¡nea de separaci├│n en el formulario y un espacio en el reporte,
                    usa comillas vac├¡as.
                  </p>
                  <div className="mt-2 p-3 bg-muted rounded-md text-xs font-mono">
                    <p>[""]</p>
                  </div>
                </div>
              </div>
            </div>
            <div>
              <h4 className="font-semibold text-base mb-2">
                3. Avanzado: Secciones Repetibles con T├¡tulos Inteligentes
              </h4>
              <p>
                Esta es la forma m├ís potente de crear secciones repetibles, ideal para cuando el
                t├¡tulo debe cambiar seg├║n la cantidad de elementos (ej. "1 Lesionado" vs. "M├║ltiples
                Lesionados").
              </p>
              <div className="mt-2 p-3 bg-muted rounded-md text-xs font-mono whitespace-pre-wrap">
                {`[singular="DATOS DEL LESIONADO" plural="DATOS DE LOS LESIONADOS" sub="Lesionado"]*
- Nombre y Apellido: {Nombre y apellido}
- C├®dula: {C├®dula}
`}
              </div>
              <p className="mt-2 text-sm text-muted-foreground">As├¡ funciona cada parte:</p>
              <ul className="list-disc list-inside mt-2 space-y-1 text-sm text-muted-foreground">
                <li>
                  <code>singular="..."</code>: T├¡tulo principal si hay <strong>un solo</strong>{' '}
                  elemento. Se formatea como: `- *T├ìTULO*`.
                </li>
                <li>
                  <code>plural="..."</code>: T├¡tulo principal si hay <strong>m├ís de un</strong>{' '}
                  elemento.
                </li>
                <li>
                  <code>sub="..."</code>: Subt├¡tulo para <strong>cada</strong> elemento individual.
                  Si se define, se numera autom├íticamente (ej. `- *Lesionado #01*`). Si se omite, no
                  se a├▒ade ning├║n subt├¡tulo por elemento.
                </li>
                <li>
                  Si no se a├▒aden elementos, toda la secci├│n (t├¡tulos y contenido) se ocultar├í del
                  reporte final.
                </li>
              </ul>
            </div>
            <div>
              <h4 className="font-semibold text-base mb-2">
                4. Avanzado: Especificar Tipos y Opciones
              </h4>
              <p>
                Puedes definir el tipo y las opciones de un campo directamente en la plantilla para
                mayor control.
              </p>
              <ul className="list-disc list-inside mt-2 space-y-4 text-sm text-muted-foreground">
                <li>
                  <strong>Tipos de Campo</strong>: Usa la sintaxis{' '}
                  <code>{`{NombreCampo:tipo}`}</code>.
                  <ul className="list-disc list-inside pl-6 mt-2 space-y-1">
                    <li>
                      <code>{`{Descripci├│n:textarea}`}</code>
                    </li>
                    <li>
                      <code>{`{Fecha de Cierre:date}`}</code>
                    </li>
                    <li>
                      <code>{`{Hora de Llamada:time-hlv}`}</code>
                    </li>
                    <li>
                      <code>{`{Motivo:dropdown}`}</code>
                    </li>
                  </ul>
                  <p className="mt-2">
                    Tipos disponibles: <code>text</code>, <code>textarea</code>, <code>date</code>,{' '}
                    <code>time-hlv</code>, <code>dropdown</code>.
                  </p>
                </li>
                <li>
                  <strong>Opciones para Dropdown</strong>: Define las opciones directamente en la
                  plantilla.
                  <div className="mt-2 p-3 bg-muted rounded-md text-xs font-mono whitespace-pre-wrap">
                    {`{Motivo:dropdown(Llamada Radio=Se recibe llamada v├¡a radio...|Llamada Telef├│nica=Se recibe llamada telef├│nica...)}`}
