                <p>
                  Una vez que subas tu plantilla, selecci├│nala en la lista. En el panel de la
                  derecha podr├ís configurar cualquier detalle que no hayas especificado en el
                  archivo `.txt`, como el "campo de destino" para los dropdowns.
                </p>
              </div>
              <div>
                <h4 className="font-semibold text-base mb-2">M├ís Informaci├│n</h4>
                <p className="text-muted-foreground">
                  Para una explicaci├│n detallada sobre c├│mo la aplicaci├│n guarda los datos y
                  renderiza los reportes, consulta la p├ígina de{' '}
                  <Link
                    href="/documentation"
                    className="text-primary underline hover:text-primary/80"
                    onClick={() => setIsInfoDialogOpen(false)}
                  >
                    Documentaci├│n
                  </Link>
                  .
                </p>
              </div>
            </div>
          </div>
          <DialogFooter>
            <DialogClose asChild>
              <Button type="button">Entendido</Button>
            </DialogClose>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

