'use client';

import { useState, useMemo, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
  DialogClose,
} from '@/components/ui/dialog';
import { useReports } from '@/hooks/use-reports';
import { useGuardHistory } from '@/hooks/use-guard-history';
import { Skeleton } from '@/components/ui/skeleton';
import { findValueInFormData } from '@/lib/report-sorter';
import { getReportCategory } from '@/lib/statistics-utils';
import { ScrollArea } from '@/components/ui/scroll-area';
import { useGuards } from '@/hooks/use-guards';
import { useSettings } from '@/hooks/use-settings';
import { useRoles } from '@/hooks/use-roles';
import { usePersonnel } from '@/hooks/use-personnel';
import { useTemplates } from '@/hooks/use-templates';
import { renderFinalReport } from '@/lib/template-parser';
import { format } from 'date-fns';
import type { Report, StaffMember } from '@/types';
import { DatePicker } from '@/components/date-picker';
import { TimeHlvInput } from '@/components/time-hlv-input';
import { PlusCircle, Trash2, Calculator, FileText, Save } from 'lucide-react';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { DEFAULT_STATISTICS_CATEGORIES } from '@/constants/statistics';
import { LEADER_ROLES } from '@/constants/roles';
import { PERSONNEL_STATUS } from '@/constants/personnel';
import { ATTENDANCE_STATUS } from '@/constants/attendance';
import { generateId } from '@/lib/utils/id';

interface ManualNovedad {
  id: string;
  date: Date;
  time: string;
  text: string;
}

const formatStaffMemberForReport = (member: StaffMember, showCedula: boolean): string => {
  const rank = member.rank ? `${member.rank} ` : '';
  if (showCedula && member.cedula) {
    return `${rank}${member.name} ${member.cedula}`;
  }
  return `${rank}${member.name}`;
};

const findInsensitive = (obj: Record<string, string>, key: string): string => {
  const keyLower = key.toLowerCase();
  const foundKey = Object.keys(obj).find((k) => k.toLowerCase() === keyLower);
  return foundKey ? (obj[foundKey] ?? '') : '';
};

export default function ReporteFinalPage() {
  const { reports, isLoaded: reportsLoaded, getLatestReports, clearAllReports } = useReports();
  const { guards, isLoaded: guardsLoaded } = useGuards();
  const { settings, saveSettings, isLoaded: settingsLoaded } = useSettings();
  const { roles, isLoaded: rolesLoadedHook } = useRoles();
  const { templates, configs, isLoaded: templatesLoaded } = useTemplates();
  const { personnel } = usePersonnel();
  const { saveGuardReport } = useGuardHistory();
  const router = useRouter();

  const [statisticsText, setStatisticsText] = useState(
    DEFAULT_STATISTICS_CATEGORIES.map((c) => `- ${c} 0`).join('\n')
  );
  const [generatedReport, setGeneratedReport] = useState('');
  const [isResultDialogOpen, setIsResultDialogOpen] = useState(false);
  const [copyButtonText, setCopyButtonText] = useState('Copiar');

  const [manualNovedades, setManualNovedades] = useState<ManualNovedad[]>([]);
  const [newNovedadDate, setNewNovedadDate] = useState(new Date());
  const [newNovedadTime, setNewNovedadTime] = useState('');
  const [newNovedadText, setNewNovedadText] = useState('');

  useEffect(() => {
    if (!settingsLoaded) return;

    const hasCustomDates = settings.finalReportStartDate && settings.finalReportEndDate;

    const startDate = hasCustomDates ? new Date(settings.finalReportStartDate!) : new Date();
    startDate.setHours(9, 0, 0, 0);

    const endDate = hasCustomDates
      ? new Date(settings.finalReportEndDate!)
      : new Date(new Date().setDate(new Date().getDate() + 1));
    endDate.setHours(9, 0, 0, 0);

    const defaultStartNovedad: ManualNovedad = {
      id: `${generateId('manual')}_start`,
      date: startDate,
      time: '09:00 HLV',
      text: 'Se inicia la guardia preventiva de 24 horas',
    };

    const defaultEndNovedad: ManualNovedad = {
      id: `${generateId('manual')}_end`,
      date: endDate,
      time: '09:00 HLV',
      text: 'Se da culminaci├│n a la guardia preventiva de 24 horas',
    };

    setManualNovedades((prev) => {
      const otherNovedades = prev.filter((n) => !n.id.includes('_start') && !n.id.includes('_end'));
      return [...otherNovedades, defaultStartNovedad, defaultEndNovedad];
    });
  }, [settings.finalReportStartDate, settings.finalReportEndDate, settingsLoaded]);

  const globalSettings = useMemo(() => {
    return Object.values(configs).reduce(
      (acc, config) => {
        Object.keys(config.fields).forEach((fieldName) => {
          const field = config.fields[fieldName];
          if (field && field.type === 'predefined' && field.value) {
            acc[fieldName] = field.value;
          }
        });
        return acc;
      },
      {} as Record<string, string>
    );
  }, [configs]);

  const activeGuard = useMemo(() => {
    if (!settings.activeGuardId || !guards.length) return null;
    return guards.find((g) => g.id === settings.activeGuardId);
  }, [settings.activeGuardId, guards]);

  const hasSnapshot = useMemo(() => {
    const staffSnapshot =
      settings.finalReportStaffSnapshot &&
      Object.keys(settings.finalReportStaffSnapshot).length > 0;
    const customDates = !!settings.finalReportStartDate && !!settings.finalReportEndDate;
    return staffSnapshot && customDates;
  }, [settings]);

  const handleClearSnapshot = () => {
    saveSettings({
      ...settings,
      finalReportStaffSnapshot: {},
      finalReportStartDate: '',
      finalReportEndDate: '',
    });
  };

  const handleAddManualNovedad = () => {
    if (!newNovedadTime || !newNovedadText) return;

    const newNovedad: ManualNovedad = {
      id: generateId('manual'),
      date: newNovedadDate,
      time: newNovedadTime,
      text: newNovedadText,
    };
    setManualNovedades((prev) => [...prev, newNovedad]);
    setNewNovedadTime('');
    setNewNovedadText('');
  };

  const handleRemoveManualNovedad = (idToRemove: string) => {
    setManualNovedades((prev) => prev.filter((n) => n.id !== idToRemove));
  };

  const getSortDate = (novedad: Report | ManualNovedad): Date | null => {
    if ('templateId' in novedad) {
      // It's a Report
      const fechaStr = findValueInFormData(novedad.formData, 'Fecha') as string | undefined;
      const horaStr = findValueInFormData(novedad.formData, 'Hora') as string | undefined;

      if (!fechaStr || !horaStr) return null;

      const timeMatch = horaStr.match(/(\d{2}):(\d{2})/);
      if (!timeMatch) return null;

      const mappedValues = timeMatch.slice(1).map(Number);
      const hours = mappedValues[0];
      const minutes = mappedValues[1];
      if (hours === undefined || minutes === undefined || isNaN(hours) || isNaN(minutes))
        return null;

      const sortDate = new Date(`${fechaStr}T00:00:00`);
      if (isNaN(sortDate.getTime())) return null;

      sortDate.setHours(hours, minutes);
      return sortDate;
    } else {
      // It's a ManualNovedad
      const horaStr = novedad.time;
      const timeMatch = horaStr.match(/(\d{2}):(\d{2})/);
      if (!timeMatch) return null;
      const mappedValues = timeMatch.slice(1).map(Number);
      const hours = mappedValues[0];
      const minutes = mappedValues[1];
      if (hours === undefined || minutes === undefined || isNaN(hours) || isNaN(minutes))
        return null;

      const sortDate = new Date(novedad.date);
      sortDate.setHours(hours, minutes, 0, 0);
      return sortDate;
    }
  };

  const sortedManualNovedades = useMemo(() => {
    return [...manualNovedades].sort((a, b) => {
      const dateA = getSortDate(a);
      const dateB = getSortDate(b);
      if (dateA && dateB) return dateA.getTime() - dateB.getTime();
      return 0;
    });
  }, [manualNovedades]);

  const finishedReports = useMemo(() => {
    return reports.filter((report) => report.status === 'Finalizado');
  }, [reports]);

  const handleGenerateReport = () => {
    if (finishedReports.length === 0 && !statisticsText.trim() && manualNovedades.length === 0) {
      setGeneratedReport('No hay novedades finalizadas ni estad├¡sticas para reportar.');
      setIsResultDialogOpen(true);
      return;
    }

    const staffForReport = hasSnapshot ? settings.finalReportStaffSnapshot : activeGuard?.staff;
    const guardIdForReport = hasSnapshot
      ? String(findValueInFormData(settings.finalReportStaffSnapshot, 'Guardia') || activeGuard?.id || '')
      : activeGuard?.id || '';

    // Resolve Leaders from Staff
    const getLeaderName = (roleName: string) => {
      // Priority 1: If snapshot, trust the snapshot as historical record
      if (hasSnapshot && staffForReport) {
        const key = Object.keys(staffForReport).find(
          (k) => k.toLowerCase() === roleName.toLowerCase()
        );
        if (key) {
          const members = staffForReport[key];
          const firstMember = members ? members[0] : undefined;
          if (firstMember) {
            return formatStaffMemberForReport(firstMember, false).trim();
          }
        }
      }

      // Priority 2: Use Global Personnel (Live mode or fallback)
      if (personnel) {
        const globalMatch = personnel.find(
          (p) => p.roleId?.toLowerCase() === roleName.toLowerCase()
        );
        if (globalMatch) {
          return formatStaffMemberForReport(globalMatch, false).trim();
        }
      }
      return '';
    };

    const director = getLeaderName(LEADER_ROLES.DIRECTOR);
    const jefeDeOperaciones = getLeaderName(LEADER_ROLES.JEFE_OPERACIONES);
    const municipio = findInsensitive(globalSettings, 'Municipio');
    const estado = findInsensitive(globalSettings, 'Estado');

    const dateRangeString = (() => {
      const startDate = hasSnapshot ? new Date(settings.finalReportStartDate!) : new Date();
      const endDate = hasSnapshot
        ? new Date(settings.finalReportEndDate!)
        : new Date(new Date().setDate(new Date().getDate() + 1));

      const formatDatePart = (date: Date) =>
        new Intl.DateTimeFormat('es-ES', { weekday: 'long', day: '2-digit', month: 'long' }).format(
          date
        );
      return `DESDE EL ${formatDatePart(startDate)} HASTA EL ${formatDatePart(endDate)} DE ${startDate.getFullYear()}`.toUpperCase();
    })();

    // Use the Orden del D├¡a header format
    const headerParts = [
      `*ORDEN DEL D├ìA DEL INSTITUTO AUT├ôNOMO DE PROTECCI├ôN CIVIL Y ADMINISTRACI├ôN DE DESASTRES MUNICIPIO ${(municipio || '').toUpperCase()} ESTADO ${(estado || '').toUpperCase()}*`,
      ``,
      `*DIRECTOR*`,
      director,
      ``,
      `*JEFE DE OPERACIONES*`,
      jefeDeOperaciones,
      ``,
    ];

    if (guardIdForReport && staffForReport) {
      headerParts.push(`*GRUPO DE GUARDIA:* ÔÇ£${guardIdForReport}ÔÇØ`, ``);
      headerParts.push(`*PERIODO:* ${dateRangeString}`, ``);

      roles
        .filter((r) => !r.isHidden)
        .forEach((role) => {
          if (
            role.name.toLowerCase() === LEADER_ROLES.DIRECTOR.toLowerCase() ||
            role.name.toLowerCase() === LEADER_ROLES.JEFE_OPERACIONES.toLowerCase()
          )
            return;

          const staffKey = Object.keys(staffForReport).find(
            (k) => k.toLowerCase() === role.name.toLowerCase()
          );
          const staffList = staffKey
            ? staffForReport[staffKey as keyof typeof staffForReport]
            : undefined;
          if (staffList && staffList.length > 0 && staffList.some((s) => s.name.trim() !== '')) {
            const showCedula = !!settings.reportaRoleIds?.some(
              (id) => id.toLowerCase() === role.name.toLowerCase()
            );
            // Match Orden del D├¡a format: Vertical list with Role Header
            headerParts.push(
              ``,
              `*${role.name.toUpperCase()}*`,
              staffList.map((member) => formatStaffMemberForReport(member, showCedula)).join('\n')
            );
          }
        });
    }

    const allNovedades = [
      ...finishedReports.map((report) => ({
        type: 'report',
        data: report,
        sortDate: getSortDate(report),
      })),
      ...manualNovedades.map((novedad) => ({
        type: 'manual',
        data: novedad,
        sortDate: getSortDate(novedad),
      })),
    ];

    const sortedAllNovedades = allNovedades
      .filter((item) => item.sortDate)
      .sort((a, b) => a.sortDate!.getTime() - b.sortDate!.getTime());

    const reportContent = sortedAllNovedades
      .map((item) => {
        if (item.type === 'report') {
          const report = item.data as Report;
          const formattedDate = new Intl.DateTimeFormat('es-ES', {
            day: '2-digit',
            month: '2-digit',
            year: 'numeric',
          }).format(item.sortDate!);
          const horaStr = findValueInFormData(report.formData, 'Hora') as string | undefined;
          const timestampText = `${formattedDate} ${horaStr || ''}`.trim();

          const template = templates.find((t) => t.id === report.templateId);
          const config = configs[report.templateId];

          let contentText = '';
          if (template && config) {
            const dynamicPredefinedValues = {
              ...globalSettings,
              Guardia: guardIdForReport,
              [LEADER_ROLES.DIRECTOR]: director,
              [LEADER_ROLES.JEFE_OPERACIONES]: jefeDeOperaciones,
            };
            contentText = renderFinalReport(
              template.content,
              report.formData || {},
              config,
              {},
              true,
              dynamicPredefinedValues
            );
          }

          const titleText = ` - *${timestampText}* - *${report.title}*`;
          return contentText ? `${titleText}\n\n${contentText}` : titleText;
        } else {
          const novedad = item.data as ManualNovedad;
          const formattedDate = new Intl.DateTimeFormat('es-ES', {
            day: '2-digit',
            month: '2-digit',
            year: 'numeric',
          }).format(item.sortDate!);
          const timestampText = `${formattedDate} ${novedad.time}`;
          return ` - *${timestampText}* - *${novedad.text}*`;
        }
      })
      .filter(Boolean)
      .join('\n\n');

    const finalReportParts = [...headerParts];
    if (statisticsText.trim())
      finalReportParts.push(``, `*ESTAD├ìSTICAS DEL D├ìA*`, ``, statisticsText.trim());
    if (reportContent.trim()) finalReportParts.push(``, `*NOVEDADES DEL D├ìA*`, ``, reportContent);
    finalReportParts.push(``, `*PROTECCI├ôN CIVIL ${(municipio || '').toUpperCase()}*`);

    setGeneratedReport(finalReportParts.join('\n').trim());
    setIsResultDialogOpen(true);
    setCopyButtonText('Copiar');
  };

  const handleCopyToClipboard = () => {
    navigator.clipboard.writeText(generatedReport);
    setCopyButtonText('┬íCopiado!');
    setTimeout(() => setCopyButtonText('Copiar'), 2000);
  };

  const isLoaded =
    reportsLoaded && guardsLoaded && settingsLoaded && rolesLoadedHook && templatesLoaded;

  return (
    <>
      <div className="p-4 sm:p-6 lg:p-8">
        <Card className="max-w-4xl mx-auto shadow-lg">
          <CardHeader>
            <CardTitle>Generador de Reporte de Cierre de Guardia</CardTitle>
            <CardDescription>
              A├▒ade las estad├¡sticas y recopila todas las novedades del d├¡a para generar el reporte
              final.
            </CardDescription>
          </CardHeader>
          <CardContent>
            {!isLoaded ? (
              <div className="space-y-6">
                <Skeleton className="h-24 w-full" />
                <Skeleton className="h-48 w-full" />
              </div>
            ) : (
              <div className="space-y-6">
                {hasSnapshot ? (
                  <Alert variant="default">
                    <AlertTitle>Usando Datos de Orden del D├¡a</AlertTitle>
                    <AlertDescription className="space-y-4">
                      <div className="flex items-center justify-between gap-4">
                        <span>
                          El reporte se generar├í con el personal y periodo de la ├║ltima orden del
                          d├¡a emitida.
                        </span>
                        <Button
                          variant="link"
                          className="p-0 h-auto whitespace-nowrap"
                          onClick={handleClearSnapshot}
                        >
                          Anular y usar valores actuales
                        </Button>
                      </div>

                      <div className="rounded-md bg-muted/50 p-3 text-xs font-mono whitespace-pre-wrap max-h-48 overflow-y-auto border">
                        {(() => {
                          const municipio = findInsensitive(globalSettings, 'Municipio');
                          const estado = findInsensitive(globalSettings, 'Estado');

                          const guardIdForReport = hasSnapshot
                            ? findValueInFormData(settings.finalReportStaffSnapshot, 'Guardia') ||
                            activeGuard?.id
                            : activeGuard?.id;
                          const staffForReport = hasSnapshot
                            ? settings.finalReportStaffSnapshot
                            : activeGuard?.staff;

                          // Resolve Leaders from Staff locally for preview
                          const getLeaderName = (roleName: string) => {
                            if (staffForReport) {
                              const key = Object.keys(staffForReport).find(
                                (k) => k.toLowerCase() === roleName.toLowerCase()
                              );
                              if (key) {
                                const members = staffForReport[key];
                                const firstMember = members ? members[0] : undefined;
                                if (firstMember) {
                                  return formatStaffMemberForReport(firstMember, false).trim();
                                }
                              }
                            }
                            if (personnel) {
                              const globalMatch = personnel.find(
                                (p) => p.roleId?.toLowerCase() === roleName.toLowerCase()
                              );
                              if (globalMatch)
                                return formatStaffMemberForReport(globalMatch, false).trim();
                            }
                            return '';
                          };

                          const director = getLeaderName(LEADER_ROLES.DIRECTOR);
                          const jefeDeOperaciones = getLeaderName(LEADER_ROLES.JEFE_OPERACIONES);

                          const dateRangeString = (() => {
                            const startDate = hasSnapshot
                              ? new Date(settings.finalReportStartDate!)
                              : new Date();
                            const endDate = hasSnapshot
                              ? new Date(settings.finalReportEndDate!)
                              : new Date(new Date().setDate(new Date().getDate() + 1));
                            const formatDatePart = (date: Date) =>
                              new Intl.DateTimeFormat('es-ES', {
                                weekday: 'long',
                                day: '2-digit',
                                month: 'long',
                              }).format(date);
                            return `DESDE EL ${formatDatePart(startDate)} HASTA EL ${formatDatePart(endDate)} DE ${startDate.getFullYear()}`.toUpperCase();
                          })();

                          const parts = [
                            `*ORDEN DEL D├ìA DEL INSTITUTO AUT├ôNOMO DE PROTECCI├ôN CIVIL Y ADMINISTRACI├ôN DE DESASTRES MUNICIPIO ${(municipio || '').toUpperCase()} ESTADO ${(estado || '').toUpperCase()}*`,
                            ``,
                            `*DIRECTOR*`,
                            director,
                            ``,
                            `*JEFE DE OPERACIONES*`,
                            jefeDeOperaciones,
                            ``,
                          ];

                          if (guardIdForReport && staffForReport) {
                            parts.push(`*GRUPO DE GUARDIA:* ÔÇ£${guardIdForReport}ÔÇØ`, ``);
                            parts.push(`*PERIODO:* ${dateRangeString}`, ``);

                            roles
                              .filter((r) => !r.isHidden)
                              .forEach((role) => {
                                if (
                                  role.name.toLowerCase() === LEADER_ROLES.DIRECTOR.toLowerCase() ||
                                  role.name.toLowerCase() ===
                                  LEADER_ROLES.JEFE_OPERACIONES.toLowerCase()
                                )
                                  return;
                                const staffKey = Object.keys(staffForReport).find(
                                  (k) => k.toLowerCase() === role.name.toLowerCase()
                                );
                                const staffList = staffKey
                                  ? staffForReport[staffKey as keyof typeof staffForReport]
                                  : undefined;
                                if (
                                  staffList &&
                                  staffList.length > 0 &&
                                  staffList.some((s) => s.name.trim() !== '')
                                ) {
                                  const showCedula = !!settings.reportaRoleIds?.some(
                                    (id) => id.toLowerCase() === role.name.toLowerCase()
                                  );
                                  parts.push(
                                    ``,
                                    `*${role.name.toUpperCase()}*`,
                                    staffList
                                      .map((member) =>
                                        formatStaffMemberForReport(member, showCedula)
                                      )
                                      .join('\n')
                                  );
                                }
                              });
                          }
                          return parts.join('\n');
                        })()}
                      </div>
                    </AlertDescription>
                  </Alert>
                ) : (
                  <Alert variant="default">
                    <AlertTitle>Aviso</AlertTitle>
                    <AlertDescription className="flex items-center justify-between gap-4">
                      <span>
                        No se ha emitido una Orden del D├¡a. El reporte se generar├í con la guardia
                        activa y fecha actuales.
                      </span>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => router.push('/orden-del-dia')}
                      >
                        Ir a Orden del D├¡a
                      </Button>
                    </AlertDescription>
                  </Alert>
                )}
                <div className="space-y-2">
                  <div className="flex items-center justify-between">
                    <Label htmlFor="statistics-text">Estad├¡sticas del D├¡a</Label>
                    <div className="flex gap-2">
                      <Button
                        variant="ghost"
                        size="sm"
                        className="h-6 text-xs text-muted-foreground hover:text-primary"
                        onClick={() => {
                          setStatisticsText(
                            DEFAULT_STATISTICS_CATEGORIES.map((c) => `- ${c} 0`).join('\n')
                          );
                        }}
                        title="Cargar lista completa de categor├¡as en 0"
                      >
                        <FileText className="h-3 w-3 mr-1" />
                        Cargar Est├índar
                      </Button>
                      <Button
                        variant="ghost"
                        size="sm"
                        className="h-6 text-xs text-muted-foreground hover:text-primary"
                        onClick={() => {
                          // 1. Calculate counts from actual reports
                          const reportCounts = new Map<string, number>();
                          finishedReports.forEach((report) => {
                            const template = templates.find((t) => t.id === report.templateId);

                            if (template) {
                              let category = template.statisticsCategory?.toUpperCase().trim();

                              // Evaluate Rules
                              if (template.statisticsRules && template.statisticsRules.length > 0) {
                                for (const rule of template.statisticsRules) {
                                  // Get value from report data using the field ID (Label)
                                  // Note: findValueInFormData searches loosely by label/key
                                  const rawValue = findValueInFormData(
                                    report.formData,
                                    rule.fieldId
                                  );
                                  const val = String(rawValue || '')
                                    .trim()
                                    .toLowerCase();
                                  const targetVal = rule.condition.trim().toLowerCase();

                                  if (val === targetVal) {
                                    category = rule.category.toUpperCase().trim();
                                    break; // Stop at first match
                                  }
                                }
                              }

                              if (category) {
                                reportCounts.set(category, (reportCounts.get(category) || 0) + 1);
                              }
                            }
                          });

                          // 2. Parse existing text or load default if empty
                          let workingMap = new Map<string, number>();
                          const currentLines = statisticsText
                            .trim()
                            .split('\n')
                            .filter((l) => l.trim());

                          if (currentLines.length === 0) {
                            // If empty, load defaults at 0
                            DEFAULT_STATISTICS_CATEGORIES.forEach((cat) => workingMap.set(cat, 0));
                          } else {
                            // Parse existing lines
                            currentLines.forEach((line) => {
                              const match = line.match(/^-\s+(.*)\s+(\d+)$/);
                              if (match && match[1] !== undefined && match[2] !== undefined) {
                                workingMap.set(match[1].trim(), parseInt(match[2]));
                              }
                            });
                          }

                          // 3. Update with calculated counts
                          reportCounts.forEach((count, category) => {
                            workingMap.set(category, count);
                          });

                          // 4. Render back to text
                          const sortedKeys = Array.from(workingMap.keys()).sort((a, b) => {
                            const idxA = DEFAULT_STATISTICS_CATEGORIES.indexOf(a);
                            const idxB = DEFAULT_STATISTICS_CATEGORIES.indexOf(b);
                            if (idxA !== -1 && idxB !== -1) return idxA - idxB;
                            if (idxA !== -1) return -1;
                            if (idxB !== -1) return 1;
                            return a.localeCompare(b);
                          });

                          const newText = sortedKeys
                            .map((key) => `- ${key} ${workingMap.get(key)}`)
                            .join('\n');
                          setStatisticsText(newText);

                          if (
                            reportCounts.size === 0 &&
                            currentLines.length === 0 &&
                            DEFAULT_STATISTICS_CATEGORIES.length === 0
                          ) {
                            // no op
                          }
                        }}
                        title="Actualizar conteo basado en reportes"
                      >
                        <Calculator className="h-3 w-3 mr-1" />
                        Autocalcular
                      </Button>
                    </div>
                  </div>
                  <Textarea
                    id="statistics-text"
                    value={statisticsText}
                    onChange={(e) => setStatisticsText(e.target.value)}
                    placeholder="Introduce las estad├¡sticas del d├¡a, una por l├¡nea. Ejemplo:&#10;- ATENCIONES PREHOSPITALARIAS 06"
                    rows={5}
                  />
                </div>
                <div>
                  <h4 className="font-semibold mb-2">
                    Novedades Registradas ({finishedReports.length} de {reports.length} finalizadas)
                  </h4>
                  <ScrollArea className="h-48 rounded-md border p-4 bg-muted/50">
                    {reports.length > 0 ? (
                      <ul className="space-y-2">
                        {reports.map((report) => (
                          <li key={report.id} className="text-sm">
                            - {report.title}
                            {report.status === 'Finalizado' ? (
                              <span className="ml-2 text-xs text-green-600 font-semibold">
                                (Finalizado)
                              </span>
                            ) : (
                              <span className="ml-2 text-xs text-amber-600">(En proceso)</span>
                            )}
                            {findValueInFormData(report.formData, 'Hora') && (
                              <span className="ml-2 text-xs text-muted-foreground">
                                ({String(findValueInFormData(report.formData, 'Hora'))})
                              </span>
                            )}
                          </li>
                        ))}
                      </ul>
                    ) : (
                      <p className="text-sm text-muted-foreground text-center">
                        No hay novedades para mostrar.
                      </p>
                    )}
                  </ScrollArea>
                </div>

                <div className="space-y-4 pt-4 border-t">
                  <h4 className="font-semibold">A├▒adir Novedad Manual</h4>
                  <div className="space-y-4">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div className="space-y-2">
                        <Label>Fecha</Label>
                        <DatePicker
                          value={format(newNovedadDate, 'yyyy-MM-dd')}
                          onChange={(val) => setNewNovedadDate(new Date(val + 'T00:00:00'))}
                        />
                      </div>
                      <div className="space-y-2">
                        <Label>Hora</Label>
                        <TimeHlvInput
                          value={newNovedadTime}
                          onChange={setNewNovedadTime}
                          showHelperText={false}
                        />
                      </div>
                    </div>
                    <div className="space-y-2">
                      <Label>Texto de la Novedad</Label>
                      <Textarea
                        value={newNovedadText}
                        onChange={(e) => setNewNovedadText(e.target.value)}
                        placeholder="Ej: Se env├¡a primer corte de novedades..."
                      />
                    </div>
                    <div className="flex justify-end">
                      <Button onClick={handleAddManualNovedad}>
                        <PlusCircle className="h-4 w-4 mr-2" />
                        A├▒adir
                      </Button>
                    </div>
                  </div>

                  {manualNovedades.length > 0 && (
                    <div className="space-y-2 pt-2">
                      <Label>Novedades Manuales ({manualNovedades.length})</Label>
                      <div className="space-y-2 rounded-md border p-2 bg-muted/50 max-h-48 overflow-y-auto">
                        {sortedManualNovedades.map((novedad) => (
                          <div
                            key={novedad.id}
                            className="flex items-center justify-between rounded-md p-2 text-sm bg-background"
                          >
                            <span>{`${format(novedad.date, 'dd/MM/yyyy')} ${novedad.time} - ${novedad.text}`}</span>
                            {!novedad.id.includes('_start') && !novedad.id.includes('_end') && (
                              <Button
                                variant="ghost"
                                size="icon"
                                className="h-7 w-7 text-destructive"
                                onClick={() => handleRemoveManualNovedad(novedad.id)}
                              >
                                <Trash2 className="h-4 w-4" />
                              </Button>
                            )}
                          </div>
                        ))}
                      </div>
                    </div>
                  )}
                </div>

                <div className="flex justify-end">
                  <Button
                    onClick={handleGenerateReport}
                    disabled={
                      finishedReports.length === 0 &&
                      !statisticsText.trim() &&
                      manualNovedades.length === 0
                    }
                  >
                    Generar Reporte de Cierre
                  </Button>
                </div>
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      <Dialog open={isResultDialogOpen} onOpenChange={setIsResultDialogOpen}>
        <DialogContent className="max-h-[90vh] max-w-[90vw] sm:max-w-2xl flex flex-col">
          <DialogHeader>
            <DialogTitle>Reporte de Cierre de Guardia Generado</DialogTitle>
            <DialogDescription>Puedes copiar el texto generado.</DialogDescription>
          </DialogHeader>
          <div className="flex-1 overflow-y-auto -mx-6 px-6">
            <Textarea
              readOnly
              value={generatedReport}
              className="w-full h-full min-h-[50vh] text-sm whitespace-pre-wrap font-mono"
            />
          </div>
          <DialogFooter className="mt-auto pt-4">
            <Button type="button" onClick={handleCopyToClipboard}>
              {copyButtonText}
            </Button>
            <Button
              type="button"
              variant="default"
              className="bg-green-600 hover:bg-green-700 text-white"
              onClick={() => {
                saveGuardReport({
                  id: generateId('report'),
                  date: settings.finalReportStartDate
                    ? new Date(settings.finalReportStartDate).toISOString()
                    : new Date().toISOString(),
                  generatedAt: new Date().toISOString(),
                  guardGroup: settings.activeGuardId || '',
                  content: generatedReport,
                  summary: `Reporte de Cierre - ${format(new Date(), 'dd/MM/yyyy')}`,
                });
                setIsResultDialogOpen(false);
                clearAllReports();
              }}
            >
              <Save className="h-4 w-4 mr-2" />
              Guardar en Historial
            </Button>
            <DialogClose asChild>
              <Button type="button" variant="secondary">
                Cerrar
              </Button>
            </DialogClose>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

'use client';

import { useState, useEffect, useMemo, useCallback } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Separator } from '@/components/ui/separator';
import type { StaffRole, Department } from '@/types';
import { Skeleton } from '@/components/ui/skeleton';
import { PlusCircle, Trash2, GripVertical, AlertTriangle } from 'lucide-react';
import { useDepartments } from '@/hooks/use-departments';
import { GuardStaffEditor } from '@/components/guard-staff-editor';
import { useUnits } from '@/hooks/use-units';
import { useRoles } from '@/hooks/use-roles';
import { useReports } from '@/hooks/use-reports';
import { useTemplates } from '@/hooks/use-templates';
import { useGuards } from '@/hooks/use-guards';
import { useDrafts } from '@/hooks/use-drafts';
import { useFieldDefinitions } from '@/hooks/use-field-definitions';
import { useSettings } from '@/hooks/use-settings';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { GlobalTagsManager } from '@/components/global-tags-manager';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';

export default function SettingsPage() {
  const { units, saveUnits, isLoaded: unitsLoaded, clearAllUnits } = useUnits();
  const { roles: initialRoles, saveRoles, isLoaded: rolesLoaded, clearAllRoles } = useRoles();
  const {
    departments,
    addDepartment,
    removeDepartment,
    updateDepartment,
    isLoaded: deptsLoaded,
    clearAllDepartments,
  } = useDepartments();
  const { settings, saveSettings, isLoaded: settingsLoaded, clearAllSettings } = useSettings();
  const { clearAllReports } = useReports();
  const { clearAllTemplates } = useTemplates();
  const { clearAllGuards } = useGuards();
  const { clearAllDefinitions } = useFieldDefinitions();
  const { clearDraft } = useDrafts();

  const [newUnit, setNewUnit] = useState('');
  const [actionToConfirm, setActionToConfirm] = useState<string | null>(null);

  const isLoaded = unitsLoaded && rolesLoaded && deptsLoaded && settingsLoaded;

  const handleAddUnit = async () => {
    if (newUnit && !units.includes(newUnit)) {
      await saveUnits([...units, newUnit].sort());
      setNewUnit('');
    }
  };

  const handleRemoveUnit = async (unitToRemove: string) => {
    await saveUnits(units.filter((u) => u !== unitToRemove));
  };

  const handleConfirmReset = async () => {
    if (!actionToConfirm) return;

    switch (actionToConfirm) {
      case 'reports':
        await clearAllReports();
        break;
      case 'templates':
        await clearAllTemplates();
        break;
      case 'staff':
        await clearAllRoles();
        await clearAllDepartments();
        await clearAllGuards();
        await clearAllUnits();
        break;
      case 'definitions':
        await clearAllDefinitions();
        break;
      case 'all':
        await Promise.all([
          clearAllReports(),
          clearAllTemplates(),
          clearAllRoles(),
          clearAllDepartments(),
          clearAllGuards(),
          clearAllUnits(),
          clearAllDefinitions(),
          clearAllSettings(),
          clearDraft(),
        ]);
        localStorage.removeItem('report-app-welcome-seen');
        window.location.reload();
        break;
    }

    setActionToConfirm(null);
  };

  /* REPORTING ROLES LOGIC */
  const handleAddReportRole = async (roleName: string) => {
    if (roleName && !settings.reportaRoleIds?.includes(roleName)) {
      await saveSettings({
        ...settings,
        reportaRoleIds: [...(settings.reportaRoleIds || []), roleName],
      });
    }
  };

  const handleRemoveReportRole = async (roleName: string) => {
    await saveSettings({
      ...settings,
      reportaRoleIds: (settings.reportaRoleIds || []).filter((r) => r !== roleName),
    });
  };

  const handleMoveReportRole = async (index: number, direction: 'up' | 'down') => {
    if (!settings.reportaRoleIds) return;
    const newRoles = [...settings.reportaRoleIds];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;

    if (targetIndex >= 0 && targetIndex < newRoles.length) {
      const temp = newRoles[index];
      const target = newRoles[targetIndex];
      if (temp !== undefined && target !== undefined) {
        newRoles[index] = target;
        newRoles[targetIndex] = temp;
        await saveSettings({ ...settings, reportaRoleIds: newRoles });
      }
    }
  };

  const resetOptions: {
    [key: string]: { title: string; description: string; buttonLabel: string };
  } = {
    reports: {
      title: '┬┐Limpiar todos los reportes?',
      description:
        'Esta acci├│n es irreversible. Se eliminar├ín permanentemente todos los reportes de novedades que has guardado.',
      buttonLabel: 'Limpiar Reportes',
    },
    templates: {
      title: '┬┐Limpiar todas las plantillas?',
      description:
        'Esta acci├│n es irreversible. Se eliminar├ín permanentemente todas las plantillas y sus configuraciones asociadas.',
      buttonLabel: 'Limpiar Plantillas',
    },
    staff: {
      title: '┬┐Restablecer personal, guardias y unidades?',
      description:
        'Se eliminar├ín todas las guardias, departamentos, cargos personalizados y unidades, volviendo a la configuraci├│n por defecto. El personal y las unidades asignadas se perder├ín.',
      buttonLabel: 'Restablecer Personal y Unidades',
    },
    definitions: {
      title: '┬┐Restablecer etiquetas globales?',
      description:
        'Se eliminar├ín todas las etiquetas globales personalizadas, volviendo a la configuraci├│n por defecto.',
      buttonLabel: 'Restablecer Etiquetas',
    },
    all: {
      title: '┬┐Restablecer toda la aplicaci├│n?',
      description:
        '┬íADVERTENCIA! Esta acci├│n es irreversible. Se eliminar├í TODA la informaci├│n guardada (reportes, plantillas, configuraciones, personal) y se restaurar├í la aplicaci├│n a su estado inicial. Es como abrirla por primera vez.',
      buttonLabel: 'Restablecer Toda la Aplicaci├│n',
    },
  };

  if (!isLoaded) {
    return (
      <div className="p-4 sm:p-6 lg:p-8 space-y-6">
        <Skeleton className="h-48 w-full max-w-4xl mx-auto" />
        <Skeleton className="h-48 w-full max-w-4xl mx-auto" />
        <Skeleton className="h-48 w-full max-w-4xl mx-auto" />
      </div>
    );
  }

  return (
    <>
      <div className="p-4 sm:p-6 lg:p-8 space-y-6">
        <Card className="max-w-4xl mx-auto shadow-lg">
          <CardHeader>
            <CardTitle>Configuraci├│n de Personal que Reporta</CardTitle>
            <CardDescription>
              Gestiona los cargos que se usar├ín para rellenar la etiqueta [Reporta].
              El orden en la lista determina la prioridad al mostrar el personal.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-6 pt-6">
            <div className="space-y-2 max-w-sm">
              <Label>A├▒adir Cargo a Reporta</Label>
              <Select onValueChange={handleAddReportRole}>
                <SelectTrigger>
                  <SelectValue placeholder="Selecciona un cargo para a├▒adir..." />
                </SelectTrigger>
                <SelectContent>
                  {initialRoles
                    .filter((role) => !settings.reportaRoleIds?.includes(role.name))
                    .map((role) => (
                      <SelectItem key={role.name} value={role.name}>
                        {role.name}
                      </SelectItem>
                    ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label>Cargos Seleccionados (Prioridad de arriba a abajo)</Label>
              <div className="space-y-2 rounded-md border p-2">
                {settings.reportaRoleIds && settings.reportaRoleIds.length > 0 ? (
                  settings.reportaRoleIds.map((roleName, index) => (
                    <div
                      key={roleName}
                      className="flex items-center justify-between rounded-md p-3 bg-muted/30 hover:bg-muted/50 transition-colors border"
                    >
                      <div className="flex items-center gap-3">
                        <span className="flex h-6 w-6 items-center justify-center rounded-full bg-primary/10 text-[10px] font-bold text-primary">
                          {index + 1}
                        </span>
                        <span className="font-medium">{roleName}</span>
                      </div>
                      <div className="flex items-center gap-1">
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-8 w-8"
                          onClick={() => handleMoveReportRole(index, 'up')}
                          disabled={index === 0}
                          title="Subir prioridad"
                        >
                          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="m18 15-6-6-6 6" /></svg>
                        </Button>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-8 w-8"
                          onClick={() => handleMoveReportRole(index, 'down')}
                          disabled={index === (settings.reportaRoleIds?.length || 0) - 1}
                          title="Bajar prioridad"
                        >
                          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="m6 9 6 6 6-6" /></svg>
                        </Button>
                        <Separator orientation="vertical" className="h-6 mx-1" />
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-8 w-8 text-destructive hover:bg-destructive/10"
                          onClick={() => handleRemoveReportRole(roleName)}
                          title="Eliminar de la lista"
                        >
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </div>
                    </div>
                  ))
                ) : (
                  <div className="p-8 text-center text-sm text-muted-foreground border border-dashed rounded-md bg-muted/5">
                    No has seleccionado ning├║n cargo para el reporte.
                  </div>
                )}
              </div>
            </div>
          </CardContent>
        </Card>

        <Card className="max-w-4xl mx-auto shadow-lg">
          <CardHeader>
            <CardTitle>Gesti├│n de Unidades</CardTitle>
            <CardDescription>
              A├▒ade o elimina unidades de la lista de veh├¡culos operativos.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-6 pt-6">
            <div className="space-y-2">
              <Label>A├▒adir Nueva Unidad</Label>
              <div className="flex flex-col sm:flex-row gap-2 sm:max-w-sm">
                <Input
                  value={newUnit}
                  onChange={(e) => setNewUnit(e.target.value)}
                  placeholder="Ej: Alpha 3"
                  className="flex-1"
                />
                <Button onClick={handleAddUnit} className="w-full sm:w-auto">
                  <PlusCircle className="mr-2 h-4 w-4" />
                  A├▒adir
                </Button>
              </div>
            </div>
            <div className="space-y-2">
              <Label>Unidades Existentes</Label>
              <div className="space-y-2 max-h-60 overflow-y-auto rounded-md border p-2">
                {units.length > 0 ? (
                  units.map((unit) => (
                    <div
                      key={unit}
                      className="flex items-center justify-between rounded-md p-2 hover:bg-muted/50"
                    >
                      <span>{unit}</span>
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-8 w-8 text-destructive hover:bg-destructive/10"
                        onClick={() => handleRemoveUnit(unit)}
                        aria-label={`Eliminar Unidad ${unit}`}
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </div>
                  ))
                ) : (
                  <p className="p-4 text-center text-sm text-muted-foreground">No hay unidades.</p>
                )}
              </div>
            </div>
          </CardContent>
        </Card>

        <GlobalTagsManager />

        <Card className="max-w-4xl mx-auto shadow-lg border-destructive">
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-destructive">
              <AlertTriangle />
              Zona de Peligro
            </CardTitle>
            <CardDescription>
              Las siguientes acciones son destructivas y no se pueden deshacer. ├Üsalas con
              precauci├│n.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            {Object.entries(resetOptions).map(([key, option]) => (
              <div
                key={key}
                className="flex flex-col sm:flex-row sm:items-center justify-between p-4 gap-4 rounded-md border border-dashed border-destructive/50"
              >
                <div className="space-y-1">
                  <h4 className="font-semibold text-destructive">{option.buttonLabel}</h4>
                  <p className="text-sm text-muted-foreground leading-relaxed">
                    {option.description.split('.')[0]}.
                  </p>
                </div>
                <Button
                  variant="destructive"
                  onClick={() => setActionToConfirm(key)}
                  className="w-full sm:w-auto shrink-0 shadow-sm"
                >
                  {option.buttonLabel}
                </Button>
              </div>
            ))}
          </CardContent>
        </Card>
      </div>

      <AlertDialog
        open={!!actionToConfirm}
        onOpenChange={(open) => !open && setActionToConfirm(null)}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>
              {actionToConfirm && resetOptions[actionToConfirm]?.title}
            </AlertDialogTitle>
            <AlertDialogDescription>
              {actionToConfirm && resetOptions[actionToConfirm]?.description}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel onClick={() => setActionToConfirm(null)}>Cancelar</AlertDialogCancel>
            <AlertDialogAction onClick={handleConfirmReset}>S├¡, continuar</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

'use client';

import { useState, useMemo, useEffect } from 'react';
import { MapContainer, TileLayer, Marker, Popup, useMapEvents, useMap } from 'react-leaflet';
import L, { LatLng } from 'leaflet';
import 'leaflet/dist/leaflet.css';

import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Map as MapIcon, Satellite } from 'lucide-react';
import { Button } from '@/components/ui/button';

import type { Address } from '@/types';

interface AddressMapProps {
  latitude?: string | null;
  longitude?: string | null;
  name?: string | null;
  addresses?: Address[];
  onMapClick?: (coords: { lat: number; lng: number }) => void;
}

type MapType = 'street' | 'satellite';

const TILE_LAYERS = {
  street: {
    url: 'https://{s}.tile.openstreetmap.fr/hot/{z}/{x}/{y}.png',
    attribution:
      '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors, Tiles style by <a href="https://www.hotosm.org/" target="_blank">HOT</a>',
  },
  satellite: {
    url: 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',
    attribution:
      'Tiles &copy; Esri &mdash; Source: Esri, i-cubed, USDA, USGS, AEX, GeoEye, Getmapping, Aerogrid, IGN, IGP, UPR-EGP, and the GIS User Community',
  },
  labels: {
    url: 'https://server.arcgisonline.com/ArcGIS/rest/services/Reference/World_Boundaries_and_Places/MapServer/tile/{z}/{y}/{x}',
    attribution: '',
  },
};

const ChangeView = ({ center, zoom }: { center: [number, number]; zoom: number }) => {
  const map = useMap();
  useEffect(() => {
    map.setView(center, zoom, { animate: false });
  }, [center, zoom, map]);
  return null;
};

const MapResizer = ({ mapType }: { mapType: string }) => {
  const map = useMap();
  useEffect(() => {
    const handleResize = () => {
      map.invalidateSize();
    };

    window.addEventListener('resize', handleResize);

    const timer = setTimeout(() => {
      map.invalidateSize();
    }, 200);

    return () => {
      window.removeEventListener('resize', handleResize);
      clearTimeout(timer);
    };
  }, [map, mapType]);
  return null;
};

const TempMarkerWithPopup = ({
  position,
  onCreateClick,
  icon,
}: {
  position: LatLng;
  onCreateClick: () => void;
  icon: L.Icon;
}) => {
  const map = useMap();

  useEffect(() => {
    // Auto-centering removed as per user request to avoid jumping/zooming when clicking the map
    // map.setView(position, map.getZoom(), { animate: false });
  }, [position, map]);

  return (
    <Marker position={position} icon={icon}>
      <Popup autoClose={false} closeOnClick={false} closeButton={false} autoPan={false}>
        <div className="text-center p-1">
          <p className="font-semibold mb-2">Nuevo Punto</p>
          <Button size="sm" onClick={onCreateClick}>
            Crear Direcci├│n Aqu├¡
          </Button>
        </div>
      </Popup>
    </Marker>
  );
};

export function AddressMap({
  latitude,
  longitude,
  name,
  addresses = [],
  onMapClick,
}: AddressMapProps) {
  const [mapType, setMapType] = useState<MapType>('street');
  const [tempMarkerPos, setTempMarkerPos] = useState<LatLng | null>(null);

  const { lat, lon, isValid } = useMemo(() => {
    if (!latitude || !longitude) {
      return { lat: NaN, lon: NaN, isValid: false };
    }
    const parsedLat = parseFloat(latitude);
    const parsedLon = parseFloat(longitude);
    const valid = !isNaN(parsedLat) && !isNaN(parsedLon);
    return { lat: parsedLat, lon: parsedLon, isValid: valid };
  }, [latitude, longitude]);

  useEffect(() => {
    // Cleanup helper for strict mode / React 19
    // Removed manual cleanup that was causing _leaflet_events error
    return () => { };
  }, []);

  useEffect(() => {
    // When a permanent address is selected, remove the temporary marker
    if (isValid) {
      setTempMarkerPos(null);
    }
  }, [isValid, latitude, longitude]);

  const center = useMemo<[number, number]>(
    () => (isValid ? [lat, lon] : [10.16, -64.68]),
    [isValid, lat, lon]
  );

  const zoom = useMemo(() => (isValid ? 16 : 9), [isValid]);

  const MapEventsHandler = () => {
    useMapEvents({
      click(e) {
        if (onMapClick) {
          setTempMarkerPos(e.latlng);
        }
      },
    });
    return null;
  };

  const handleCreateClick = () => {
    if (tempMarkerPos && onMapClick) {
      onMapClick({ lat: tempMarkerPos.lat, lng: tempMarkerPos.lng });
      setTempMarkerPos(null); // Clear marker after clicking the button
    }
  };

  // Create icon instance memoized
  const customIcon = useMemo(() => {
    return L.icon({
      iconUrl: 'https://unpkg.com/leaflet@1.7.1/dist/images/marker-icon.png',
      iconRetinaUrl: 'https://unpkg.com/leaflet@1.7.1/dist/images/marker-icon-2x.png',
      shadowUrl: 'https://unpkg.com/leaflet@1.7.1/dist/images/marker-shadow.png',
      iconSize: [25, 41],
      iconAnchor: [12, 41],
      popupAnchor: [1, -34],
      tooltipAnchor: [16, -28],
      shadowSize: [41, 41],
    });
  }, []);

  return (
    <Card className="h-full flex flex-col">
      <CardHeader>
        <div className="flex flex-col sm:flex-row justify-between items-start gap-4">
          <div>
            <CardTitle>Mapa Interactivo</CardTitle>
            <CardDescription>
              {tempMarkerPos
                ? 'Confirma la creaci├│n del nuevo punto'
                : name
                  ? `Ubicaci├│n: ${name}`
                  : 'Haz clic para a├▒adir un punto'}
            </CardDescription>
          </div>
          <div className="flex gap-1 bg-muted p-1 rounded-md self-start sm:self-center">
            <Button
              size="sm"
              variant={mapType === 'street' ? 'secondary' : 'ghost'}
              onClick={() => setMapType('street')}
              className="h-8 px-3"
            >
              <MapIcon className="mr-2 h-4 w-4" />
              Calle
            </Button>
            <Button
              size="sm"
              variant={mapType === 'satellite' ? 'secondary' : 'ghost'}
              onClick={() => setMapType('satellite')}
              className="h-8 px-3"
            >
              <Satellite className="mr-2 h-4 w-4" />
              Sat├®lite
            </Button>
          </div>
        </div>
      </CardHeader>
      <CardContent className="flex-1 p-0 rounded-b-lg overflow-hidden relative">
        <MapContainer
          center={center}
          zoom={zoom}
          scrollWheelZoom={true}
          doubleClickZoom={false}
          style={{ height: '100%', width: '100%', minHeight: '400px' }}
        >
          <MapResizer mapType={mapType} />
          <ChangeView key={`${latitude}-${longitude}`} center={center} zoom={zoom} />
          <TileLayer
            key={mapType}
            attribution={TILE_LAYERS[mapType].attribution}
            url={TILE_LAYERS[mapType].url}
          />
          {mapType === 'satellite' && (
            <TileLayer key="satellite-labels" url={TILE_LAYERS.labels.url} opacity={0.8} />
          )}
          <MapEventsHandler />
          {/* All saved addresses */}
          {addresses.map((address) => {
            const aLat = parseFloat(address.latitude || '');
            const aLon = parseFloat(address.longitude || '');
            if (isNaN(aLat) || isNaN(aLon)) return null;

            // Highlight the currently selected address if it matches
            const isSelected =
              address.id === addresses.find((a) => a.name === name && a.latitude === latitude)?.id;

            return (
              <Marker
                key={address.id}
                position={[aLat, aLon]}
                icon={customIcon}
                opacity={isSelected ? 1 : 0.7}
              >
                <Popup autoPan={false}>
                  <div className="text-sm">
                    <p className="font-bold border-b border-muted pb-1 mb-1">{address.name}</p>
                    <p className="text-[10px] text-muted-foreground">
                      {[address.municipality, address.parish, address.sector]
                        .filter(Boolean)
                        .join(', ')}
                    </p>
                    {address.details && (
                      <p className="text-[10px] italic mt-1 font-mono">"{address.details}"</p>
                    )}
                  </div>
                </Popup>
              </Marker>
            );
          })}

          {/* Temporary marker for new locations */}
          {tempMarkerPos && (
            <TempMarkerWithPopup
              position={tempMarkerPos}
              onCreateClick={handleCreateClick}
              icon={customIcon}
            />
          )}
        </MapContainer>
      </CardContent>
    </Card>
  );
}

'use client';

import React, { useMemo } from 'react';
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import Link from 'next/link';
import { useFieldDefinitions } from '@/hooks/use-field-definitions';
import { useRoles } from '@/hooks/use-roles';
import type { FieldConfig } from '@/types';
import { Skeleton } from '@/components/ui/skeleton';
import { useUnits } from '@/hooks/use-units';

export function GlobalTagsManager() {
  const {
    definitions,
    saveDefinitions,
    removeDefinition,
    isLoaded: definitionsLoaded,
  } = useFieldDefinitions();
  const { roles, isLoaded: rolesLoaded } = useRoles();
  const { units, isLoaded: unitsLoaded } = useUnits();
  const orderedFields = useMemo(() => Object.keys(definitions), [definitions]);

  // Unused handlers removed for cleanliness

  const handleUpdateDefinition = async (fieldName: string, newConfig: FieldConfig) => {
    const newDefinitions = { ...definitions, [fieldName]: newConfig };
    await saveDefinitions(newDefinitions);
  };

  const allDefaultFieldKeys = useMemo(() => ['Municipio', 'Estado', 'REDAN', 'ZOEDAN'], []);

  const generalFields = useMemo(() => {
    return orderedFields.filter((key) => definitions[key] && allDefaultFieldKeys.includes(key));
  }, [orderedFields, definitions, allDefaultFieldKeys]);

  if (!definitionsLoaded || !rolesLoaded || !unitsLoaded) {
    return (
      <Card className="max-w-4xl mx-auto shadow-lg">
        <CardHeader>
          <Skeleton className="h-8 w-1/2" />
          <Skeleton className="h-4 w-3/4" />
        </CardHeader>
        <CardContent className="space-y-4 pt-6">
          <Skeleton className="h-10 w-full" />
          <Skeleton className="h-20 w-full" />
          <Skeleton className="h-20 w-full" />
        </CardContent>
      </Card>
    );
  }

  return (
    <>
      <Card className="max-w-4xl mx-auto shadow-lg">
        <CardHeader>
          <CardTitle>Gestor de Etiquetas Globales</CardTitle>
          <CardDescription>
            Define etiquetas predefinidas para toda la aplicaci├│n y consulta las etiquetas generadas
            por los cargos.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-6 pt-6">
          <div>
            <h3 className="text-lg font-semibold mb-2">Datos Generales</h3>
            <p className="text-sm text-muted-foreground mb-4">
              Estos valores se usar├ín en todas las plantillas que incluyan la etiqueta
              correspondiente (ej. {`{Municipio}`}). Las etiquetas "Fecha" y "Hora" son fijas.
            </p>
            <div className="space-y-2">
              {generalFields.map((key) => {
                const config = definitions[key];
                if (!config) return null;
                return (
                  <div
                    key={key}
                    className="flex flex-col sm:flex-row sm:items-center gap-2 sm:gap-4 rounded-md border p-3 bg-card"
                  >
                    <Label htmlFor={key} className="sm:w-48 font-semibold shrink-0">
                      {config.label}
                    </Label>
                    <div className="flex-1">
                      <Input
                        id={key}
                        value={config.value || ''}
                        onChange={(e) =>
                          handleUpdateDefinition(key, { ...config, value: e.target.value })
                        }
                        className="bg-background w-full"
                        disabled={key === 'Hora' || key === 'Fecha'}
                      />
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          <div>
            <h3 className="text-lg font-semibold mb-2">Etiquetas de Cargos y Unidades</h3>
            <p className="text-sm text-muted-foreground mb-4">
              Estas etiquetas se generan autom├íticamente a partir de los cargos y unidades definidos
              en{' '}
              <Link href="/settings" className="text-primary underline">
                Configuraci├│n
              </Link>
              . La etiqueta{' '}
              <code className="font-mono bg-muted px-1 py-0.5 rounded">{`{Unidad}`}</code> es
              especial: se convertir├í autom├íticamente en un campo de selecci├│n para las unidades que
              hayas registrado.
            </p>
            <div className="flex flex-wrap items-center gap-2">
              {roles.map((role) => (
                <Badge key={role.name} variant="secondary">
                  {role.name}
                </Badge>
              ))}
              <Badge variant="outline">Unidad</Badge>
              {roles.length === 0 && (
                <p className="text-sm text-muted-foreground">No hay cargos definidos.</p>
              )}
            </div>
          </div>
        </CardContent>
      </Card>
    </>
  );
}

