import React, { memo } from 'react';
import {
    FieldConfig,
    StaffRole,
    StaffMember,
    AppSettings,
    SnippetOption,
} from '@/types';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { TimeHlvInput } from '@/components/time-hlv-input';
import { DatePicker } from '@/components/date-picker';
import { MultiInput } from '@/components/ui/multi-input';
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from '@/components/ui/select';
import { AddressInput } from '@/components/ui/address-input';
import { CedulaInput } from '@/components/cedula-input';
import { formatStaffMemberForAutocomplete } from '@/lib/formatters';

interface FieldRendererProps {
    fieldId: string;
    fieldConfig: FieldConfig;
    roles: StaffRole[];
    rolesLoaded: boolean;
    units: string[];
    staffOptions: StaffMember[];
    setValue: (
        name: string,
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        value: any,
        options?: { shouldValidate?: boolean; shouldDirty?: boolean }
    ) => void;
    settings: AppSettings | null;
    // Props passed from Controller render ÔÇö typed as `any` because react-hook-form
    // Controller values are inherently dynamic (string | string[] | StaffMember[] | etc.)
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    value: any;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    onChange: (value: any) => void;
    onBlur?: () => void;
    disabled?: boolean;
    className?: string;
    name: string; // The full path name from react-hook-form
}

export const FieldRenderer = memo(
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    React.forwardRef<any, FieldRendererProps>(
        (
            {
                fieldId,
                fieldConfig,
                roles,
                rolesLoaded,
                units,
                staffOptions,
                setValue,
                settings,
                value,
                onChange,
                onBlur,
                disabled,
                className,
                name,
            },
            ref
        ) => {
            const lowerFieldId = fieldId.toLowerCase();
            const addressFieldNames = ['direcci├│n', 'ubicaci├│n', 'destino'];

            // Check for Reporta field (Analista is discarded)
            if (lowerFieldId === 'reporta') {
                const reportaRoleIds = settings?.reportaRoleIds || [];
                const reportingStaff = staffOptions.filter(
                    (staff) => staff.roleId && reportaRoleIds.includes(staff.roleId)
                );

                // The value might be an array of StaffMember objects. We need the ID for the Select.
                const selectedStaffId =
                    Array.isArray(value) && value.length > 0 && typeof value[0] === 'object'
                        ? value[0].id
                        : undefined;

                const handleSelectChange = (staffId: string) => {
                    const selectedStaff = reportingStaff.find((s) => s.id === staffId);
                    // The form expects an array for this field
                    onChange(selectedStaff ? [selectedStaff] : []);
                };

                return (
                    <Select
                        onValueChange={handleSelectChange}
                        value={selectedStaffId}
                        disabled={disabled}
                    >
                        <SelectTrigger className={className} ref={ref} onBlur={onBlur}>
                            <SelectValue placeholder="Selecciona el personal..." />
                        </SelectTrigger>
                        <SelectContent>
                            {reportingStaff.length > 0 ? (
                                reportingStaff.map((staff) => (
                                    <SelectItem key={staff.id} value={staff.id}>
                                        {formatStaffMemberForAutocomplete(staff, true)}
                                    </SelectItem>
                                ))
                            ) : (
                                <div className="p-2 text-xs text-muted-foreground text-center">
                                    No hay personal asignado a los cargos de reporte.
                                </div>
                            )}
                        </SelectContent>
                    </Select>
                );
            }

            // If type is explicitly something other than 'text', prioritize the switch
            if (fieldConfig.type && fieldConfig.type !== 'text') {
                switch (fieldConfig.type) {
                    case 'textarea':
                        return (
                            <Textarea
                                value={value}
                                onChange={onChange}
                                onBlur={onBlur}
                                disabled={disabled}
                                className={className}
                                rows={1}
                                ref={ref}
                            />
                        );
                    case 'time-hlv':
                        return (
                            <TimeHlvInput
                                value={value}
                                onChange={onChange}
                                disabled={disabled}
                                className={className}
                                ref={ref}
                                onBlur={onBlur}
                            />
                        );
                    case 'date':
                        return (
                            <DatePicker
                                value={value}
                                onChange={onChange}
                                disabled={disabled}
                                className={className}
                                ref={ref}
                                onBlur={onBlur}
                            />
                        );
                    case 'multi-text':
                        return (
                            <MultiInput
                                value={
                                    Array.isArray(value) ? value : value ? [String(value)] : []
                                }
                                onChange={onChange}
                                disabled={disabled}
                                className={className}
                                placeholder="Escribe y presiona Enter para a├▒adir..."
                                ref={ref}
                                onBlur={onBlur}
                            />
                        );
                    case 'dropdown': {
                        const handleSelect = (selectedLabel: string) => {
                            const selectedOption = (fieldConfig.snippetOptions || []).find(
                                (opt: SnippetOption) => opt.label === selectedLabel
                            );
                            if (selectedOption) {
                                onChange(selectedOption.label);
                                if (fieldConfig.targetField) {
                                    const pathParts = name.split('.');
                                    // Replace the last part with targetField to get the sibling field path
                                    pathParts[pathParts.length - 1] = fieldConfig.targetField;
                                    const targetPath = pathParts.join('.');
                                    setValue(targetPath, selectedOption.value, {
                                        shouldDirty: true,
                                    });
                                }
                            }
                        };
                        return (
                            <Select
                                onValueChange={handleSelect}
                                value={value as string}
                                disabled={disabled}
                            >
                                <SelectTrigger className={`w-full ${className || ''}`} ref={ref} onBlur={onBlur}>
                                    <SelectValue placeholder="Selecciona una opci├│n..." />
                                </SelectTrigger>
                                <SelectContent>
                                    {(fieldConfig.snippetOptions || []).map((option) => (
                                        <SelectItem key={option.id} value={option.label}>
                                            {option.label}
                                        </SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        );
                    }
                }
            }

            // Default or explicitly 'text': use name-based specialization or standard input
            if (lowerFieldId === 'c├®dula') {
                return (
                    <CedulaInput
                        value={value}
                        onChange={onChange}
                        disabled={disabled}
                        className={className}
                        ref={ref}
                        onBlur={onBlur}
                    />
                );
            }

            if (addressFieldNames.includes(lowerFieldId)) {
                return (
                    <AddressInput
                        value={value}
                        onChange={onChange}
                        disabled={disabled}
                        className={className}
                        placeholder="Selecciona o escribe una direcci├│n..."
                        ref={ref}
                        onBlur={onBlur}
                    />
                );
            }

            if (fieldId === 'Unidad') {
                return (
                    <MultiInput
                        value={
                            Array.isArray(value) ? value : value ? [String(value)] : []
                        }
                        onChange={onChange}
                        disabled={disabled}
                        className={className}
                        options={units}
                        placeholder="Buscar o a├▒adir unidades..."
                        ref={ref}
                        onBlur={onBlur}
                    />
                );
            }

            const role = rolesLoaded
                ? roles.find((r) => r.name.toLowerCase() === lowerFieldId)
                : null;

            if (role) {
                const currentValue = Array.isArray(value)
                    // eslint-disable-next-line @typescript-eslint/no-explicit-any
                    ? value.map((val: any) =>
                        typeof val === 'object' && val.name ? val.name : val
                    )
                    : [];
                const autocompleteOptions = staffOptions.map((member) =>
                    formatStaffMemberForAutocomplete(member, false)
                );
                const handleMultiInputChange = (newValue: string[] | string) => {
                    const finalValueArray = Array.isArray(newValue) ? newValue : [newValue];
                    onChange(finalValueArray);
                };

                return (
                    <MultiInput
                        value={currentValue}
                        onChange={(val) => handleMultiInputChange(val as string[] | string)}
                        disabled={disabled}
                        className={className}
                        options={autocompleteOptions}
                        placeholder="Buscar o a├▒adir..."
                        isSingle={role.isSingle}
                        ref={ref}
                        onBlur={onBlur}
                    />
                );
            }

            return (
                <Input
                    value={value}
                    onChange={onChange}
                    onBlur={onBlur}
                    disabled={disabled}
                    className={className}
                    ref={ref}
                />
            );
        }
    )
);
FieldRenderer.displayName = 'FieldRenderer';

