'use client';

import { useMemo, useEffect, forwardRef, useImperativeHandle, useCallback } from 'react';
import { useForm, Controller } from 'react-hook-form';
import type {
  Template,
  TemplateConfig,
  FieldConfig,
  FieldType,
  SectionConfig,
  StaffMember,
  FormDataRecord,
} from '@/types';
import { useFieldDefinitions } from '@/hooks/use-field-definitions';

import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { parseTemplate, renderFinalReport } from '@/lib/template-parser';
import { logger } from '@/lib/logger';
import { cn } from '@/lib/utils';
import { useRoles } from '@/hooks/use-roles';
import { useGuards } from '@/hooks/use-guards';
import { useDepartments } from '@/hooks/use-departments';
import { useUnits } from '@/hooks/use-units';
import { useSettings } from '@/hooks/use-settings';
import { toast } from 'sonner';

import { FieldRenderer } from './field-renderer';
import { SectionRenderer } from './section-renderer';

export interface ReportFormRef {
  submit: () => void;
  getValues: () => FormDataRecord;
  getRenderedContent: () => string;
}

export interface ReportFormProps {
  template: Template;
  config: TemplateConfig;
  initialData?: FormDataRecord;
  onSubmit: (formData: FormDataRecord, content: string, title: string) => void;
  disabled?: boolean;
  onDataChange?: (formData: FormDataRecord) => void;
}

export const ReportForm = forwardRef<ReportFormRef, ReportFormProps>(
  ({ template, config, initialData, onSubmit, disabled = false, onDataChange }, ref) => {
    const { definitions } = useFieldDefinitions();
    const { roles, isLoaded: rolesLoaded } = useRoles();
    const { guards, isLoaded: guardsLoaded } = useGuards();
    const { departments, isLoaded: deptsLoaded } = useDepartments();
    const { settings, isLoaded: settingsLoaded } = useSettings();
    const { units } = useUnits();

    const activeGuardStaff = useMemo(() => {
      if (!settingsLoaded || !guardsLoaded || !settings?.activeGuardId) return [];
      const activeGuard = guards.find((g) => g.id === settings.activeGuardId);
      if (!activeGuard || !activeGuard.staff) return [];

      const staffSetWithRoles = new Set<StaffMember & { roleId?: string }>();
      Object.entries(activeGuard.staff).forEach(([roleName, staffList]) => {
        const roleId = roles.find((r) => r.name === roleName)?.name; // Using name as ID for now
        staffList.forEach((person) => {
          staffSetWithRoles.add({ ...person, roleId: roleId });
        });
      });

      return Array.from(staffSetWithRoles).sort((a, b) => a.name.localeCompare(b.name));
    }, [settings?.activeGuardId, guards, settingsLoaded, guardsLoaded, roles]);

    const finalConfig = useMemo(() => {
      if (!config || !template) return { fields: {}, sections: [], layout: [] };

      const {
        sections,
        layout,
        fieldNames,
        fieldTypes,
        templateOptions,
        fieldModifiers,
        fieldWidths,
        requiredFields,
      } = parseTemplate(template.content);

      const newConfig: TemplateConfig = {
        fields: {},
        sections,
        layout,
      };

      let timeHlvFieldInConfig: string | null = null;
      const templateConfigFields = config.fields || {};

      if (config.fields) {
        timeHlvFieldInConfig =
          Object.keys(config.fields).find((k) => config.fields[k]?.type === 'time-hlv') || null;
      }

      fieldNames.forEach((fieldId) => {
        const templateFieldConfig = templateConfigFields[fieldId];
        const globalDef = definitions[fieldId];
        const typeFromTemplate = fieldTypes.get(fieldId);

        // Priority: template-specific config > global definition > calculated > default
        const mergedConfig = { ...(globalDef || {}), ...(templateFieldConfig || {}) };

        // Determine the type with proper priority
        let fieldType: FieldType = 'text';

        // Priority 1: Explicitly specified type from template (e.g. {Field:dropdown})
        if (typeFromTemplate && typeFromTemplate !== 'text') {
          fieldType = typeFromTemplate;
        }
        // Priority 2: Special handling for Fecha and Hora fields by name
        else if (fieldId.toLowerCase() === 'fecha') {
          fieldType = 'date';
        } else if (fieldId.toLowerCase() === 'hora') {
          if (!timeHlvFieldInConfig || timeHlvFieldInConfig === fieldId) {
            fieldType = 'time-hlv';
            if (!timeHlvFieldInConfig) timeHlvFieldInConfig = fieldId;
          } else {
            fieldType = 'text';
          }
        }
        // Priority 3: Use type from template even if it's 'text'
        else if (typeFromTemplate) {
          fieldType = typeFromTemplate;
        }
        // Priority 4: Check template config (from JSON/Props)
        else if (templateFieldConfig?.type) {
          fieldType = templateFieldConfig.type;
        }
        // Priority 5: Check global definition
        else if (globalDef?.type) {
          fieldType = globalDef.type;
        }
        // Priority 6: Otherwise use merged config or default to 'text'
        else if ((mergedConfig as any).type) {
          fieldType = (mergedConfig as any).type;
        }

        newConfig.fields[fieldId] = {
          ...mergedConfig,
          type: fieldType,
          label: (mergedConfig as any).label || fieldId,
        } as FieldConfig;

        if (templateOptions.has(fieldId)) {
          newConfig.fields[fieldId].snippetOptions = templateOptions.get(fieldId);
        }

        // Apply text modifiers if defined in template
        if (fieldModifiers.has(fieldId)) {
          newConfig.fields[fieldId].modifiers = fieldModifiers.get(fieldId) as any;
        } else if ((mergedConfig as any).modifier) {
          // Backward compatibility for singular modifier in config
          newConfig.fields[fieldId].modifiers = [(mergedConfig as any).modifier];
        }

        // Apply full width if defined in template or if it's a textarea
        if (fieldWidths.has(fieldId)) {
          newConfig.fields[fieldId].isFullWidth = true;
        }

        // Apply required if defined in template
        if (requiredFields.has(fieldId)) {
          newConfig.fields[fieldId].required = true;
        }
      });

      return newConfig;
    }, [config, template, definitions]);

    const predefinedValues: Record<string, string> = useMemo(() => {
      const values: Record<string, string> = {};
      Object.entries(definitions).forEach(([key, config]) => {
        if (config.type === 'predefined' || key === 'Fecha') {
          // Treat Fecha as a dynamic predefined value
          values[key] = config.value || '';
        }
      });
      return values;
    }, [definitions]);

    const getInitialValues = useCallback(
      (data?: FormDataRecord) => {
        const initialFormValues: FormDataRecord = data ? JSON.parse(JSON.stringify(data)) : {};

        const applyDefaults = (target: FormDataRecord, fieldIds: string[]) => {
          fieldIds.forEach((fieldId) => {
            if (target[fieldId] === undefined || target[fieldId] === null) {
              const keyLower = fieldId.toLowerCase();
              const foundKey = Object.keys(predefinedValues).find(
                (k) => k.toLowerCase() === keyLower
              );

              if (foundKey) {
                target[fieldId] = predefinedValues[foundKey];
              } else {
                const role = roles.find((r) => r.name.toLowerCase() === keyLower);
                if (role) {
                  target[fieldId] = [];
                } else if (fieldId === 'Unidad') {
                  target[fieldId] = [];
                } else {
                  target[fieldId] = '';
                }
              }
            }
          });
        };

        const addedTopLevelFields = new Set<string>();
        const topLevelFieldIds = finalConfig.layout.filter((id) => {
          if (id.startsWith('section_') || id.startsWith('sec_') || id.startsWith('cond_'))
            return false;
          const isAssigned = finalConfig.sections.some((s) => s.fieldIds.includes(id));
          if (isAssigned) return false;
          if (addedTopLevelFields.has(id)) return false;
          addedTopLevelFields.add(id);
          return true;
        });
        applyDefaults(initialFormValues, topLevelFieldIds);

        const initializeSection = (sectionId: string, target: FormDataRecord) => {
          const section = finalConfig.sections.find((s) => s.id === sectionId);
          if (!section) return;

          if (section.isRepeatable) {
            if (!target[section.id] || !Array.isArray(target[section.id])) {
              target[section.id] = [];
            }

            const sectionData = target[section.id] as FormDataRecord[];

            if ((!data || sectionData.length === 0) && sectionData.length === 0) {
              const defaultItem: FormDataRecord = {};
              applyDefaults(defaultItem, section.fieldIds);
              (section.layout || section.fieldIds).forEach((id) => {
                if (id.startsWith('section_') || id.startsWith('sec_') || id.startsWith('cond_')) {
                  initializeSection(id, defaultItem);
                }
              });
              sectionData.push(defaultItem);
            } else {
              sectionData.forEach((item: FormDataRecord) => {
                applyDefaults(item, section.fieldIds);
                (section.layout || section.fieldIds).forEach((id) => {
                  if (
                    id.startsWith('section_') ||
                    id.startsWith('sec_') ||
                    id.startsWith('cond_')
                  ) {
                    initializeSection(id, item);
                  }
                });
              });
            }
          } else {
            if (section.id === 'section_separator') return;

            if (!target[section.id]) {
              target[section.id] = {};
            }

            const sectionObject = target[section.id] as FormDataRecord;
            applyDefaults(sectionObject, section.fieldIds);
            (section.layout || section.fieldIds).forEach((id) => {
              if (id.startsWith('section_') || id.startsWith('sec_') || id.startsWith('cond_')) {
                initializeSection(id, sectionObject as FormDataRecord);
              }
            });
          }
        };

        // Initialize from top-level layout
        finalConfig.layout.forEach((id) => {
          if (id.startsWith('section_') || id.startsWith('sec_') || id.startsWith('cond_')) {
            initializeSection(id, initialFormValues);
          }
        });

        return initialFormValues;
      },
      [finalConfig, predefinedValues, roles]
    );

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const { handleSubmit, control, watch, reset, getValues, setValue } = useForm<Record<string, any>>({
      defaultValues: getInitialValues(initialData) as Record<string, unknown>,
    });

    useEffect(() => {
      const subscription = watch((value, { name, type }) => {
        if (type !== 'change' || !name) return;
        if (onDataChange) {
          onDataChange(getValues());
        }
      });
      return () => subscription.unsubscribe();
    }, [watch, onDataChange, getValues]);

    useEffect(() => {
      const formValues = getInitialValues(initialData);
      reset(formValues);
    }, [initialData, finalConfig, getInitialValues, reset]);

    const handleFormSubmit = (data: FormDataRecord) => {
      const finalContent = renderFinalReport(template.content, data, finalConfig, predefinedValues);
      const title = String(data.titulo || data.title || template.name);
      onSubmit(data, finalContent, title);
    };

    useImperativeHandle(ref, () => ({
      submit: () => {
        handleSubmit(handleFormSubmit, (errors) => {
          logger.error('Form validation errors', new Error('Validation failed'), { feature: 'ReportForm', metadata: { errors } });
          toast.error('Por favor, corrige los errores en el formulario antes de guardar.');
        })();
      },
      getValues: getValues,
      getRenderedContent: () => {
        const formData = getValues();
        return renderFinalReport(template.content, formData, finalConfig, predefinedValues);
      },
    }));

    const sectionsById = useMemo(
      () =>
        finalConfig.sections.reduce(
          (acc, section) => {
            acc[section.id] = section;
            return acc;
          },
          {} as Record<string, SectionConfig>
        ),
      [finalConfig.sections]
    );

    const layoutChunks = useMemo(() => {
      const chunks: (string[] | string)[] = [];
      let currentFieldChunk: string[] = [];
      const addedTopLevelFields = new Set<string>();

      finalConfig.layout.forEach((id) => {
        if (id.startsWith('section_') || id.startsWith('sec_') || id.startsWith('cond_')) {
          if (currentFieldChunk.length > 0) {
            chunks.push(currentFieldChunk);
            currentFieldChunk = [];
          }
          chunks.push(id);
        } else if (id === 'section_separator' || id === 'sec_separator') {
          if (currentFieldChunk.length > 0) {
            chunks.push(currentFieldChunk);
            currentFieldChunk = [];
          }
          chunks.push('section_separator');
        } else {
          // It's a field
          // Check if it's already in a section
          const isAssignedToSection = finalConfig.sections.some((s) => s.fieldIds.includes(id));
          if (!isAssignedToSection) {
            // Check if it's already added to avoid duplicates if layout has duplicates
            if (!addedTopLevelFields.has(id)) {
              currentFieldChunk.push(id);
              addedTopLevelFields.add(id);
            }
          }
        }
      });

      if (currentFieldChunk.length > 0) {
        chunks.push(currentFieldChunk);
      }
      return chunks;
    }, [finalConfig]);

    return (
      <form onSubmit={handleSubmit(handleFormSubmit)} className="space-y-6" autoComplete="off">
        {layoutChunks.map((chunk, index) => {
          if (typeof chunk === 'string') {
            if (chunk === 'section_separator') {
              return <div key={`sep-${index}`} className="border-b pt-6"></div>;
            }
            const section = sectionsById[chunk];
            if (!section) return null;
            return (
              <SectionRenderer
                key={section.id}
                section={section}
                config={finalConfig}
                control={control}
                disabled={disabled}
                roles={roles}
                rolesLoaded={rolesLoaded}
                activeGuardStaff={activeGuardStaff}
                predefinedValues={predefinedValues}
                units={units}
                setValue={setValue}
                settings={settings}
                pathPrefix=""
              />
            );
          } else {
            return (
              <div
                key={`chunk-${index}`}
                className="grid grid-cols-1 sm:grid-cols-2 3xl:grid-cols-3 gap-x-4 gap-y-6"
              >
                {chunk.map((fieldId) => {
                  const fieldConfig = finalConfig.fields[fieldId];
                  if (!fieldConfig) return null;
                  const isFullWidth = fieldConfig.type === 'textarea';

                  return (
                    <div
                      key={fieldId}
                      className={cn('space-y-2', isFullWidth && 'sm:col-span-2 3xl:col-span-3')}
                    >
                      <Label htmlFor={fieldId}>{fieldConfig.label || fieldId}</Label>
                      <Controller
                        name={fieldId}
                        control={control}
                        render={({ field }) => (
                          <FieldRenderer
                            fieldId={fieldId}
                            fieldConfig={fieldConfig}
                            roles={roles}
                            rolesLoaded={rolesLoaded}
                            units={units}
                            staffOptions={activeGuardStaff}
                            setValue={setValue}
                            settings={settings}
                            value={field.value}
                            onChange={field.onChange}
                            name={field.name}
                            disabled={disabled}
                          />
                        )}
                      />
                    </div>
                  );
                })}
              </div>
            );
          }
        })}
      </form>
    );
  }
);
ReportForm.displayName = 'ReportForm';

'use client';

import { useState, useRef, useMemo, useCallback, useEffect } from 'react';
import type { Template, TemplateConfig, Report, ReportDraft, StaffMember } from '@/types';
import { ReportForm, type ReportFormRef } from './report-form';
import { Button } from '@/components/ui/button';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Eye, Copy, CheckIcon } from 'lucide-react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogClose,
} from '@/components/ui/dialog';
import { Textarea } from '@/components/ui/textarea';
import { useDrafts } from '@/hooks/use-drafts';
import { debounce } from '@/lib/utils';
import { useSettings } from '@/hooks/use-settings';
import { useGuards } from '@/hooks/use-guards';
import { parseTemplate } from '@/lib/template-parser';
import { useFieldDefinitions } from '@/hooks/use-field-definitions';
import { toast } from 'sonner';
import { formatStaffMemberForAutocomplete } from '@/lib/formatters';
import { generateId } from '@/lib/utils/id';

interface ReportGeneratorProps {
  template: Template;
  config: TemplateConfig;
  initialData?: Record<string, any>;
  onCancel: () => void;
  onSave: (report: Report) => void;
}

export function ReportGenerator({
  template,
  config,
  initialData,
  onCancel,
  onSave,
}: ReportGeneratorProps) {
  const { saveDraft, clearDraft } = useDrafts();
  const formRef = useRef<ReportFormRef>(null);
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);
  const [previewContent, setPreviewContent] = useState('');
  const [copyButtonText, setCopyButtonText] = useState('Copiar');
  const { settings } = useSettings();
  const { guards } = useGuards();
  const { definitions } = useFieldDefinitions();

  const finalInitialData = useMemo(() => {
    const newInitialData = initialData ? JSON.parse(JSON.stringify(initialData)) : {};

    const { sections, fieldNames: allTemplateFields } = parseTemplate(template.content);

    const activeGuard = guards.find((g) => g.id === settings.activeGuardId);
    if (!activeGuard) {
      return newInitialData;
    }

    const dataToInject: Record<string, any> = {};

    // Get Jefe de los servicios
    const jefeDeServiciosKey = Object.keys(activeGuard.staff || {}).find(
      (k) => k.toLowerCase() === 'jefe de los servicios'
    );
    if (jefeDeServiciosKey) {
      const jefeStaff = activeGuard.staff[jefeDeServiciosKey] || [];
      if (jefeStaff.length > 0) {
        dataToInject['Jefe de los Servicios'] = jefeStaff.map((member) => member.name);
      }
    }

    // Get Reporting Personnel (Multi-role with priority)
    if (settings.reportaRoleIds && settings.reportaRoleIds.length > 0) {
      const reportingPersonnel: StaffMember[] = [];
      settings.reportaRoleIds.forEach((roleId) => {
        const roleStaff = activeGuard.staff[roleId] || [];
        reportingPersonnel.push(...roleStaff);
      });
      dataToInject['Reporta'] = reportingPersonnel;
    }

    // Explicitly add Guardia ID to be injected
    dataToInject['Guardia'] = activeGuard.id;

    allTemplateFields.forEach((templateFieldKey) => {
      const lowerTemplateFieldKey = templateFieldKey.toLowerCase();

      const canonicalKey = Object.keys(dataToInject).find(
        (k) => k.toLowerCase() === lowerTemplateFieldKey
      );

      if (canonicalKey) {
        const valueToInject = dataToInject[canonicalKey];
        if (valueToInject === undefined) return;

        const parentSection = sections.find((s) =>
          s.fieldIds.some((sf) => sf.toLowerCase() === lowerTemplateFieldKey)
        );

        if (parentSection) {
          if (!parentSection.isRepeatable) {
            if (!newInitialData[parentSection.id]) {
              newInitialData[parentSection.id] = {};
            }
            if (newInitialData[parentSection.id][templateFieldKey] === undefined) {
              newInitialData[parentSection.id][templateFieldKey] = valueToInject;
            }
          }
        } else {
          if (newInitialData[templateFieldKey] === undefined) {
            newInitialData[templateFieldKey] = valueToInject;
          }
        }
      }
    });

    return newInitialData;
  }, [
    template.content,
    initialData,
    settings.activeGuardId,
    settings.reportaRoleIds,
    guards,
  ]);

  const saveDraftLogicRef = useRef<((formData: Record<string, any>) => void) | null>(null);

  useEffect(() => {
    saveDraftLogicRef.current = async (formData: Record<string, any>) => {
      if (template && formData) {
        const draft: ReportDraft = { templateId: template.id, formData };
        await saveDraft(draft);
      }
    };
  }, [template, saveDraft]);

  const debouncedSaveDraft = useMemo(
    () =>
      debounce((formData: Record<string, any>) => {
        saveDraftLogicRef.current?.(formData);
      }, 30000),
    []
  );

  useEffect(() => {
    return () => {
      debouncedSaveDraft.flush();
    };
  }, [debouncedSaveDraft]);

  const handleDataChange = useCallback(
    (formData: Record<string, any>) => {
      debouncedSaveDraft(formData);
    },
    [debouncedSaveDraft]
  );

  const handleCreateReport = async (
    formData: Record<string, any>,
    content: string,
    title: string
  ) => {
    debouncedSaveDraft.cancel();
    await clearDraft();

    const newReport: Report = {
      id: generateId('report'),
      templateId: template.id,
      title: title,
      timestamp: new Date().toISOString(),
      content: content,
      isRelevant: template.type === 'relevante',
      status: 'En proceso',
      formData: formData,
    };

    onSave(newReport);
  };

  const handleCancel = () => {
    debouncedSaveDraft.flush();
    onCancel();
  };

  const handleSaveClick = () => {
    formRef.current?.submit();
  };

  const handleCopyToClipboard = () => {
    navigator.clipboard.writeText(previewContent);
    setCopyButtonText('┬íCopiado!');
    toast.success('Copiado al portapapeles');
    setTimeout(() => setCopyButtonText('Copiar'), 2000);
  };

  const handlePreviewClick = () => {
    if (!formRef.current) return;

    const content = formRef.current.getRenderedContent();

    setPreviewContent(content);
    setCopyButtonText('Copiar');
    setIsPreviewOpen(true);
  };

  return (
    <>
      <div className="flex h-full flex-col">
        <div className="flex items-center justify-between border-b p-3">
          <div className="flex items-center gap-2">
            <Button variant="outline" size="sm" onClick={handleCancel}>
              Cancelar
            </Button>
            <Button variant="outline" size="sm" onClick={handlePreviewClick}>
              <Eye className="mr-2 h-4 w-4" />
              Vista Previa
            </Button>
          </div>
          <div className="flex items-center gap-2">
            <Button onClick={handleSaveClick}>Crear Novedad</Button>
          </div>
        </div>
        <ScrollArea className="flex-1">
          <div className="p-4 sm:p-6 lg:p-8">
            <Card>
              <CardHeader>
                <CardTitle>{template.name}</CardTitle>
                <CardDescription>Completa los campos para generar el reporte.</CardDescription>
              </CardHeader>
              <CardContent>
                <ReportForm
                  ref={formRef}
                  template={template}
                  config={config}
                  initialData={finalInitialData}
                  onSubmit={handleCreateReport}
                  onDataChange={handleDataChange}
                />
              </CardContent>
            </Card>
          </div>
        </ScrollArea>
      </div>

      <Dialog open={isPreviewOpen} onOpenChange={setIsPreviewOpen}>
        <DialogContent className="max-h-[90vh] max-w-[90vw] sm:max-w-3xl flex flex-col">
          <DialogHeader>
            <DialogTitle>Vista Previa del Reporte</DialogTitle>
            <DialogDescription>
              Revisa el reporte generado. Puedes copiar el texto para usarlo donde necesites.
            </DialogDescription>
          </DialogHeader>
          <div className="flex-1 overflow-y-auto -mx-6 px-6">
            <Textarea
              readOnly
              value={previewContent}
              className="w-full h-full min-h-[50vh] bg-muted/50 font-mono text-sm whitespace-pre-wrap"
            />
          </div>
          <DialogFooter className="mt-auto pt-4">
            <Button type="button" onClick={handleCopyToClipboard}>
              {copyButtonText === 'Copiar' ? (
                <Copy className="mr-2 h-4 w-4" />
              ) : (
                <CheckIcon className="mr-2 h-4 w-4" />
              )}
              {copyButtonText}
            </Button>
            <DialogClose asChild>
              <Button type="button" variant="secondary">
                Cerrar
              </Button>
            </DialogClose>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

'use client';

import { useState, useEffect, useMemo, useRef, useCallback } from 'react';
import { Button } from '@/components/ui/button';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Textarea } from '@/components/ui/textarea';
import type { Report, Template, TemplateConfig, FormDataRecord } from '@/types';
import { Trash2, Copy, CheckIcon, FileText, Eye, Save } from 'lucide-react';
import { useTemplates } from '@/hooks/use-templates';
import { ReportForm, type ReportFormRef } from './report-form';
import { Label } from '@/components/ui/label';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogClose,
} from '@/components/ui/dialog';
import { debounce } from '@/lib/utils';
import { renderFinalReport } from '@/lib/template-parser';

interface ReportViewerProps {
  report: Report | null;
  onSave: (report: Report) => void;
  onDelete: (id: string) => void;
}

export function ReportViewer({ report, onSave, onDelete }: ReportViewerProps) {
  const formRef = useRef<ReportFormRef>(null);
  const [status, setStatus] = useState<'En proceso' | 'Finalizado'>('En proceso');
  const [copyButtonText, setCopyButtonText] = useState('Copiar');
  const [saveButtonText, setSaveButtonText] = useState('Guardar Cambios');

  const { templates, configs } = useTemplates();

  const [previewContent, setPreviewContent] = useState('');
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);

  const template = useMemo(
    () => (report ? templates.find((t) => t.id === report.templateId) : null),
    [report, templates]
  );
  const config = useMemo<TemplateConfig>(
    () =>
      report
        ? configs[report.templateId] || { fields: {}, sections: [], layout: [] }
        : { fields: {}, sections: [], layout: [] },
    [report, configs]
  );
  const isFinalizado = useMemo(() => status === 'Finalizado', [status]);

  const saveLogicRef = useRef<((formData: Record<string, any>) => void) | null>(null);

  useEffect(() => {
    saveLogicRef.current = async (formData: Record<string, any>) => {
      if (!report || !template) return;

      const content = renderFinalReport(template.content, formData, config, {});
      const newTitle = String(formData.titulo || formData.title || template.name);

      const finalReport: Report = {
        ...report,
        title: newTitle,
        content: content,
        formData: formData,
        status: status,
        timestamp: new Date().toISOString(),
      };
      await onSave(finalReport);
      setSaveButtonText('Guardado');
    };
  }, [report, template, config, status, onSave]);

  const debouncedSave = useMemo(
    () =>
      debounce((formData: Record<string, any>) => {
        saveLogicRef.current?.(formData);
      }, 30000),
    []
  );

  useEffect(() => {
    return () => {
      debouncedSave.flush();
    };
  }, [debouncedSave]);

  useEffect(() => {
    if (report) {
      setStatus(report.status || 'En proceso');
      setSaveButtonText('Guardar Cambios');
    }
  }, [report]);

  const handleCopyToClipboard = () => {
    navigator.clipboard.writeText(previewContent);
    setCopyButtonText('┬íCopiado!');
    setTimeout(() => setCopyButtonText('Copiar'), 2000);
  };

  const handleSave = async () => {
    if (!formRef.current) return;
    const formData = formRef.current.getValues();
    debouncedSave.cancel();
    await saveLogicRef.current?.(formData);
  };

  const handleStatusChange = async (newStatus: 'En proceso' | 'Finalizado') => {
    setStatus(newStatus);

    if (!formRef.current) return;
    const formData = formRef.current.getValues();
    debouncedSave.cancel();

    if (!report || !template) return;
    const content = renderFinalReport(template.content, formData, config, {});
    const newTitle = String(formData.titulo || formData.title || template.name);
    const finalReport: Report = {
      ...report,
      title: newTitle,
      content: content,
      formData: formData,
      status: newStatus,
      timestamp: new Date().toISOString(),
    };
    await onSave(finalReport);
    setSaveButtonText('Guardado');
  };

  const handlePreviewClick = () => {
    if (!formRef.current) return;

    const content = formRef.current.getRenderedContent();
    setPreviewContent(content);
    setCopyButtonText('Copiar');
    setIsPreviewOpen(true);
  };

  const handleDataChange = useCallback(
    (formData: Record<string, any>) => {
      setSaveButtonText('Guardar Cambios');
      debouncedSave(formData);
    },
    [debouncedSave]
  );

  if (!report) {
    return (
      <div className="flex h-full flex-col items-center justify-center bg-card text-center">
        <FileText className="h-12 w-12 text-muted-foreground" />
        <h3 className="mt-4 text-lg font-semibold">No hay reporte seleccionado</h3>
        <p className="text-muted-foreground">
          Selecciona un reporte de la lista para verlo o editarlo.
        </p>
      </div>
    );
  }

  if (!template) {
    return (
      <div className="flex h-full flex-col">
        <ScrollArea className="flex-1 p-6">
          <div className="flex flex-col items-center justify-center bg-card text-center">
            <FileText className="h-12 w-12 text-muted-foreground" />
            <h3 className="mt-4 text-lg font-semibold text-destructive">Error en la Plantilla</h3>
            <p className="text-muted-foreground">
              La plantilla de este reporte tiene un error o no se encuentra. No se puede editar,
              pero puedes ver su contenido original o eliminarlo.
            </p>
            <div className="mt-4 w-full max-w-2xl text-left">
              <Label>Contenido del Reporte Original</Label>
              <Textarea
                readOnly
                value={report.content}
                className="mt-2 font-mono text-sm flex-1 min-h-0"
                autoSize
              />
            </div>
            <Button variant="destructive" className="mt-6" onClick={() => onDelete(report.id)}>
              <Trash2 className="mr-2 h-4 w-4" />
              Eliminar Reporte
            </Button>
          </div>
        </ScrollArea>
      </div>
    );
  }

  return (
    <>
      <div className="flex h-full flex-col">
        <div className="flex items-center justify-between border-b p-3">
          <div className="flex items-center gap-2">
            <Button
              variant="ghost"
              size="icon"
              className="text-destructive"
              onClick={() => onDelete(report.id)}
            >
              <Trash2 className="h-4 w-4" />
            </Button>
            <Button variant="outline" size="sm" onClick={handlePreviewClick}>
              <Eye className="mr-2 h-4 w-4" />
              Vista Previa
            </Button>
          </div>
          <div className="flex items-center gap-2">
            <Select value={status} onValueChange={handleStatusChange}>
              <SelectTrigger id="report-status" className="w-[180px]">
                <SelectValue placeholder="Estatus..." />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="En proceso">En proceso</SelectItem>
                <SelectItem value="Finalizado">Finalizado</SelectItem>
              </SelectContent>
            </Select>
            <Button onClick={handleSave} disabled={isFinalizado || saveButtonText === 'Guardado'}>
              {saveButtonText === 'Guardado' ? (
                <CheckIcon className="mr-2 h-4 w-4" />
              ) : (
                <Save className="mr-2 h-4 w-4" />
              )}
              {saveButtonText}
            </Button>
          </div>
        </div>
        <ScrollArea className="flex-1">
          <div className="p-4 sm:p-6 lg:p-8">
            <Card>
              <CardHeader>
                <CardTitle>{report.title}</CardTitle>
              </CardHeader>
              <CardContent>
                <ReportForm
                  ref={formRef}
                  key={report.id}
                  template={template}
                  config={config}
                  initialData={report.formData}
                  onSubmit={() => { }} // Not used here, handled by manual save
                  disabled={isFinalizado}
                  onDataChange={handleDataChange}
                />
              </CardContent>
            </Card>
          </div>
        </ScrollArea>
      </div>

      <Dialog open={isPreviewOpen} onOpenChange={setIsPreviewOpen}>
        <DialogContent className="max-h-[90vh] max-w-[90vw] sm:max-w-3xl flex flex-col">
          <DialogHeader>
            <DialogTitle>Vista Previa del Reporte</DialogTitle>
            <DialogDescription>
              Revisa el reporte generado. Puedes copiar el texto para usarlo donde necesites.
            </DialogDescription>
          </DialogHeader>
          <div className="flex-1 overflow-y-auto -mx-6 px-6">
            <Textarea
              readOnly
              value={previewContent}
              className="w-full h-full min-h-[50vh] bg-muted/50 font-mono text-sm whitespace-pre-wrap"
            />
          </div>
          <DialogFooter className="mt-auto pt-4">
            <Button type="button" onClick={handleCopyToClipboard}>
              {copyButtonText === 'Copiar' ? (
                <Copy className="mr-2 h-4 w-4" />
              ) : (
                <CheckIcon className="mr-2 h-4 w-4" />
              )}
              {copyButtonText}
            </Button>
            <DialogClose asChild>
              <Button type="button" variant="secondary">
                Cerrar
              </Button>
            </DialogClose>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

import React, { useMemo } from 'react';
import { useFieldArray, Controller, useWatch, Control } from 'react-hook-form';
import { PlusCircle, Trash2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Separator } from '@/components/ui/separator';
import { cn } from '@/lib/utils';
import {
    TemplateConfig,
    SectionConfig,
    StaffRole,
    StaffMember,
    AppSettings,
    FormDataRecord,
} from '@/types';
import { evaluateCondition } from '@/lib/template-parser';
import { FieldRenderer } from './field-renderer';

export interface SectionRendererProps {
    section: SectionConfig;
    config: TemplateConfig;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    control: Control<any>;
    disabled?: boolean;
    roles: StaffRole[];
    rolesLoaded: boolean;
    activeGuardStaff: StaffMember[];
    predefinedValues: FormDataRecord;
    units: string[];
    setValue: (
        name: string,
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        value: any,
        options?: { shouldValidate?: boolean; shouldDirty?: boolean }
    ) => void;
    settings: AppSettings | null;
    isNested?: boolean;
    pathPrefix?: string;
}

export function SectionRenderer(props: SectionRendererProps) {
    const { section, control, pathPrefix = '' } = props;
    const condition = section.condition;

    // Always call useWatch, but conditionally enable it
    // We use a dummy path if no condition exists to satisfy hook rules
    const watchPath = condition
        ? pathPrefix
            ? `${pathPrefix}.${condition.fieldId}`
            : condition.fieldId
        : 'dummy_watch_path';

    const watchedFieldValue = useWatch({
        control,
        name: watchPath,
        disabled: !condition,
    });

    if (condition) {
        if (
            !evaluateCondition(
                watchedFieldValue,
                condition.operator || '=',
                condition.value
            )
        ) {
            return null;
        }
    }

    if (section.isRepeatable) {
        return <RepeatableSectionRenderer {...props} />;
    }

    return <SingleSectionRenderer {...props} />;
}

function RepeatableSectionRenderer(props: SectionRendererProps) {
    const {
        section,
        config,
        control,
        disabled,
        roles,
        rolesLoaded,
        activeGuardStaff,
        predefinedValues,
        units,
        setValue,
        settings,
        isNested,
        pathPrefix = '',
    } = props;

    const fieldNamePrefix = pathPrefix
        ? `${pathPrefix}.${section.id}`
        : section.id;
    const { fields, append, remove } = useFieldArray({
        control,
        name: fieldNamePrefix,
    });

    const defaultItem = useMemo(
        () =>
            section.fieldIds.reduce(
                (acc: FormDataRecord, fieldId: string) => ({
                    ...acc,
                    [fieldId]: predefinedValues.hasOwnProperty(fieldId)
                        ? predefinedValues[fieldId]
                        : '',
                }),
                {}
            ),
        [section.fieldIds, predefinedValues]
    );

    // Simplified UI for single-field repeatable sections
    if (section.fieldIds.length === 1) {
        const fieldId = section.fieldIds[0];
        if (!fieldId) return null;
        const fieldConfig = (config.fields || {})[fieldId];
        if (!fieldConfig) return null;

        const isFullWidth =
            fieldConfig.type === 'textarea' || fieldConfig.isFullWidth;

        const defaultSingleFieldItem: FormDataRecord = { [fieldId]: '' };

        return (
            <div
                className={cn(
                    'space-y-4',
                    !isNested && 'pt-4',
                    isNested && isFullWidth && 'sm:col-span-2'
                )}
            >
                {section.label &&
                    (isNested ? (
                        <Label className="text-sm font-medium">
                            {section.label}
                            {fieldConfig.required && (
                                <span className="text-destructive ml-1">*</span>
                            )}
                        </Label>
                    ) : (
                        <h3 className="text-lg font-semibold">
                            {section.label}
                            {fieldConfig.required && (
                                <span className="text-destructive ml-1">*</span>
                            )}
                        </h3>
                    ))}
                <div className="space-y-2">
                    {fields.map((item, index) => (
                        <div key={item.id} className="flex items-center gap-2">
                            <div className="flex-1">
                                <Controller
                                    name={`${fieldNamePrefix}.${index}.${fieldId}`}
                                    control={control}
                                    rules={{
                                        required: fieldConfig.required
                                            ? 'Este campo es obligatorio'
                                            : false,
                                    }}
                                    render={({ field, fieldState: { error } }) => (
                                        <div className="flex flex-col gap-1 w-full">
                                            <FieldRenderer
                                                fieldId={fieldId}
                                                fieldConfig={fieldConfig}
                                                roles={roles}
                                                rolesLoaded={rolesLoaded}
                                                units={units}
                                                staffOptions={activeGuardStaff}
                                                setValue={setValue}
                                                settings={settings}
                                                value={field.value}
                                                onChange={field.onChange}
                                                onBlur={field.onBlur}
                                                ref={field.ref}
                                                name={field.name}
                                                disabled={disabled}
                                                className={cn(error && 'border-destructive')}
                                            />
                                            {error && (
                                                <span className="text-[10px] text-destructive">
                                                    {error.message}
                                                </span>
                                            )}
                                        </div>
                                    )}
                                />
                            </div>
                            {!disabled && (
                                <Button
                                    type="button"
                                    variant="ghost"
                                    size="icon"
                                    className="h-9 w-9 text-destructive shrink-0"
                                    onClick={() => remove(index)}
                                >
                                    <Trash2 className="h-4 w-4" />
                                </Button>
                            )}
                        </div>
                    ))}
                </div>
                {!disabled && (
                    <Button
                        type="button"
                        variant="outline"
                        onClick={() => append(defaultSingleFieldItem)}
                    >
                        <PlusCircle className="mr-2 h-4 w-4" /> A├▒adir {fieldConfig.label}
                    </Button>
                )}
            </div>
        );
    }

    const isFullWidth = section.fieldIds.some((fid: string) => {
        const fc = config.fields[fid];
        return fc?.type === 'textarea' || fc?.isFullWidth;
    });

    // Simplified UI for multi-field repeatable sections
    return (
        <div
            className={cn(
                'space-y-4',
                !isNested && 'pt-4',
                isNested && isFullWidth && 'sm:col-span-2'
            )}
        >
            {section.label && (
                <h3 className="text-lg font-semibold">{section.label}</h3>
            )}
            <div className="space-y-3">
                {fields.map((field, index) => (
                    <div
                        key={field.id}
                        className="p-4 rounded-md border bg-muted/30 flex flex-col gap-4"
                    >
                        <div className="flex items-center justify-between">
                            <h4 className="font-medium">
                                {section.repeatableItemLabel
                                    ? `${section.repeatableItemLabel} #${String(
                                        index + 1
                                    ).padStart(2, '0')}`
                                    : `${section.label} #${String(index + 1).padStart(2, '0')}`}
                            </h4>
                            {!disabled && (
                                <Button
                                    type="button"
                                    variant="ghost"
                                    size="icon"
                                    className="h-7 w-7 text-destructive -mr-2 -mt-2"
                                    onClick={() => remove(index)}
                                >
                                    <Trash2 className="h-4 w-4" />
                                </Button>
                            )}
                        </div>
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-4 gap-y-6">
                            {(section.layout || section.fieldIds).map(
                                (fieldId: string, fIdx: number) => {
                                    if (
                                        fieldId.startsWith('section_') ||
                                        fieldId.startsWith('sec_') ||
                                        fieldId.startsWith('cond_')
                                    ) {
                                        // This is a nested section, render it.
                                        const nestedSection = config.sections.find(
                                            (s: SectionConfig) => s.id === fieldId
                                        );
                                        if (!nestedSection) return null;

                                        return (
                                            <div
                                                key={`${fieldId}-${fIdx}`}
                                                className="sm:col-span-2 3xl:col-span-3"
                                            >
                                                <SectionRenderer
                                                    section={nestedSection}
                                                    config={config}
                                                    control={control}
                                                    disabled={disabled}
                                                    roles={roles}
                                                    rolesLoaded={rolesLoaded}
                                                    activeGuardStaff={activeGuardStaff}
                                                    predefinedValues={predefinedValues}
                                                    units={units}
                                                    setValue={setValue}
                                                    settings={settings}
                                                    isNested={true}
                                                    pathPrefix={`${fieldNamePrefix}.${index}`}
                                                />
                                            </div>
                                        );
                                    }

                                    const fieldConfig = (config.fields || {})[fieldId];
                                    if (!fieldConfig) return null;
                                    const isFullWidth =
                                        fieldConfig.type === 'textarea' || fieldConfig.isFullWidth;
                                    const path = `${fieldNamePrefix}.${index}.${fieldId}`;

                                    return (
                                        <div
                                            key={fieldId}
                                            className={cn(
                                                'space-y-2',
                                                isFullWidth && 'sm:col-span-2'
                                            )}
                                        >
                                            <Label htmlFor={path}>
                                                {fieldConfig?.label || fieldId}
                                                {fieldConfig.required && (
                                                    <span className="text-destructive ml-1">*</span>
                                                )}
                                            </Label>
                                            <Controller
                                                name={path}
                                                control={control}
                                                rules={{
                                                    required: fieldConfig.required
                                                        ? 'Este campo es obligatorio'
                                                        : false,
                                                }}
                                                render={({ field, fieldState: { error } }) => (
                                                    <div className="flex flex-col gap-1">
                                                        <FieldRenderer
                                                            fieldId={fieldId}
                                                            fieldConfig={fieldConfig}
                                                            roles={roles}
                                                            rolesLoaded={rolesLoaded}
                                                            units={units}
                                                            staffOptions={activeGuardStaff}
                                                            setValue={setValue}
                                                            settings={settings}
                                                            value={field.value}
                                                            onChange={field.onChange}
                                                            onBlur={field.onBlur}
                                                            ref={field.ref}
                                                            name={field.name}
                                                            disabled={disabled}
                                                            className={cn(error && 'border-destructive')}
                                                        />
                                                        {error && (
                                                            <span className="text-[10px] text-destructive">
                                                                {error.message}
                                                            </span>
                                                        )}
                                                    </div>
                                                )}
                                            />
                                        </div>
                                    );
                                }
                            )}
                        </div>
                    </div>
                ))}
            </div>
            {!disabled && (
                <Button
                    type="button"
                    variant="outline"
                    onClick={() => append(defaultItem)}
                    className="mt-4"
                >
                    <PlusCircle className="mr-2 h-4 w-4" /> A├▒adir{' '}
                    {section.repeatableItemLabel || section.label}
                </Button>
            )}
        </div>
    );
}

