    );
}

import { Department, StaffRole } from '@/types';
import { generateId } from '@/lib/utils/id';
import { LEADER_ROLES } from '@/constants/roles';

// Estructura institucional predefinida
const INSTITUTIONAL_STRUCTURE = `
CARGOS GLOBALES
- Director
- Sub-Director
- Jefe de operaciones
- Jefe de los servicios
- Parque de armas
- Inspector├¡a general
- Investigaciones
- Sala de evidencia

COORDINACI├ôN DE VIGILANCIA Y PATRULLAJE MOTORIZADO
- Coordinador
- Jefe de los servicios
- Supervisor de primera l├¡nea
- Patrullero

COORDINACI├ôN DE VIGILANCIA Y PATRULLAJE VEHICULAR
- Coordinador
- Jefe de los servicios
- Supervisor de primera l├¡nea
- Patrullero de seguridad
- Conductor de unidad radiopatrullera

COORDINACI├ôN DE VIGILANCIA Y PATRULLAJE CICLISTA
- Coordinador
- Jefe de los servicios
- Supervisor de primera l├¡nea
- Patrullero

COORDINACI├ôN DE VIGILANCIA Y PATRULLAJE PUNTO A PIE
- Coordinador
- Jefe de los servicios
- Supervisor de primera l├¡nea
- Patrullero

GENERICO
- Auxiliar
- Jefe de guardia
- Supervisor
- Oficial de servicio
`;

export function getInstitutionalData() {
    const normalize = (s: string) =>
        s
            .normalize('NFD')
            .replace(/[\u0300-\u036f]/g, '')
            .toLowerCase()
            .trim();

    const lines = INSTITUTIONAL_STRUCTURE.split('\n');
    const newDepts: Department[] = [];
    const newRoles: StaffRole[] = [];

    let currentDeptId: string | 'global' | null = null;
    let deptCounter = 0;

    for (const line of lines) {
        const trimmed = line.trim();
        if (!trimmed) continue;

        if (!trimmed.startsWith('-')) {
            // Es un departamento
            if (normalize(trimmed) === 'cargos globales') {
                currentDeptId = 'global';
            } else if (normalize(trimmed) === 'generico') {
                currentDeptId = null; // Para todos
            } else {
                const id = generateId('dept');
                newDepts.push({
                    id,
                    name: trimmed,
                    staff: {},
                });
                currentDeptId = id;
                deptCounter++;
            }
        } else {
            // Es un cargo
            const roleName = trimmed.substring(1).trim();

            // Check if role already exists in our new list
            const existingRoleIndex = newRoles.findIndex(
                (r) => normalize(r.name) === normalize(roleName)
            );

            if (existingRoleIndex >= 0) {
                // Update existing role scope
                const role = newRoles[existingRoleIndex]!;
                if (currentDeptId && currentDeptId !== 'global') {
                    // Add dept to scope if not global
                    if (!role.departmentScope) role.departmentScope = [];
                    if (!role.departmentScope.includes(currentDeptId)) {
                        role.departmentScope.push(currentDeptId);
                    }
                }
                // If currentDeptId is 'global', clearing scope effectively makes it global
                // but we keep existing logic.
            } else {
                // Create new role
                const isLeader = Object.values(LEADER_ROLES).some((lr) => normalize(lr) === normalize(roleName));
                const role: StaffRole = {
                    name: roleName,
                    isSingle: isLeader,
                    departmentScope:
                        currentDeptId && currentDeptId !== 'global' ? [currentDeptId] : [], // Empty = Global
                    isHidden: false,
                    order: newRoles.length,
                };
                newRoles.push(role);
            }
        }
    }

    return { newDepts, newRoles };
}

import React from 'react';
import { useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { GripVertical, Trash2 } from 'lucide-react';

import { Button } from '@/components/ui/button';
import { Switch } from '@/components/ui/switch';
import { cn } from '@/lib/utils';
import { Department, StaffRole } from '@/types';

interface SortableRoleItemProps {
    role: StaffRole;
    index: number;
    departments: Department[];
    onRemoveFromList: () => void;
}

export function SortableRoleItem({
    role,
    index,
    departments,
    onRemoveFromList,
}: SortableRoleItemProps) {
    const {
        attributes,
        listeners,
        setNodeRef,
        transform,
        transition,
        isDragging,
    } = useSortable({ id: role.name });

    const style = {
        transform: CSS.Transform.toString(transform),
        transition,
        zIndex: isDragging ? 1 : 0,
        opacity: isDragging ? 0.3 : 1,
    };

    const scopeName =
        (role.departmentScope ?? []).length > 0
            ? departments.find((d) => d.id === (role.departmentScope ?? [])[0])?.name ||
            'Varios'
            : 'Global';

    return (
        <div
            ref={setNodeRef}
            style={style}
            className={cn(
                'flex items-center justify-between p-3 px-6 hover:bg-primary/5 transition-colors group',
                isDragging && 'bg-primary/10'
            )}
        >
            <div className="flex items-center gap-3 min-w-0">
                <div
                    {...attributes}
                    {...listeners}
                    className="text-muted-foreground hover:text-primary shrink-0 cursor-grab active:cursor-grabbing p-1 -ml-1 pl-0"
                >
                    <GripVertical className="h-4 w-4" />
                </div>
                <div className="flex items-center gap-3 min-w-0">
                    <div className="flex items-center justify-center h-6 w-6 rounded-full bg-primary/10 text-[10px] font-bold text-primary font-mono shrink-0">
                        {index + 1}
                    </div>
                    <div className="min-w-0">
                        <p className="text-sm font-medium truncate" title={role.name}>
                            {role.name}
                        </p>
                        <p className="text-[10px] text-muted-foreground uppercase font-mono">
                            {scopeName}
                        </p>
                    </div>
                </div>
            </div>
            <div className="flex items-center gap-2 shrink-0">
                <Button
                    variant="ghost"
                    size="icon"
                    className="h-7 w-7 text-muted-foreground hover:text-destructive hover:bg-destructive/10 opacity-0 group-hover:opacity-100 transition-all"
                    onClick={onRemoveFromList}
                    title="Quitar de la organizaci├│n"
                >
                    <Trash2 className="h-4 w-4" />
                </Button>
            </div>
        </div>
    );
}

