import { useTemplates } from '@/hooks/use-templates';
import { parseTemplate } from '@/lib/template-parser';
import { Save, HelpCircle, X, FileText, Plus, Trash2 } from 'lucide-react';
import { toast } from 'sonner';
import { validateTemplateSyntax } from '@/lib/validators';
import { ReportForm, ReportFormRef } from '@/components/report/report-form';
import type { Template, TemplateConfig, StatisticRule } from '@/types';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@/components/ui/dialog';
import { cn } from '@/lib/utils';
import { generateId } from '@/lib/utils/id';

interface TemplateBuilderProps {
  onOpenInfoDialog: () => void;
  initialTemplate?: Template | null;
  onUpdate?: (id: string, updates: Partial<Template>) => void;
  onAdd?: (newTemplate: Template) => void;
  onCancel?: () => void;
}

export function TemplateBuilder({
  onOpenInfoDialog,
  initialTemplate,
  onUpdate,
  onAdd,
  onCancel,
}: TemplateBuilderProps) {
  const [templateContent, setTemplateContent] = useState('');
  const [templateName, setTemplateName] = useState('');
  const [statisticsCategory, setStatisticsCategory] = useState('');
  const [statisticsRules, setStatisticsRules] = useState<StatisticRule[]>([]);

  // New state for report preview
  const formRef = useRef<ReportFormRef>(null);
  const [previewReportContent, setPreviewReportContent] = useState('');
  const [isPreviewDialogOpen, setIsPreviewDialogOpen] = useState(false);
  const [mobileView, setMobileView] = useState<'editor' | 'preview'>('editor');

  // Si estamos editando, usamos el ID de la plantilla original
  const isEditing = !!initialTemplate;

  useEffect(() => {
    if (initialTemplate) {
      setTemplateContent(initialTemplate.content);
      setTemplateName(initialTemplate.name);
      setStatisticsCategory(initialTemplate.statisticsCategory || '');
      setStatisticsRules(initialTemplate.statisticsRules || []);
    } else {
      setTemplateContent('');
      setTemplateName('');
      setStatisticsCategory('');
      setStatisticsRules([]);
    }
  }, [initialTemplate]);

  // State for UI toggles
  const [showRules, setShowRules] = useState(false);

  const { definitions } = useFieldDefinitions();
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  // Creates a temporary template object for the preview
  const previewTemplate = useMemo<Template>(
    () => ({
      id: 'preview',
      name: templateName || 'Vista Previa',
      content: templateContent,
      type: 'normal',
      isActive: true,
      statisticsCategory: statisticsCategory,
      statisticsRules: statisticsRules,
    }),
    [templateContent, templateName, statisticsCategory, statisticsRules]
  );

  // Creates a temporary config for the preview
  const previewConfig = useMemo<TemplateConfig>(() => {
    const { sections, layout } = parseTemplate(templateContent);
    return {
      sections,
      layout,
      fields: {},
    };
  }, [templateContent]);

  const insertText = (text: string) => {
    const textarea = textareaRef.current;
    if (!textarea) return;

    const start = textarea.selectionStart;
    const end = textarea.selectionEnd;
    const currentText = textarea.value;

    const newText = `${currentText.substring(0, start)}${text}${currentText.substring(end)}`;
    setTemplateContent(newText);

    setTimeout(() => {
      textarea.focus();
      textarea.selectionStart = textarea.selectionEnd = start + text.length;
    }, 0);
  };

  const handleSave = () => {
    if (!templateName.trim()) {
      toast.error('Por favor, dale un nombre a la plantilla.');
      return;
    }
    if (!templateContent.trim()) {
      toast.error('La plantilla no puede estar vac├¡a.');
      return;
    }

    const syntaxCheck = validateTemplateSyntax(templateContent);
    if (!syntaxCheck.valid) {
      toast.error(`Error de sintaxis: ${syntaxCheck.error}`);
      return;
    }

    if (isEditing && initialTemplate && onUpdate) {
      onUpdate(initialTemplate.id, {
        name: templateName,
        content: templateContent,
        statisticsCategory: statisticsCategory.trim() || undefined,
        statisticsRules: statisticsRules,
      });
      toast.success('Plantilla actualizada correctamente');
      if (onCancel) onCancel();
    } else if (onAdd) {
      const newTemplate: Template = {
        id: generateId('template'),
        name: templateName,
        content: templateContent,
        type: 'normal',
        isActive: true,
        statisticsCategory: statisticsCategory.trim() || undefined,
        statisticsRules: statisticsRules,
      };
      onAdd(newTemplate);
      setTemplateName('');
      setTemplateContent('');
      setStatisticsCategory('');
      setStatisticsRules([]);
      toast.success('Plantilla creada correctamente');
    }
  };

  const handlePreviewReport = () => {
    if (formRef.current) {
      const content = formRef.current.getRenderedContent();
      setPreviewReportContent(content);
      setIsPreviewDialogOpen(true);
    }
  };

  const globalTags = Object.keys(definitions).map((key) => definitions[key]);

  const commonSnippets = [
    { name: 'Secci├│n', value: '["T├¡tulo" {Campo}]' },
    { name: 'S. Repet', value: '["T├¡tulo"]* {Campo}' },
    { name: 'S. Cond', value: '[?{Campo}=Val]\n["T├¡tulo"]\n{Campo}\n[/]\n' },
    { name: 'Fecha', value: '{Fecha}' },
    { name: 'Hora', value: '{Hora}' },
    { name: 'Lista', value: '{Campo:dropdown(A=1|B=2)}' },
  ];

  const parseFieldNames = (content: string) => {
    const matches = content.match(/\{([a-zA-Z0-9_\u00C0-\u00FF\s]+)(:[^}]+)?\}/g);
    if (!matches) return [];
    return matches
      .map((m) => {
        const clean = m.replace('{', '').replace('}', '');
        return (clean.split(':')[0] || '').trim();
      })
      .filter((v, i, a) => a.indexOf(v) === i);
  };

  const availableFields = useMemo(() => parseFieldNames(templateContent), [templateContent]);

  return (
    <div className="flex-1 flex flex-col h-full min-h-0 overflow-hidden">
      {/* Mobile View Toggle */}
      <div className="lg:hidden flex p-2 gap-2 bg-muted/20 border-b">
        <Button
          variant={mobileView === 'editor' ? 'default' : 'ghost'}
          size="sm"
          className="flex-1 h-8 text-xs font-semibold"
          onClick={() => setMobileView('editor')}
        >
          Editor
        </Button>
        <Button
          variant={mobileView === 'preview' ? 'default' : 'ghost'}
          size="sm"
          className="flex-1 h-8 text-xs font-semibold"
          onClick={() => setMobileView('preview')}
        >
          Vista Previa Formulario
        </Button>
      </div>

      <div className="flex-1 grid grid-cols-1 lg:grid-cols-2 gap-4 h-full min-h-0 overflow-hidden p-0 lg:p-0">
        <Card
          className={cn(
            'flex flex-col h-full border-muted-foreground/20 shadow-md min-h-0 overflow-hidden',
            mobileView !== 'editor' && 'hidden lg:flex'
          )}
        >
          <CardHeader className="bg-muted/30 py-2.5 px-3 sm:py-3 sm:px-4">
            <div className="flex justify-between items-center gap-2">
              <div className="flex items-center gap-2 min-w-0">
                <CardTitle className="text-sm sm:text-base truncate">
                  {isEditing ? 'Editar Plantilla' : 'Nueva Plantilla'}
                </CardTitle>
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={onOpenInfoDialog}
                  className="h-7 w-7 sm:h-8 sm:w-8 shrink-0"
                >
                  <HelpCircle className="h-4 w-4" />
                </Button>
              </div>
              <div className="flex items-center gap-1 sm:gap-2 shrink-0">
                {isEditing && (
                  <Button
                    variant="ghost"
                    size="icon"
                    onClick={onCancel}
                    title="Cancelar"
                    className="h-7 w-7 sm:h-8 sm:w-8"
                  >
                    <X className="h-4 w-4" />
                  </Button>
                )}
                <Button onClick={handleSave} size="sm" className="h-8 px-2 sm:px-3 hidden sm:flex">
                  <Save className="sm:mr-2 h-4 w-4" />
                  <span>Guardar</span>
                </Button>
              </div>
            </div>
          </CardHeader>
          <CardContent className="flex-1 p-4 overflow-hidden flex flex-col gap-4">
            {/* Header Fields Section - Fixed at top */}
            <div className="flex flex-col gap-4 shrink-0">
              {/* Compact Header Row */}
              <div className="flex flex-col sm:flex-row gap-3">
                <div className="flex-1 space-y-1">
                  <Label htmlFor="template-name" className="text-[10px] sm:text-xs text-muted-foreground uppercase font-semibold">
                    Nombre
                  </Label>
                  <Input
                    id="template-name"
                    value={templateName}
                    onChange={(e) => setTemplateName(e.target.value)}
                    placeholder="Nombre de la plantilla"
                    className="h-9 text-sm"
                  />
                </div>
                <div className="flex-1 space-y-1">
                  <Label htmlFor="stats-category" className="text-[10px] sm:text-xs text-muted-foreground uppercase font-semibold">
                    Categor├¡a Estad├¡stica (Defecto)
                  </Label>
                  <Input
                    id="stats-category"
                    value={statisticsCategory}
                    onChange={(e) => setStatisticsCategory(e.target.value)}
                    placeholder="Ej: SIN NOVEDAD"
                    className="h-9 text-sm"
                  />
                </div>
              </div>

              {/* Collapsible Rules Section */}
              <div className="border rounded-md bg-muted/20">
                <button
                  type="button"
                  onClick={() => setShowRules(!showRules)}
                  className="w-full flex items-center justify-between p-2 text-xs font-semibold hover:bg-muted/40 transition-colors"
                >
                  <div className="flex items-center gap-2">
                    <span>
                      Reglas Condicionales{' '}
                      {statisticsRules.length > 0 && `(${statisticsRules.length})`}
                    </span>
                  </div>
                  <div className="text-muted-foreground">
                    {showRules ? 'Ocultar' : 'Mostrar/Editar'}
                  </div>
                </button>

                {showRules && (
                  <div className="p-2 border-t space-y-2">
                    <div className="flex items-center justify-between">
                      <span className="text-[10px] text-muted-foreground">
                        Reglas autom├íticas basadas en valores de campos.
                      </span>
                      <Button
                        size="sm"
                        variant="outline"
                        className="h-6 text-xs"
                        onClick={() =>
                          setStatisticsRules([
                            ...statisticsRules,
                            { fieldId: '', condition: '', category: '' },
                          ])
                        }
                      >
                        <Plus className="h-3 w-3 mr-1" /> Nueva Regla
                      </Button>
                    </div>
                    <div className="space-y-1 max-h-40 overflow-y-auto">
                      {statisticsRules.length === 0 && (
                        <p className="text-xs text-center text-muted-foreground py-2">Sin reglas.</p>
                      )}
                      {statisticsRules.map((rule, idx) => (
                        <div
                          key={idx}
                          className="flex gap-1 items-center bg-background p-1.5 rounded border"
                        >
                          <div className="grid grid-cols-2 sm:flex sm:flex-row gap-1 items-center flex-1 min-w-0">
                            <Select
                              value={rule.fieldId}
                              onValueChange={(val) => {
                                setStatisticsRules(prev => prev.map((r, i) =>
                                  i === idx ? { ...r, fieldId: val } : r
                                ));
                              }}
                            >
                              <SelectTrigger className="h-7 text-[10px] sm:text-xs">
                                <SelectValue placeholder="Campo" />
                              </SelectTrigger>
                              <SelectContent>
                                {availableFields.map((f) => (
                                  <SelectItem key={f} value={f}>
                                    {f}
                                  </SelectItem>
                                ))}
                              </SelectContent>
                            </Select>
                            <div className="flex items-center gap-1">
                              <span className="text-[10px] font-bold">=</span>
                              <Input
                                className="h-7 text-[10px] sm:text-xs min-w-0 flex-1"
                                placeholder="Valor"
                                value={rule.condition}
                                onChange={(e) => {
                                  const val = e.target.value;
                                  setStatisticsRules(prev => prev.map((r, i) =>
                                    i === idx ? { ...r, condition: val } : r
                                  ));
                                }}
                              />
                            </div>
                            <div className="flex items-center gap-1 col-span-2 sm:flex-1">
                              <span className="text-[10px]">ÔåÆ</span>
                              <Input
                                className="h-7 text-[10px] sm:text-xs min-w-0 flex-1"
                                placeholder="Categor├¡a"
                                value={rule.category}
                                onChange={(e) => {
                                  const val = e.target.value;
                                  setStatisticsRules(prev => prev.map((r, i) =>
                                    i === idx ? { ...r, category: val } : r
                                  ));
                                }}
                              />
                            </div>
                          </div>
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-7 w-7 text-muted-foreground hover:text-destructive shrink-0"
                            onClick={() =>
                              setStatisticsRules(statisticsRules.filter((_, i) => i !== idx))
                            }
                          >
                            <Trash2 className="h-3.5 w-3.5" />
                          </Button>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>

            {/* Unified Toolbar - Sticky above editor */}
            <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-2 p-1.5 bg-muted/30 rounded-md border text-xs shrink-0">
              <div className="flex items-center gap-2 min-w-0">
                <span className="hidden sm:inline font-semibold text-muted-foreground ml-1 shrink-0">Insertar:</span>
                <Select onValueChange={(val) => insertText(`{${val}}`)}>
                  <SelectTrigger className="h-8 sm:h-7 text-xs flex-1 sm:w-[130px] bg-background border-dashed">
                    <SelectValue placeholder="Etiqueta Global" />
                  </SelectTrigger>
                  <SelectContent>
                    {globalTags.map((tag, i) => (
                      <SelectItem key={tag?.label || i} value={tag?.label || ''}>
                        {tag?.label || ''}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="hidden sm:block w-px h-4 bg-border mx-1" />

              <div className="flex-1 overflow-x-auto no-scrollbar scroll-smooth">
                <div className="flex items-center gap-1 pb-0.5">
                  {commonSnippets.map((snippet) => (
                    <Button
                      key={snippet.name}
                      size="sm"
                      variant="ghost"
                      className="h-8 sm:h-7 px-2.5 text-xs bg-background/50 sm:bg-transparent hover:bg-background border border-transparent hover:border-border whitespace-nowrap shrink-0"
                      onClick={() => insertText(snippet.value)}
                      title={`Insertar: ${snippet.value}`}
                    >
                      {snippet.name}
                    </Button>
                  ))}
                </div>
              </div>
            </div>

            {/* Editor Area - This fills the rest of the vertical space */}
            <div className="flex-1 flex flex-col min-h-0 rounded-md border shadow-sm bg-background">
              <Textarea
                ref={textareaRef}
                value={templateContent}
                onChange={(e) => setTemplateContent(e.target.value)}
                className="flex-1 w-full font-mono text-sm leading-relaxed resize-none p-4 border-0 focus-visible:ring-0 overflow-y-auto"
                placeholder="Escribe el contenido de tu plantilla aqu├¡..."
              />
            </div>
          </CardContent>
        </Card>

        {/* Preview Panel (Card 2) */}
        <Card
          className={cn(
            'flex flex-col h-full border-muted-foreground/20 shadow-md bg-muted/10',
            mobileView !== 'preview' && 'hidden lg:flex'
          )}
        >
          <CardHeader className="bg-muted/30 py-3 px-4">
            <div className="flex justify-between items-center">
              <CardTitle className="text-base">Vista Previa</CardTitle>
              <Button
                variant="secondary"
                size="sm"
                onClick={handlePreviewReport}
                className="h-8 text-xs"
              >
                <FileText className="mr-2 h-3 w-3" />
                Generar Texto
              </Button>
            </div>
          </CardHeader>
          <CardContent className="flex-1 p-0 overflow-hidden relative">
            <div className="absolute inset-0 overflow-auto p-4">
              <div className="max-w-3xl mx-auto">
                <ReportForm
                  ref={formRef}
                  template={previewTemplate}
                  config={previewConfig}
                  onSubmit={() => { }}
                  disabled={false}
                />
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Mobile Preview & Actions Button (Floating) */}
      <div className="lg:hidden fixed bottom-6 right-6 z-50 flex flex-col gap-3">
        <Button
          onClick={handlePreviewReport}
          className="shadow-xl rounded-full h-12 w-12 bg-primary text-primary-foreground hover:scale-105 transition-transform"
          size="icon"
          title="Ver Vista Previa del Reporte"
        >
          <FileText className="h-6 w-6" />
        </Button>
        <Button
          onClick={handleSave}
          className="shadow-xl rounded-full h-12 w-12 bg-green-600 hover:bg-green-700 text-white hover:scale-105 transition-transform"
          size="icon"
          title="Guardar Plantilla"
        >
          <Save className="h-6 w-6" />
        </Button>
      </div>

      <Dialog open={isPreviewDialogOpen} onOpenChange={setIsPreviewDialogOpen}>
        <DialogContent className="max-w-3xl max-h-[80vh] flex flex-col">
          <DialogHeader>
            <DialogTitle>Vista Previa del Reporte</DialogTitle>
            <DialogDescription>
              Esta es una representaci├│n de c├│mo se ver├í el reporte final con el contenido actual.
            </DialogDescription>
          </DialogHeader>
          <div className="flex-1 overflow-auto bg-muted/20 p-4 rounded-md border mt-2">
            <pre className="whitespace-pre-wrap font-mono text-sm leading-relaxed">
              {previewReportContent}
            </pre>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

'use client';

import * as React from 'react';
import { useState, useMemo, useEffect, useCallback } from 'react';
import type {
  Template,
  TemplateConfig,
  FieldConfig,
  SectionConfig,
  FieldType,
  SnippetOption,
} from '@/types';
import { useFieldDefinitions } from '@/hooks/use-field-definitions';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Button } from '@/components/ui/button';
import { ScrollArea } from '@/components/ui/scroll-area';
import { parseTemplate } from '@/lib/template-parser';
import { Textarea } from '@/components/ui/textarea';
import { SnippetOptionEditor } from '@/components/snippet-option-editor';
import { Badge } from '@/components/ui/badge';
import { toast } from 'sonner';
import { STATISTICS_SECTIONS } from '@/constants/statistics';
import { ChevronDown, ChevronUp, Layers, BarChart3, Settings2 } from 'lucide-react';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';

const initialConfig: TemplateConfig = {
  fields: {},
  sections: [],
  layout: [],
};

const TargetFieldEditor = ({
  fieldId,
  config,
  allFields,
  onConfigChange,
  siblingFieldIds,
}: {
  fieldId: string;
  config: FieldConfig;
  allFields: Record<string, FieldConfig>;
  onConfigChange: (fieldId: string, newConfig: Partial<FieldConfig>) => void;
  siblingFieldIds: string[];
}) => {
  const textareaFields = useMemo(() => {
    return siblingFieldIds.filter((id) => allFields[id]?.type === 'textarea' && id !== fieldId);
  }, [siblingFieldIds, allFields, fieldId]);

  const handleTargetChange = (newTarget: string) => {
    onConfigChange(fieldId, { targetField: newTarget });
  };

  return (
    <div className="p-2 border rounded-md bg-muted/30 space-y-2 mt-2 ml-4">
      <div className="flex items-center gap-2">
        <Settings2 className="h-4 w-4 text-muted-foreground" />
        <Label className="text-xs font-semibold">Destino del Texto (para Dropdown)</Label>
      </div>
      <Select value={config.targetField} onValueChange={handleTargetChange}>
        <SelectTrigger className="h-8 text-xs">
          <SelectValue placeholder="Selecciona un campo..." />
        </SelectTrigger>
        <SelectContent>
          {textareaFields.map((id) => (
            <SelectItem key={id} value={id} className="text-xs">
              {id}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
      <p className="text-[10px] text-muted-foreground italic">
        El texto se enviar├í a este campo del reporte.
      </p>
    </div>
  );
};

const FieldEditor = React.memo(function FieldEditor({
  fieldId,
  fieldConfig,
  allFields,
  onConfigChange,
  siblingFieldIds,
  optionsDefinedInTemplate,
}: {
  fieldId: string;
  fieldConfig: FieldConfig;
  allFields: Record<string, FieldConfig>;
  onConfigChange: (fieldId: string, newConfig: Partial<FieldConfig>) => void;
  siblingFieldIds: string[];
  optionsDefinedInTemplate: boolean;
}) {
  const { definitions } = useFieldDefinitions();

  const globalDefinition = definitions[fieldId];
  const finalType = fieldConfig.type || globalDefinition?.type || 'text';
  const isTypeDefinedInTemplate = !!parseTemplate(`{${fieldId}:${finalType}}`).fieldTypes.get(
    fieldId
  );

  return (
    <div className="border rounded-md bg-background shadow-xs hover:border-primary/30 transition-all p-2 mb-2">
      <div className="flex items-center justify-between gap-4">
        <div className="flex items-center gap-2 overflow-hidden flex-1">
          <TooltipProvider>
            <Tooltip>
              <TooltipTrigger asChild>
                <div className="p-1.5 bg-muted rounded text-primary flex-shrink-0">
                  <Layers className="h-3.5 w-3.5" />
                </div>
              </TooltipTrigger>
              <TooltipContent>Campo: {fieldId}</TooltipContent>
            </Tooltip>
          </TooltipProvider>
          <Label className="text-xs font-semibold truncate" title={fieldId}>
            {fieldConfig.label || fieldId}
          </Label>
          {isTypeDefinedInTemplate && (
            <Badge
              variant="outline"
              className="text-[9px] py-0 px-1 bg-blue-50 text-blue-600 border-blue-200"
            >
              Fijo
            </Badge>
          )}
        </div>
        <Select
          value={finalType}
          onValueChange={(value) => onConfigChange(fieldId, { type: value as FieldType })}
          disabled={isTypeDefinedInTemplate}
        >
          <SelectTrigger className="w-[120px] h-8 text-[11px] bg-background">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="text" className="text-xs">
              Texto
            </SelectItem>
            <SelectItem value="textarea" className="text-xs">
              ├ürea de Texto
            </SelectItem>
            <SelectItem value="dropdown" className="text-xs">
              Dropdown
            </SelectItem>
            <SelectItem value="time-hlv" className="text-xs">
              Hora (HLV)
            </SelectItem>
            <SelectItem value="date" className="text-xs">
              Fecha
            </SelectItem>
            <SelectItem value="semantic" className="text-xs">
              Estad├¡stica Fija
            </SelectItem>
          </SelectContent>
        </Select>
      </div>
      {finalType === 'dropdown' && (
        <div className="mt-1">
          <TargetFieldEditor
            fieldId={fieldId}
            config={fieldConfig}
            allFields={allFields}
            onConfigChange={onConfigChange}
            siblingFieldIds={siblingFieldIds}
          />
          {!optionsDefinedInTemplate && (
            <div className="mt-2 scale-95 origin-top-left ml-4">
              <SnippetOptionEditor
                config={fieldConfig}
                onUpdate={(newConfig) => onConfigChange(fieldId, newConfig)}
              />
            </div>
          )}
        </div>
      )}
    </div>
  );
});

export function TemplateEditor({
  template,
  config,
  onConfigChange,
  onTemplateChange,
}: {
  template: Template;
  config: TemplateConfig;
  onConfigChange: (config: TemplateConfig) => void;
  onTemplateChange: (template: Template) => void;
}) {
  const [localTemplate, setLocalTemplate] = useState<Template>(template);
  const [localConfig, setLocalConfig] = useState<TemplateConfig>(() =>
    JSON.parse(JSON.stringify({ ...initialConfig, ...(config || {}) }))
  );
  const [optionsDefinedInTemplate, setOptionsDefinedInTemplate] = useState(
    new Map<string, boolean>()
  );
  const [hasChanges, setHasChanges] = useState(false);

  useEffect(() => {
    setLocalTemplate(template);
    setLocalConfig(config);

    const { templateOptions } = parseTemplate(template.content);
    setOptionsDefinedInTemplate(new Map(Array.from(templateOptions.keys()).map((k) => [k, true])));

    setHasChanges(false);
  }, [template, config]);

  const handleSaveChanges = () => {
    onConfigChange(localConfig);
    onTemplateChange(localTemplate);
    setHasChanges(false);
    toast.success('Cambios guardados correctamente en la plantilla.');
  };

  const handleFieldChange = useCallback((fieldId: string, newConfig: Partial<FieldConfig>) => {
    setLocalConfig((prev) => {
      const updatedFields = { ...prev.fields };

      updatedFields[fieldId] = {
        ...(updatedFields[fieldId] || { label: fieldId, type: 'text' }),
        ...newConfig,
      } as FieldConfig;

      if (newConfig.type === 'time-hlv') {
        Object.keys(updatedFields).forEach((fId) => {
          const field = updatedFields[fId];
          if (field && fId !== fieldId && field.type === 'time-hlv') {
            updatedFields[fId] = { ...field, type: 'text' };
          }
        });
      }

      return { ...prev, fields: updatedFields };
    });
    setHasChanges(true);
  }, []);

  const handleSectionChange = (sectionId: string, updates: Partial<SectionConfig>) => {
    setLocalConfig((prev) => {
      const updatedSections = (prev.sections || []).map((s) =>
        s.id === sectionId ? { ...s, ...updates } : s
      );
      return { ...prev, sections: updatedSections };
    });
    setHasChanges(true);
  };

  const statisticsOptions = useMemo(() => {
    return STATISTICS_SECTIONS.flatMap((s) =>
      s.items.map((i) => ({
        value: `${i.code} ${i.label}`,
        label: `${i.code} - ${i.label}`,
      }))
    );
  }, []);

  const sectionsById = useMemo(
    () =>
      (localConfig.sections || []).reduce(
        (acc, section) => {
          acc[section.id] = section;
          return acc;
        },
        {} as Record<string, SectionConfig>
      ),
    [localConfig.sections]
  );

  const addedTopLevelFields = useMemo(() => new Set<string>(), []);

  return (
    <Card className="h-full flex flex-col shadow-lg">
      <CardHeader className="flex flex-row items-start justify-between">
        <div>
          <CardTitle>Editor de Plantilla: {localTemplate.name}</CardTitle>
          <CardDescription>
            Configura los tipos de campo. La estructura se define en el archivo .txt.
          </CardDescription>
        </div>
        <Button onClick={handleSaveChanges} disabled={!hasChanges}>
          {hasChanges ? 'Guardar Cambios' : 'Guardado'}
        </Button>
      </CardHeader>
      <ScrollArea className="flex-1 w-full">
        <CardContent className="pt-2">
          <div className="space-y-2 mb-6">
            <Label htmlFor="template-name">Nombre de la Plantilla</Label>
            <Input
              id="template-name"
              value={localTemplate.name}
              onChange={(e) => {
                setLocalTemplate((p) => ({ ...p, name: e.target.value }));
                setHasChanges(true);
              }}
            />
          </div>

          <div className="border-t pt-6">
            <h3 className="font-semibold text-lg mb-4">Estructura del Formulario</h3>

            <div className="space-y-4 p-1 rounded-md bg-muted/30">
              {(localConfig.layout || []).map((itemId, index) => {
                if (
                  itemId.startsWith('section_') ||
                  itemId.startsWith('sec_') ||
                  itemId.startsWith('cond_')
                ) {
                  const section = sectionsById[itemId];
                  if (!section) return null;
                  return (
                    <Card
                      key={`${section.id}-${index}`}
                      className="bg-background overflow-hidden shadow-sm border-l-4 border-l-primary/30"
                    >
                      <CardHeader className="p-3 bg-muted/40 border-b">
                        <div className="flex flex-col gap-2">
                          <div className="flex items-center justify-between">
                            <CardTitle className="text-sm font-bold flex items-center gap-2 uppercase tracking-tight">
                              {section.label}
                              {section.isRepeatable && (
                                <Badge
                                  variant="secondary"
                                  className="text-[10px] h-5 bg-primary/10 text-primary border-primary/20"
                                >
                                  Repetible
                                </Badge>
                              )}
                            </CardTitle>
                          </div>

                          <div className="flex items-center gap-2 mt-1">
                            <BarChart3 className="h-3.5 w-3.5 text-muted-foreground" />
                            <Select
                              value={section.statisticsCategory || 'none'}
                              onValueChange={(val) =>
                                handleSectionChange(section.id, {
                                  statisticsCategory: val === 'none' ? undefined : val,
                                })
                              }
                            >
                              <SelectTrigger className="h-7 text-[10px] w-full bg-background/50 border-dashed">
                                <SelectValue placeholder="Anexar Estad├¡stica..." />
                              </SelectTrigger>
                              <SelectContent>
                                <SelectItem value="none" className="text-xs italic">
                                  Niguna estad├¡stica
                                </SelectItem>
                                {statisticsOptions.map((opt) => (
                                  <SelectItem
                                    key={opt.value}
                                    value={opt.value}
                                    className="text-[10px]"
                                  >
                                    {opt.label}
                                  </SelectItem>
                                ))}
                              </SelectContent>
                            </Select>
                          </div>
                        </div>
                      </CardHeader>
                      <CardContent className="p-2 space-y-0.5 bg-muted/5">
                        {section.layout?.map((fieldId, fieldIdx) => {
                          const fieldConfig = localConfig.fields[fieldId];
                          if (!fieldConfig) return null;

                          return (
                            <FieldEditor
                              key={`${section.id}-${fieldId}-${fieldIdx}`}
                              fieldId={fieldId}
                              fieldConfig={fieldConfig}
                              allFields={localConfig.fields}
                              onConfigChange={handleFieldChange}
                              siblingFieldIds={section.fieldIds}
                              optionsDefinedInTemplate={
                                optionsDefinedInTemplate.get(fieldId) || false
                              }
                            />
                          );
                        })}
                        {section.fieldIds.length === 0 && (
                          <p className="text-[11px] text-muted-foreground text-center p-2 italic">
                            Sin campos definidos.
                          </p>
                        )}
                      </CardContent>
                    </Card>
                  );
                } else if (itemId === 'section_separator' || itemId === 'sec_separator') {
                  return <div key={`${itemId}-${index}`} className="h-px bg-foreground/20 my-4" />;
                } else {
                  const fieldId = itemId;
                  const fieldConfig = localConfig.fields[fieldId];
                  if (!fieldConfig || fieldConfig.type === 'predefined') return null;

                  addedTopLevelFields.add(fieldId);

                  return (
                    <FieldEditor
                      key={`top-${fieldId}-${index}`}
                      fieldId={fieldId}
                      fieldConfig={fieldConfig}
                      allFields={localConfig.fields}
                      onConfigChange={handleFieldChange}
                      siblingFieldIds={Array.from(addedTopLevelFields)}
                      optionsDefinedInTemplate={optionsDefinedInTemplate.get(fieldId) || false}
                    />
                  );
                }
              })}
              {(localConfig.layout || []).length === 0 && (
                <div className="text-center p-6 border-2 border-dashed rounded-md">
                  <p className="text-muted-foreground">
                    No se detectaron campos o secciones en la plantilla.
                  </p>
                  <p className="text-sm text-muted-foreground mt-1">
                    Verifica la sintaxis <code>{`{campo}`}</code> o <code>["Secci├│n"...]</code> en
                    tu archivo.
                  </p>
                </div>
              )}
            </div>
          </div>
        </CardContent>
      </ScrollArea>
    </Card>
  );
}

'use client';

import React, { useState, KeyboardEvent, useRef, forwardRef } from 'react';
import { Input } from './input';
import { Badge } from './badge';
import { X, ChevronsUpDown } from 'lucide-react';
import { cn } from '@/lib/utils';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Button } from '@/components/ui/button';

interface MultiInputProps {
  value: string[];
  onChange: (value: string[] | string) => void;
  options?: string[];
  placeholder?: string;
  disabled?: boolean;
  isSingle?: boolean;
  className?: string; // Added className
  onBlur?: () => void; // Added onBlur
}

export const MultiInput = forwardRef<HTMLInputElement, MultiInputProps>(
  (
    {
      value = [],
      onChange,
      options = [],
      placeholder,
      disabled,
      isSingle = false,
      className,
      onBlur,
    },
    ref
  ) => {
    const [inputValue, setInputValue] = useState('');
    const [open, setOpen] = useState(false);
    const internalInputRef = useRef<HTMLInputElement>(null);

    const handleAddValue = (newValue: string) => {
      const trimmed = newValue.trim();
      if (isSingle) {
        onChange(trimmed);
      } else {
        if (trimmed && !value.includes(trimmed)) {
          onChange([...value, trimmed]);
        }
      }
      setInputValue('');
    };

    const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleAddValue(inputValue);
        setOpen(false);
      } else if (e.key === 'Backspace' && inputValue === '' && value.length > 0 && !isSingle) {
        const lastValue = value[value.length - 1];
        if (lastValue) handleRemoveValue(lastValue);
      }
    };

    const handleRemoveValue = (valueToRemove: string) => {
      onChange(value.filter((v) => v !== valueToRemove));
    };

    const handleSelectOption = (option: string) => {
      handleAddValue(option);
      setOpen(false);
      internalInputRef.current?.focus();
    };

    const displayValue = isSingle ? (Array.isArray(value) ? value[0] || '' : value) : inputValue;

    const currentValuesSet = new Set(value);

    const filteredOptions = options.filter(
      (option) =>
        !currentValuesSet.has(option) && option.toLowerCase().includes(displayValue.toLowerCase())
    );

    return (
      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger asChild>
          <div
            role="combobox"
            aria-expanded={open}
            className={cn(
              'flex flex-wrap items-center gap-2 rounded-md border border-input p-1.5 min-h-10 relative bg-background',
              disabled && 'cursor-not-allowed opacity-50 bg-muted',
              className // Apply className to container
            )}
            onClick={() => !disabled && internalInputRef.current?.focus()}
          >
            {!isSingle &&
              value.map((item) => (
                <Badge key={item} variant="secondary" className="gap-1.5 pr-1 text-sm">
                  {item}
                  {!disabled && (
                    <button
                      type="button"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleRemoveValue(item);
                      }}
                      className="rounded-full hover:bg-muted-foreground/20"
                    >
                      <X className="h-3 w-3" />
                    </button>
                  )}
                </Badge>
              ))}
            <Input
              ref={(node) => {
                internalInputRef.current = node;
                if (typeof ref === 'function') ref(node);
                else if (ref) ref.current = node;
              }}
              value={isSingle ? (Array.isArray(value) ? value[0] || '' : value || '') : inputValue}
              onChange={(e) => {
                if (isSingle) {
                  onChange(e.target.value);
                } else {
                  setInputValue(e.target.value);
                }
              }}
              onBlur={onBlur} // Pass onBlur
              onKeyDown={handleKeyDown}
              placeholder={placeholder}
              disabled={disabled}
              className="flex-1 border-0 shadow-none focus-visible:ring-0 p-0 h-8 bg-transparent min-w-[100px]"
            />
            <ChevronsUpDown className="h-4 w-4 shrink-0 opacity-50 absolute right-3 top-1/2 -translate-y-1/2" />
          </div>
        </PopoverTrigger>
        <PopoverContent
          className="w-[var(--radix-popover-trigger-width)] p-0"
          onOpenAutoFocus={(e) => e.preventDefault()}
        >
          <div className="p-1 max-h-60 overflow-y-auto">
            {filteredOptions.length > 0 ? (
              filteredOptions.map((option) => (
                <Button
                  key={option}
                  variant="ghost"
                  className="w-full justify-start h-8 px-2 font-normal"
                  onClick={() => handleSelectOption(option)}
                >
                  {option}
                </Button>
              ))
            ) : (
              <p className="p-2 text-center text-xs text-muted-foreground">
                {options.length > 0 && currentValuesSet.size === options.length
                  ? 'Todas las opciones seleccionadas.'
                  : 'No hay opciones disponibles.'}
              </p>
            )}
            {displayValue &&
              !options.includes(displayValue) &&
              !currentValuesSet.has(displayValue) && (
                <Button
                  variant="ghost"
                  className="w-full justify-start h-8 px-2 font-normal text-primary"
                  onClick={() => handleSelectOption(displayValue)}
                >
                  A├▒adir "{displayValue}"
                </Button>
              )}
          </div>
        </PopoverContent>
      </Popover>
    );
  }
);
MultiInput.displayName = 'MultiInput';

'use client';

import * as React from 'react';

import { cn } from '@/lib/utils';

export interface TextareaProps extends React.TextareaHTMLAttributes<HTMLTextAreaElement> {
  autoSize?: boolean;
}

const Textarea = React.forwardRef<HTMLTextAreaElement, TextareaProps>(
  ({ className, autoSize = true, ...props }, ref) => {
    const internalRef = React.useRef<HTMLTextAreaElement>(null);
    React.useImperativeHandle(ref, () => internalRef.current!);

    const { rows, ...rest } = props;

    React.useLayoutEffect(() => {
      const textarea = internalRef.current;
      if (autoSize && textarea) {
        // Reset height to recalculate scrollHeight
        textarea.style.height = 'inherit';
        // Set height to scrollHeight to fit content
        textarea.style.height = `${textarea.scrollHeight}px`;
      }
    }, [props.value, autoSize]);

    return (
      <textarea
        className={cn(
          'flex w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50',
          autoSize ? 'resize-none overflow-hidden' : '',
          className
        )}
        ref={internalRef}
        autoComplete="off"
        autoCorrect="off"
        spellCheck="false"
        {...rest}
      />
    );
  }
);
Textarea.displayName = 'Textarea';

export { Textarea };

