'use client';

import { useState, useEffect, useCallback } from 'react';
import { logger } from '@/lib/logger';

export interface ConnectionStatus {
    isOnline: boolean;
    isServerUp: boolean;
    updateAvailable: boolean;
    checkServerStatus: () => Promise<void>;
    handleUpdate: () => Promise<void>;
}

export function useConnectionStatus(): ConnectionStatus {
    const [isOnline, setIsOnline] = useState(true);
    const [isServerUp, setIsServerUp] = useState(true);
    const [updateAvailable, setUpdateAvailable] = useState(false);

    const checkServerStatus = useCallback(async () => {
        if (!navigator.onLine) {
            setIsServerUp(false);
            return;
        }

        try {
            const controller = new AbortController();
            const id = setTimeout(() => controller.abort(), 5000);
            const response = await fetch('/api/health', {
                method: 'HEAD',
                signal: controller.signal,
                cache: 'no-store'
            });
            clearTimeout(id);
            setIsServerUp(response.ok);
        } catch (error) {
            logger.warn("Server health check failed:", error);
            setIsServerUp(false);
        }
    }, []);

    useEffect(() => {
        setIsOnline(navigator.onLine);

        const handleOnline = () => {
            setIsOnline(true);
            checkServerStatus();
        };
        const handleOffline = () => {
            setIsOnline(false);
            setIsServerUp(false);
        };

        window.addEventListener('online', handleOnline);
        window.addEventListener('offline', handleOffline);

        // Initial server check
        if (navigator.onLine) {
            checkServerStatus();
        } else {
            setIsServerUp(false);
        }

        // Periodic server check (every 30 seconds to be less aggressive than before but still useful)
        const interval = setInterval(() => {
            if (navigator.onLine) {
                checkServerStatus();
            }
        }, 30000);

        // Check for SW updates
        if (typeof window !== 'undefined' && 'serviceWorker' in navigator) {
            navigator.serviceWorker.ready.then((registration) => {
                const checkWaiting = () => {
                    if (registration.waiting) {
                        setUpdateAvailable(true);
                    }
                };

                checkWaiting();

                registration.addEventListener('updatefound', () => {
                    const newWorker = registration.installing;
                    if (newWorker) {
                        newWorker.addEventListener('statechange', () => {
                            if (newWorker.state === 'installed' && navigator.serviceWorker.controller) {
                                setUpdateAvailable(true);
                            }
                        });
                    }
                });
            });

            const handleControllerChange = () => {
                window.location.reload();
            };
            navigator.serviceWorker.addEventListener('controllerchange', handleControllerChange);

            return () => {
                window.removeEventListener('online', handleOnline);
                window.removeEventListener('offline', handleOffline);
                navigator.serviceWorker.removeEventListener('controllerchange', handleControllerChange);
                clearInterval(interval);
            };
        }

        return () => {
            window.removeEventListener('online', handleOnline);
            window.removeEventListener('offline', handleOffline);
            clearInterval(interval);
        };
    }, [checkServerStatus]);

    const handleUpdate = useCallback(async () => {
        if (typeof window !== 'undefined' && 'serviceWorker' in navigator) {
            const registration = await navigator.serviceWorker.ready;
            if (registration.waiting) {
                registration.waiting.postMessage({ type: 'SKIP_WAITING' });
            } else {
                window.location.reload();
            }
        } else {
            window.location.reload();
        }
    }, []);

    return {
        isOnline,
        isServerUp,
        updateAvailable,
        checkServerStatus,
        handleUpdate
    };
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import type { FieldConfig } from '@/types';
import { format } from 'date-fns';
import { useSettings } from './use-settings';
import { useGuards } from './use-guards';
import { useDatabase } from '@/lib/db/db-provider';
import { logger } from '@/lib/logger';

const defaultDefinitions: Record<string, FieldConfig> = {
  Municipio: { label: 'Municipio', type: 'predefined', value: '', sectionId: 'default' },
  Estado: { label: 'Estado', type: 'predefined', value: '', sectionId: 'default' },
  Director: { label: 'Director', type: 'predefined', value: '', sectionId: 'default' },
  'Jefe de Operaciones': {
    label: 'Jefe de Operaciones',
    type: 'predefined',
    value: '',
    sectionId: 'default',
  },
  REDAN: { label: 'REDAN', type: 'predefined', value: '', sectionId: 'default' },
  ZOEDAN: { label: 'ZOEDAN', type: 'predefined', value: '', sectionId: 'default' },
  Fecha: {
    label: 'Fecha',
    type: 'date',
    value: format(new Date(), 'yyyy-MM-dd'),
    sectionId: 'default',
  },
  Hora: { label: 'Hora', type: 'time-hlv', value: '', sectionId: 'default' },
  Reporta: { label: 'Reporta', type: 'predefined', value: '', sectionId: 'default' },
  Analista: { label: 'Analista', type: 'predefined', value: '', sectionId: 'default' },
};

export function useFieldDefinitions() {
  const db = useDatabase();
  const { settings, isLoaded: settingsLoaded } = useSettings();
  const { guards, isLoaded: guardsLoaded } = useGuards();

  const [definitions, setDefinitions] = useState<Record<string, FieldConfig>>({});
  const [isLoaded, setIsLoaded] = useState(false);

  useEffect(() => {
    if (!db) return;

    const sub = db.field_definitions.find().$.subscribe((data) => {
      if (data.length > 0) {
        const defMap: Record<string, FieldConfig> = {};
        data.forEach((d) => {
          const item = d.toJSON();
          defMap[item.id] = item.config as FieldConfig;
        });

        // Dynamic date update for 'Fecha' if it exists
        if (defMap['Fecha']) {
          defMap['Fecha'] = {
            ...defMap['Fecha'],
            value: format(new Date(), 'yyyy-MM-dd'),
          };
        }

        setDefinitions(defMap);
      } else {
        // Initial insert
        const entries = Object.entries(defaultDefinitions).map(([id, config]) => ({ id, config }));
        db.field_definitions
          .bulkInsert(entries)
          .catch((err) => logger.error('Failed to insert default field definitions', err, { feature: 'FieldDefinitions' }));
      }
      setIsLoaded(true);
    });

    return () => sub.unsubscribe();
  }, [db]);

  const saveDefinitions = useCallback(
    async (newDefinitions: Record<string, FieldConfig>) => {
      if (!db) return;
      try {
        const entries = Object.entries(newDefinitions).map(([id, config]) => ({ id, config }));
        const allDocs = await db.field_definitions.find().exec();
        const newIds = new Set(Object.keys(newDefinitions));
        const toDelete = allDocs.filter((d) => !newIds.has(d.id));
        if (toDelete.length > 0) await Promise.all(toDelete.map((d) => d.remove()));
        await db.field_definitions.bulkUpsert(entries);
      } catch (error) {
        logger.error('Failed to save field definitions', error, { feature: 'FieldDefinitions' });
      }
    },
    [db]
  );

  const updateDefinition = useCallback(
    async (fieldName: string, newConfig: FieldConfig) => {
      if (!db) return;
      try {
        await db.field_definitions.upsert({ id: fieldName, config: newConfig });
      } catch (error) {
        logger.error('Failed to update field definition', error, { feature: 'FieldDefinitions', metadata: { fieldName } });
      }
    },
    [db]
  );

  const removeDefinition = useCallback(
    async (fieldName: string) => {
      if (!db) return;
      try {
        const doc = await db.field_definitions.findOne(fieldName).exec();
        if (doc) await doc.remove();
      } catch (error) {
        logger.error('Failed to remove field definition', error, { feature: 'FieldDefinitions', metadata: { fieldName } });
      }
    },
    [db]
  );

  const clearAllDefinitions = useCallback(async () => {
    if (!db) return;
    try {
      const allDocs = await db.field_definitions.find().exec();
      await Promise.all(allDocs.map((d) => d.remove()));
      const entries = Object.entries(defaultDefinitions).map(([id, config]) => ({ id, config }));
      await db.field_definitions.bulkInsert(entries);
    } catch (error) {
      logger.error('Failed to clear field definitions', error, { feature: 'FieldDefinitions' });
    }
  }, [db]);

  return {
    definitions,
    updateDefinition,
    removeDefinition,
    saveDefinitions,
    isLoaded: isLoaded && settingsLoaded && guardsLoaded,
    clearAllDefinitions,
  };
}

'use client';

import { useCallback } from 'react';
import { useDatabase } from '@/lib/db/db-provider';
import type { PersonnelAssignment, Staff } from '@/types';
import { logger } from '@/lib/logger';
import { format } from 'date-fns';

/**
 * Hook for managing personnel assignment history.
 * Tracks which guard and role staff members were assigned to on specific dates.
 */
export function usePersonnelHistory() {
    const db = useDatabase();

    /**
     * Records assignments for a given guard/department on a specific date.
     * Creates or updates history entries for all staff members in the provided staff object.
     */
    const recordAssignments = useCallback(
        async (guardId: string, staff: Staff, date: string) => {
            if (!db) return;

            try {
                const timestamp = new Date().toISOString();
                const assignments: PersonnelAssignment[] = [];

                Object.entries(staff).forEach(([roleName, staffList]) => {
                    staffList.forEach((member) => {
                        if (!member.personnelId && !member.id) return;

                        const pId = member.personnelId || member.id;
                        assignments.push({
                            id: `${pId}_${date}`,
                            personnelId: pId,
                            date,
                            guardId,
                            roleName,
                            timestamp,
                        });
                    });
                });

                if (assignments.length > 0) {
                    await db.personnel_assignment_history.bulkUpsert(assignments);
                    logger.info('Recorded personnel assignments', {
                        guardId,
                        date,
                        count: assignments.length,
                    });
                }
            } catch (error) {
                logger.error('Failed to record personnel assignments', error, {
                    feature: 'PersonnelHistory',
                    metadata: { guardId, date },
                });
            }
        },
        [db]
    );

    /**
     * Fetches the assignment history for a specific personnel member.
     */
    const getHistory = useCallback(
        async (personnelId: string) => {
            if (!db) return [];

            try {
                const docs = await db.personnel_assignment_history
                    .find({
                        selector: { personnelId },
                        sort: [{ date: 'desc' }],
                    })
                    .exec();

                return docs.map((d) => d.toJSON()) as PersonnelAssignment[];
            } catch (error) {
                logger.error('Failed to fetch personnel history', error, {
                    feature: 'PersonnelHistory',
                    metadata: { personnelId },
                });
                return [];
            }
        },
        [db]
    );

    /**
     * Fetches the assignment for a specific personnel member on a specific date.
     */
    const getAssignmentForDate = useCallback(
        async (personnelId: string, date: string) => {
            if (!db) return null;

            try {
                const doc = await db.personnel_assignment_history.findOne(`${personnelId}_${date}`).exec();
                return doc ? (doc.toJSON() as PersonnelAssignment) : null;
            } catch (error) {
                logger.error('Failed to fetch assignment for date', error, {
                    feature: 'PersonnelHistory',
                    metadata: { personnelId, date },
                });
                return null;
            }
        },
        [db]
    );

    return {
        recordAssignments,
        getHistory,
        getAssignmentForDate,
    };
}

'use client';

import { useMemo } from 'react';
import { logger } from '@/lib/logger';
import { useReports } from './use-reports';
import { useTemplates } from './use-templates';
import { useAddresses } from './use-addresses';
import { format } from 'date-fns/format';
import { startOfWeek } from 'date-fns/startOfWeek';
import { eachDayOfInterval } from 'date-fns/eachDayOfInterval';
import { subDays } from 'date-fns/subDays';
import { es } from 'date-fns/locale';

export function useStats() {
  const { reports } = useReports();
  const { templates } = useTemplates();
  const { addresses } = useAddresses();

  const stats = useMemo(() => {
    // Total reportes
    const totalReports = reports.length;

    // Reportes por plantilla
    const reportsByTemplate: Record<string, number> = {};
    reports.forEach((report) => {
      const templateId = report.templateId;
      if (templateId) {
        reportsByTemplate[templateId] = (reportsByTemplate[templateId] || 0) + 1;
      }
    });

    // Reportes por mes (├║ltimos 6 meses)
    const reportsByMonth: Record<string, number> = {};
    reports.forEach((report) => {
      if (report.timestamp) {
        try {
          const month = format(new Date(report.timestamp), 'MMM yyyy', { locale: es });
          reportsByMonth[month] = (reportsByMonth[month] || 0) + 1;
        } catch (error) {
          logger.warn('Invalid timestamp for report', { feature: 'Stats', metadata: { reportId: report.id } });
        }
      }
    });

    // Reportes por d├¡a de la semana (├║ltimos 7 d├¡as)
    const last7Days = eachDayOfInterval({
      start: subDays(new Date(), 6),
      end: new Date(),
    });

    const reportsByDay = last7Days.map((day) => {
      const dayKey = format(day, 'EEE', { locale: es });
      const dayFull = format(day, 'yyyy-MM-dd');
      const count = reports.filter((r) => {
        if (!r.timestamp) return false;
        try {
          const reportDate = format(new Date(r.timestamp), 'yyyy-MM-dd');
          return reportDate === dayFull;
        } catch (error) {
          return false;
        }
      }).length;

      return {
        day: dayKey,
        reportes: count,
      };
    });

    // Top plantilla m├ís usada
    const templateEntries = Object.entries(reportsByTemplate);
    const topTemplateEntry =
      templateEntries.length > 0 ? templateEntries.sort(([, a], [, b]) => b - a)[0] : null;

    const topTemplate = topTemplateEntry
      ? {
        id: topTemplateEntry[0],
        count: topTemplateEntry[1],
        name: templates.find((t) => t.id === topTemplateEntry[0])?.name || 'Desconocida',
      }
      : null;

    // Top 5 plantillas
    const topTemplates = templateEntries
      .sort(([, a], [, b]) => b - a)
      .slice(0, 5)
      .map(([id, count]) => ({
        id,
        name: templates.find((t) => t.id === id)?.name || 'Desconocida',
        count,
      }));

    // Promedio de reportes por d├¡a
    const validReports = reports.filter((r) => r.timestamp);
    const daysWithReports = new Set(
      validReports
        .map((r) => {
          try {
            return format(new Date(r.timestamp), 'yyyy-MM-dd');
          } catch (error) {
            return '';
          }
        })
        .filter((d) => d !== '')
    ).size;
    const averagePerDay =
      daysWithReports > 0 ? (validReports.length / daysWithReports).toFixed(1) : '0';

    // Reportes recientes (├║ltimos 5)
    const recentReports = [...reports]
      .filter((r) => r.timestamp)
      .sort((a, b) => {
        try {
          return new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime();
        } catch (error) {
          return 0;
        }
      })
      .slice(0, 5)
      .map((report) => ({
        ...report,
        templateName: templates.find((t) => t.id === report.templateId)?.name || 'Sin plantilla',
      }));

    return {
      totalReports,
      reportsByTemplate,
      reportsByMonth,
      reportsByDay,
      topTemplate,
      topTemplates,
      totalTemplates: templates.length,
      activeTemplates: templates.filter((t) => t.isActive).length,
      inactiveTemplates: templates.filter((t) => !t.isActive).length,
      totalAddresses: addresses.length,
      averagePerDay,
      recentReports,
    };
  }, [reports, templates, addresses]);

  return stats;
}

/**
 * Hook for managing report templates with field configuration.
 * 
 * Manages templates and their field configurations with automatic parsing,
 * validation, and migration support. Handles dual storage for templates
 * and their associated field configurations.
 * 
 * @returns Template state and operations
 * @property {Template[]} templates - List of all templates
 * @property {Record<string, TemplateConfig>} configs - Field configs per template
 * @property {(template: Template) => void} addTemplate - Create new template
 * @property {(id: string) => void} removeTemplate - Delete template
 * @property {(template: Template) => void} updateTemplate - Update template
 * @property {(id: string, config: TemplateConfig) => void} updateTemplateConfig - Update field config
 * @property {(id: string) => void} toggleTemplateActive - Toggle template active state
 * @property {() => void} clearAllTemplates - Delete all templates
 * @property {boolean} isLoaded - Loading state
 * 
 * @example
 * ```tsx
 * const { templates, addTemplate, configs } = useTemplates();
 * 
 * addTemplate({
 *   id: 'new-template',
 *   name: 'Reporte de Emergencia',
 *   content: '{Fecha}\n{Hora}\n...'
 * });
 * ```
 */

'use client';

import { useState, useEffect, useCallback, useMemo } from 'react';
import { toast } from 'sonner';
import type { Template, TemplateConfig, FieldConfig, SectionConfig } from '@/types';
import { parseTemplate } from '@/lib/template-parser';
import { useFieldDefinitions } from './use-field-definitions';
import { useSettings } from './use-settings';
import { useDatabase } from '@/lib/db/db-provider';
import { TemplateSchema } from '@/lib/validations/schemas';
import { logger } from '@/lib/logger';
import { getUserFriendlyErrorMessage } from '@/lib/error-handler';

export function useTemplates() {
  const db = useDatabase();
  const [templates, setTemplates] = useState<Template[]>([]);
  const [configs, setConfigs] = useState<Record<string, TemplateConfig>>({});
  const [isTemplatesLoaded, setIsTemplatesLoaded] = useState(false);
  const [isConfigsLoaded, setIsConfigsLoaded] = useState(false);

  const { definitions: globalDefinitions, isLoaded: definitionsLoaded } = useFieldDefinitions();
  const { settings, isLoaded: settingsLoaded } = useSettings();

  useEffect(() => {
    if (!db) return;

    const subTemplates = db.templates.find().$.subscribe(data => {
      setTemplates(data.map(d => d.toJSON()) as Template[]);
      setIsTemplatesLoaded(true);
    });

    const subConfigs = db.template_configs.find().$.subscribe(data => {
      const configMap: Record<string, TemplateConfig> = {};
      data.forEach(d => {
        const item = d.toJSON();
        configMap[item.id] = item.config as TemplateConfig;
      });
      setConfigs(configMap);
      setIsConfigsLoaded(true);
    });

    return () => {
      subTemplates.unsubscribe();
      subConfigs.unsubscribe();
    };
  }, [db]);

  // Cach├® de parse para evitar re-parsing innecesario
  const parsedTemplates = useMemo(() => {
    const cache = new Map();
    templates.forEach(template => {
      const cacheKey = `${template.id}-${template.content.length}`;
      cache.set(cacheKey, parseTemplate(template.content));
    });
    return cache;
  }, [templates]);

  // Optimize config synchronization to avoid unnecessary writes and re-renders
  useEffect(() => {
    if (isTemplatesLoaded && definitionsLoaded && templates.length > 0 && db) {
      const newConfigs: Record<string, TemplateConfig> = {};
      let hasSignificantChanges = false;

      templates.forEach(template => {
        const cacheKey = `${template.id}-${template.content.length}`;
        const parsed = parsedTemplates.get(cacheKey);
        const existingConfig = configs[template.id] || { fields: {}, sections: [], layout: [] };

        const finalConfig: TemplateConfig = {
          sections: parsed.sections.map((parsedSection: SectionConfig) => {
            const existingSection = (existingConfig.sections || []).find((s: SectionConfig) => s.label === parsedSection.label);
            return {
              ...parsedSection,
              statisticsCategory: existingSection?.statisticsCategory
            };
          }),
          layout: parsed.layout,
          fields: {}
        };

        parsed.fieldNames.forEach((fieldName: string) => {
          const existingFieldConfig = existingConfig.fields[fieldName];
          const globalDef = globalDefinitions[fieldName];
          const typeFromTemplate = parsed.fieldTypes.get(fieldName);
          const optionsFromTemplate = parsed.templateOptions.get(fieldName);

          const baseConfig: FieldConfig = {
            type: 'text',
            label: fieldName,
            ...globalDef,
            ...existingFieldConfig,
          };

          if (typeFromTemplate) {
            baseConfig.type = typeFromTemplate;
          } else if (globalDef?.type) {
            baseConfig.type = globalDef.type;
          }

          if (optionsFromTemplate) {
            baseConfig.snippetOptions = optionsFromTemplate;
          }

          finalConfig.fields[fieldName] = baseConfig;
        });

        newConfigs[template.id] = finalConfig;

        // Check if this specific template config actually changed from what we have in state
        if (JSON.stringify(finalConfig) !== JSON.stringify(existingConfig)) {
          hasSignificantChanges = true;
        }
      });

      if (hasSignificantChanges) {
        // Use a small timeout to debounce bulkUpsert if multiple renders happen quickly
        const timeoutId = setTimeout(() => {
          const entries = Object.entries(newConfigs).map(([id, config]) => ({ id, config }));
          db.template_configs.bulkUpsert(entries).catch(err =>
            logger.error('Failed to sync template configs', err, { feature: 'Templates' })
          );
        }, 100);
        return () => clearTimeout(timeoutId);
      }
    }
  }, [isTemplatesLoaded, isConfigsLoaded, definitionsLoaded, templates, db, parsedTemplates, configs, globalDefinitions]);

  const addTemplate = async (newTemplate: Template) => {
    if (!db) return;
    try {
      // Validate with Zod first
      const validatedTemplate = TemplateSchema.parse(newTemplate);

      const { sections, layout, fieldNames, fieldTypes, templateOptions, errors } = parseTemplate(validatedTemplate.content);

      if (errors.length > 0) {
        toast.error(`La plantilla tiene errores: ${errors[0]}`);
        logger.warn('Template has parsing errors', { id: validatedTemplate.id, errors });
      } else {
        toast.success(`Plantilla "${validatedTemplate.name}" agregada correctamente.`);
        logger.info('Template added', { id: validatedTemplate.id, name: validatedTemplate.name });
      }

      await db.templates.insert({ ...validatedTemplate, isActive: errors.length === 0 });

      const newConfig: TemplateConfig = { fields: {}, sections, layout };
      fieldNames.forEach(fieldName => {
        newConfig.fields[fieldName] = {
          ...(globalDefinitions[fieldName] || { type: 'text', label: fieldName }),
        };
        const typeFromTemplate = fieldTypes.get(fieldName);
        if (typeFromTemplate) newConfig.fields[fieldName].type = typeFromTemplate;
        const optionsFromTemplate = templateOptions.get(fieldName);
        if (optionsFromTemplate) newConfig.fields[fieldName].snippetOptions = optionsFromTemplate;
      });

      await db.template_configs.upsert({ id: validatedTemplate.id, config: newConfig });

    } catch (error) {
      logger.error('Error adding template', error);
      toast.error(getUserFriendlyErrorMessage(error));
    }
  };

  const removeTemplate = async (templateId: string) => {
    if (!db) return;
    try {
      const templateDoc = await db.templates.findOne(templateId).exec();
      if (templateDoc) await templateDoc.remove();

      const configDoc = await db.template_configs.findOne(templateId).exec();
      if (configDoc) await configDoc.remove();

      logger.info('Template removed', { id: templateId });
      toast.success('Plantilla eliminada.');
    } catch (error) {
      logger.error('Failed to remove template', error);
      toast.error('Error al eliminar la plantilla.');
    }
  };

  const updateTemplateConfig = async (templateId: string, config: TemplateConfig) => {
    if (!db) return;
    try {
      await db.template_configs.upsert({ id: templateId, config });
      toast.success('Configuraci├│n de campos actualizada.');
    } catch (error) {
      logger.error('Failed to update template config', error, { feature: 'Templates', metadata: { templateId } });
    }
  };

  const updateTemplate = async (updatedTemplate: Template) => {
    if (!db) return;
    try {
      // Validate with Zod
      const validatedTemplate = TemplateSchema.parse(updatedTemplate);

      const doc = await db.templates.findOne(validatedTemplate.id).exec();
      if (doc) {
        await doc.patch(validatedTemplate);
        logger.info('Template updated', { id: validatedTemplate.id });
        toast.success('Plantilla actualizada.');
      } else {
        toast.error('Plantilla no encontrada.');
      }
    } catch (error) {
      logger.error('Failed to update template', error);
      toast.error(getUserFriendlyErrorMessage(error));
    }
  };

  const toggleTemplateActive = useCallback(async (templateId: string) => {
    if (!db) return;
    const doc = await db.templates.findOne(templateId).exec();
    if (doc) {
      await doc.patch({ isActive: !(doc.toJSON().isActive ?? true) });
    }
  }, [db]);

  const clearAllTemplates = useCallback(async () => {
    if (!db) return;
    const allTemplates = await db.templates.find().exec();
    await Promise.all(allTemplates.map(d => d.remove()));
    const allConfigs = await db.template_configs.find().exec();
    await Promise.all(allConfigs.map(d => d.remove()));
  }, [db]);

  return {
    templates,
    configs,
    addTemplate,
    removeTemplate,
    updateTemplate,
    updateTemplateConfig,
    toggleTemplateActive,
    clearAllTemplates,
    isLoaded: isTemplatesLoaded && definitionsLoaded && settingsLoaded
  };
}

/**
 * statistics-utils.test.ts
 * 
 * Unit tests for statistics utility functions
 */

import { describe, it, expect, beforeEach } from 'vitest';
import { getReportCategory, calculateMonthlyStats, type MonthlyStats } from '../statistics-utils';
import type { Report, Template, TemplateConfig } from '@/types';

// Mock data factories
function createMockReport(overrides: Partial<Report> = {}): Report {
    return {
        id: 'report-1',
        templateId: 'template-1',
        title: 'Test Report',
        content: 'Test content',
        isRelevant: true,
        formData: {},
        status: 'Finalizado',
        timestamp: new Date(2026, 0, 15, 10, 30).toISOString(), // Jan 15, 2026
        ...overrides,
    };
}

function createMockTemplate(overrides: Partial<Template> = {}): Template {
    return {
        id: 'template-1',
        name: 'Test Template',
        content: '{Field1}',
        type: 'normal',
        isActive: true,
        ...overrides,
    };
}

function createMockConfig(overrides: Partial<TemplateConfig> = {}): TemplateConfig {
    return {
        fields: {},
        sections: [],
        layout: [],
        ...overrides,
    };
}

describe('statistics-utils', () => {
    describe('getReportCategory', () => {
        it('should return null when template is undefined', () => {
            const report = createMockReport();
            const result = getReportCategory(report, undefined);
            expect(result).toBeNull();
        });

        it('should return null when template has no category or rules', () => {
            const report = createMockReport();
            const template = createMockTemplate();
            const result = getReportCategory(report, template);
            expect(result).toBeNull();
        });

        it('should return default category when no rules match', () => {
            const report = createMockReport();
            const template = createMockTemplate({
                statisticsCategory: '1.3 ROBOS',
            });
            const result = getReportCategory(report, template);
            expect(result).toBe('1.3 ROBOS');
        });

        it('should normalize category to uppercase and trim', () => {
            const report = createMockReport();
            const template = createMockTemplate({
                statisticsCategory: '  1.3 robos  ',
            });
            const result = getReportCategory(report, template);
            expect(result).toBe('1.3 ROBOS');
        });

        it('should prioritize conditional rules over default category', () => {
            const report = createMockReport({
                formData: { tipo: 'hurto' },
            });
            const template = createMockTemplate({
                statisticsCategory: '1.3 ROBOS',
                statisticsRules: [
                    { fieldId: 'tipo', condition: 'hurto', category: '1.2 HURTOS' },
                ],
            });
            const result = getReportCategory(report, template);
            expect(result).toBe('1.2 HURTOS');
        });

        it('should match conditional rule case-insensitively', () => {
            const report = createMockReport({
                formData: { tipo: 'HURTO' },
            });
            const template = createMockTemplate({
                statisticsRules: [
                    { fieldId: 'tipo', condition: 'hurto', category: '1.2 HURTOS' },
                ],
            });
            const result = getReportCategory(report, template);
            expect(result).toBe('1.2 HURTOS');
        });

        it('should trim whitespace in condition matching', () => {
            const report = createMockReport({
                formData: { tipo: '  hurto  ' },
            });
            const template = createMockTemplate({
                statisticsRules: [
                    { fieldId: 'tipo', condition: '  hurto  ', category: '1.2 HURTOS' },
                ],
            });
            const result = getReportCategory(report, template);
            expect(result).toBe('1.2 HURTOS');
        });

        it('should use first matching rule when multiple rules defined', () => {
            const report = createMockReport({
                formData: { tipo: 'robo' },
            });
            const template = createMockTemplate({
                statisticsRules: [
                    { fieldId: 'tipo', condition: 'robo', category: '1.3 ROBOS' },
                    { fieldId: 'tipo', condition: 'robo', category: '1.4 OTHER' }, // Should not be used
                ],
            });
            const result = getReportCategory(report, template);
            expect(result).toBe('1.3 ROBOS');
        });

        it('should return default category when no rules match', () => {
            const report = createMockReport({
                formData: { tipo: 'accidente' },
            });
            const template = createMockTemplate({
                statisticsCategory: '2.1 ACCIDENTES',
                statisticsRules: [
                    { fieldId: 'tipo', condition: 'robo', category: '1.3 ROBOS' },
                ],
            });
            const result = getReportCategory(report, template);
            expect(result).toBe('2.1 ACCIDENTES');
        });

        it('should handle missing formData field gracefully', () => {
            const report = createMockReport({
                formData: {},
            });
            const template = createMockTemplate({
                statisticsCategory: '1.0 DEFAULT',
                statisticsRules: [
                    { fieldId: 'nonexistent', condition: 'value', category: '1.1 OTHER' },
                ],
            });
            const result = getReportCategory(report, template);
            expect(result).toBe('1.0 DEFAULT');
        });

        it('should handle null/undefined values in formData', () => {
            const report = createMockReport({
                formData: { tipo: null },
            });
            const template = createMockTemplate({
                statisticsCategory: '1.0 DEFAULT',
                statisticsRules: [
                    { fieldId: 'tipo', condition: 'robo', category: '1.3 ROBOS' },
                ],
            });
            const result = getReportCategory(report, template);
            expect(result).toBe('1.0 DEFAULT');
        });
    });

    describe('calculateMonthlyStats', () => {
        const testMonth = 0; // January
        const testYear = 2026;

        it('should return empty stats for no reports', () => {
            const result = calculateMonthlyStats([], [], {}, testMonth, testYear);
            expect(result).toBeInstanceOf(Map);
            // Should have default categories initialized
            expect(result.size).toBeGreaterThan(0);
        });

        it('should filter reports by month and year', () => {
