import { TemplateParserResult, SectionConfig, FormDataRecord, FieldConfig, SnippetOption } from '../types';
import type { ResolutionResult } from './template/renderer';

/** No-op audit recorder (audit-engine was removed during cleanup) */
const recordReportAudit = (_reportId: string, _audit: ResolutionResult[]): void => { };
import { evaluateCondition, applyModifiers } from './template/evaluator';
import { tokenize } from './template/lexer';
import { parse } from './template/parser';
import {
  renderContentWithSections as renderContentWithSectionsFromModule,
  renderContent as renderContentFromModule,
  renderFinalReport as renderFinalFromModule
} from './template/renderer';
import { validateSyntax, validateSemantics } from './template/validator';

/**
 * Parsea una plantilla completa y devuelve su configuraci├│n y errores
 */
export function parseTemplate(templateContent: string): TemplateParserResult {
  const tokens = tokenize(templateContent);
  const result = parse(tokens);

  // Syntax and semantic validation
  const syntaxErrors = validateSyntax(templateContent);
  const semanticErrors = validateSemantics(result.sections, result.fieldNames, result.fieldTypes, result.templateOptions);

  return {
    ...result,
    errors: [...syntaxErrors, ...semanticErrors],
  };
}

// Re-export from new evaluator module for backwards compatibility
export { evaluateCondition, applyModifiers as applyTextModifier } from './template/evaluator';

/**
 * Renderiza el contenido de una plantilla con los datos proporcionados
 */
export function renderContent(
  content: string,
  data: unknown,
  config: TemplateParserResult
): string {
  return renderContentFromModule(content, data, config);
}

/**
 * Renderiza el reporte final completo
 */
export function renderFinalReport(
  template: string,
  data: FormDataRecord,
  config: { fields: Record<string, FieldConfig>; sections: SectionConfig[]; layout: string[] },
  predefinedValues: Record<string, string>,
  summaryOnly: boolean = false,
  dynamicPredefinedValues: Record<string, string> = {}
): string {
  // Use the modular renderer which handles everything including audit and semantic resolution
  // Note: We pass the parseTemplate as a dependency to the modular renderer
  return renderFinalFromModule(
    template,
    data,
    config,
    predefinedValues,
    summaryOnly,
    dynamicPredefinedValues,
    parseTemplate,
    recordReportAudit
  );
}

/**
 * Funci├│n auxiliar para renderizar contenido con manejo completo de secciones
 * (Mantenida para compatibilidad si se usa externamente, aunque el renderizador modular es preferible)
 */
export function renderContentWithSections(
  content: string,
  data: FormDataRecord,
  config: { fields: Record<string, FieldConfig>; sections: SectionConfig[]; layout: string[] },
  predefinedValues: Record<string, string>,
  dynamicPredefinedValues: Record<string, string> = {}
): string {
  return renderContentWithSectionsFromModule(
    content,
    data,
    {
      ...config,
      templateOptions: new Map<string, SnippetOption[]>(),
      fieldModifiers: new Map<string, string[]>(),
    },
    predefinedValues,
    dynamicPredefinedValues
  );
}

/**
 * Template Evaluator - Condition & Modifier Evaluation
 * 
 * Evaluates conditional expressions and applies text modifiers
 */

/**
 * Evaluates a conditional expression
 * 
 * @param fieldValue - The actual value of the field
 * @param operator - The comparison operator (=, !=, >, <, >=, <=)
 * @param targetValue - The value to compare against
 * @returns True if the condition is met
 * 
 * @example
 * ```typescript
 * evaluateCondition('Robo', '=', 'Robo') // true
 * evaluateCondition(5, '>', '3') // true
 * evaluateCondition('Active', '!=', 'Inactive') // true
 * ```
 */
/**
 * Evaluates a conditional expression
 * 
 * Supports numeric and string comparisons using standard operators.
 * 
 * @param fieldValue - The actual value of the field
 * @param operator - The comparison operator (=, !=, >, <, >=, <=)
 * @param targetValue - The value to compare against
 * @returns True if the condition is met
 * 
 * @example
 * ```typescript
 * evaluateCondition('Robo', '=', 'Robo') // true
 * evaluateCondition(5, '>', '3') // true
 * evaluateCondition('Active', '!=', 'Inactive') // true
 * ```
 */
export function evaluateCondition(
    fieldValue: unknown,
    operator: string,
    targetValue: string
): boolean {
    if (fieldValue === undefined || fieldValue === null) {
        return operator === '!=';
    }

    const val = coerceForComparison(fieldValue);
    const target = coerceForComparison(targetValue);

    switch (operator) {
        case '=':
        case '==':
            return val === target;
        case '!=':
            return val !== target;
        case '>':
            return val > target;
        case '<':
            return val < target;
        case '>=':
            return val >= target;
        case '<=':
            return val <= target;
        default:
            return false;
    }
}

/**
 * Applies text modifiers to a value
 * 
 * @param value - The value to modify
 * @param modifiers - Array of modifier names (upper, lower, title, etc.)
 * @returns Modified string value
 * 
 * @example
 * ```typescript
 * applyModifiers('hello world', ['upper']) // 'HELLO WORLD'
 * applyModifiers('HELLO WORLD', ['lower']) // 'hello world'
 * applyModifiers('hello world', ['title']) // 'Hello World'
 * ```
 */
export function applyModifiers(value: unknown, modifiers: string | string[]): string {
    if (value === undefined || value === null) return '';

    let result = String(value);
    const mods = Array.isArray(modifiers) ? modifiers : [modifiers];

    mods.forEach((mod) => {
        const trimmedMod = mod.trim().toLowerCase();
        if (trimmedMod === 'upper') {
            result = result.toUpperCase();
        } else if (trimmedMod === 'lower') {
            result = result.toLowerCase();
        } else if (trimmedMod === 'title') {
            result = result
                .toLowerCase()
                .split(' ')
                .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
                .join(' ');
        } else if (trimmedMod.startsWith('default(')) {
            if (!result || result.trim() === '') {
                const match = mod.match(/default\("?(.*?)"?\)/i);
                if (match && match[1]) {
                    result = match[1];
                }
            }
        }
    });

    return result;
}

/**
 * Formats a value based on its field type (Reserved for future specialized formatting)
 */
export function formatValue(value: unknown, fieldType: string): string {
    return String(value);
}

/**
 * Coerces values for comparison (handles numeric strings)
 */
function coerceForComparison(value: unknown): string | number {
    const s = String(value).trim();
    // If it looks like a number, treat it as a number for comparison
    if (s !== '' && !isNaN(Number(s))) {
        return Number(s);
    }
    return s;
}

/**
 * Template Lexer - Tokenization
 * 
 * Converts template string into a stream of tokens for parsing
 * 
 * Supported syntax:
 * - Fields: {FieldName}, {FieldName:type}, {FieldName|modifier}
 * - Repeatable fields: {FieldName}*
 * - Sections: [Label]content[/]
 * - Self-contained Sections: ["Title" {Field}]
 * - Visual Separators: [""]
 * - Repeatable sections: [Label]*content[/]
 * - Conditionals: [?{Field} op value]content[/]
 *   where op can be: =, !=, >, <, >=, <=
 * - Mapping Conditionals: [?{Field}] Key=Value [/]
 *   Implicitly defines dropdown options and report translation.
 */

import type { Token, ConditionalExpression } from './types';

/**
 * Tokenizes a template string into a structured token stream
 * 
 * @param template - The template string to tokenize
 * @returns Array of tokens representing the template structure
 * 
 * @example
 * ```typescript
 * const tokens = tokenize('Hello {Name}, today is {Fecha:date}');
 * // Returns: [
 * //   { type: 'text', content: 'Hello ', position: 0 },
 * //   { type: 'field', id: 'Name', raw: '{Name}', position: 6 },
 * //   { type: 'text', content: ', today is ', position: 12 },
 * //   { type: 'field', id: 'Fecha', raw: '{Fecha:date}', position: 24 }
 * // ]
 * ```
 */
export function tokenize(template: string): Token[] {
    const tokens: Token[] = [];
    let position = 0;
    let currentText = '';

    const flushText = () => {
        if (currentText) {
            tokens.push({
                type: 'text',
                content: currentText,
                raw: currentText,
                position: position - currentText.length,
            });
            currentText = '';
        }
    };

    while (position < template.length) {
        const char = template[position];
        const next = template[position + 1];

        // Check for field start: { (but not {{ for escaping)
        if (char === '{' && next !== '{') {
            flushText();
            const fieldToken = extractFieldToken(template, position);
            if (fieldToken) {
                tokens.push(fieldToken);
                position = fieldToken.endPos;
                continue;
            }
        }

        // Check for section/conditional start: [
        if (char === '[' && next !== '[') {
            flushText();
            const sectionToken = extractSectionToken(template, position);
            if (sectionToken) {
                tokens.push(sectionToken);
                position = sectionToken.endPos;
                continue;
            }
        }

        // Regular text
        currentText += char;
        position++;
    }

    flushText();
    return tokens;
}

/**
 * Extracts a field token from the template
 * Returns the token and the position after the closing brace
 */
function extractFieldToken(
    template: string,
    startPos: number
): (Token & { endPos: number }) | null {
    let pos = startPos + 1; // Skip opening {
    let depth = 1;
    let content = '';

    // Find matching closing brace
    while (pos < template.length && depth > 0) {
        const char = template[pos];
        if (char === '{') depth++;
        if (char === '}') depth--;

        if (depth > 0) {
            content += char;
        }
        pos++;
    }

    if (depth !== 0) {
        // Unbalanced braces - treat as text
        return null;
    }

    // Check for repeatable marker: *
    let finalPos = pos;
    if (template[pos] === '*') {
        finalPos++;
    }
    const raw = template.substring(startPos, finalPos);

    // Extract just the field ID (before : or |)
    const id = content.split(/[:|]/)[0]?.trim() || '';
    if (!id) return null;

    return {
        type: 'field',
        id,
        raw,
        position: startPos,
        endPos: finalPos,
    };
}

/**
 * Extracts a section or conditional token from the template
 * Returns the token and the position after the closing bracket
 */
function extractSectionToken(
    template: string,
    startPos: number
): (Token & { endPos: number }) | null {
    let pos = startPos + 1; // Skip opening [
    let content = '';

    // Find closing ]
    while (pos < template.length && template[pos] !== ']') {
        content += template[pos];
        pos++;
    }

    if (pos >= template.length) {
        // No closing bracket found
        return null;
    }

    pos++; // Skip closing ]
    const raw = template.substring(startPos, pos);

    // Check if this is a section end marker: [/]
    if (content.trim() === '/') {
        return {
            type: 'section_end',
            raw,
            position: startPos,
            endPos: pos,
        };
    }

    // Check if this is a conditional: [?{Field} op value] or [?{Field}]
    const conditionalMatch = content.match(
        /^\?\s*\{\s*([^\}]+)\s*\}\s*(?:(!=|>=|<=|>|<|=)\s*(.+))?$/
    );

    if (conditionalMatch) {
        const [, fieldId, operator, value] = conditionalMatch;
        const cleanValue = value?.trim().replace(/^"|"$/g, '') || '';

        return {
            type: 'section_start',
            label: undefined,
            condition: {
                fieldId: fieldId?.trim() || '',
                operator: (operator as ConditionalExpression['operator']) || '=',
                value: cleanValue,
            },
            raw,
            position: startPos,
            endPos: pos,
        };
    }

    // Regular section: [Label] or [Label]*
    const label = content.replace(/\*$/, '').trim();
    const isRepeatable = content.endsWith('*');

    return {
        type: 'section_start',
        label: label || undefined,
        condition: undefined,
        raw,
        position: startPos,
        endPos: pos,
    };
}


/**
 * Checks if a character is a special template character
 */
function isSpecialChar(char: string): boolean {
    return char === '{' || char === '}' || char === '[' || char === ']';
}

/**
 * Escapes special characters in regex
 */
function escapeRegex(str: string): string {
    return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

import type { Token, ParseResult, FieldConfig } from './types';
import type { SnippetOption, FieldType, SectionConfig, TemplateParserResult } from '@/types';
import { tokenize } from './lexer';

/**
 * Automatic field types based on field name
 */
const AUTOMATIC_FIELD_TYPES: Record<string, FieldType> = {
    hora: 'time-hlv',
    fecha: 'date',
};

/**
 * Parses field tag content to extract configuration
 * 
 * Syntax: {FieldName:type:modifiers|textMod}
 * Examples:
 * - {Name} ÔåÆ text field
 * - {Fecha:date} ÔåÆ date field
 * - {Nombre:text:full:req|title} ÔåÆ required full-width text with title case
 * - {Tipo:dropdown(A=Val1|B=Val2)} ÔåÆ dropdown with inline options
 */
export function parseFieldTag(
    tagContent: string,
    templateOptions: Map<string, SnippetOption[]>
): {
    fieldId: string;
    fieldType: FieldType;
    modifiers: string[];
    isFullWidth: boolean;
    isRequired: boolean;
} {
    const segments = tagContent.split(':').map((s) => s.trim());
    const fieldId = segments[0] || '';
    const otherSegments = segments.slice(1);

    let fieldType: FieldType = AUTOMATIC_FIELD_TYPES[fieldId.toLowerCase()] || 'text';
    let isFullWidth = false;
    let isRequired = false;
    const modifiers: string[] = [];

    const VALID_FIELD_TYPES = new Set<FieldType>([
        'text',
        'textarea',
        'date',
        'predefined',
        'time-hlv',
        'multi-text',
        'dropdown',
        'semantic',
    ]);
    const VALID_TEXT_MODS = new Set(['upper', 'lower', 'title']);

    otherSegments.forEach((segment) => {
        const dropdownMatch = segment.match(/^dropdown\((.+)\)$/);
        const optionsString = dropdownMatch?.[1];
        if (dropdownMatch && optionsString) {
            fieldType = 'dropdown';
            const options: SnippetOption[] = optionsString
                .split('|')
                .map((opt, i) => {
                    const eqIdx = opt.indexOf('=');
                    if (eqIdx > -1) {
                        const label = opt.substring(0, eqIdx).trim();
                        const value = opt.substring(eqIdx + 1).trim();
                        if (label) {
                            return { id: `tpl_opt_${fieldId}_${i}`, label, value };
                        }
                    }
                    return null;
                })
                .filter((o): o is SnippetOption => o !== null);

            if (options.length > 0) {
                templateOptions.set(fieldId, options);
            }
            return;
        }

        if (segment === 'full') {
            isFullWidth = true;
        } else if (segment === 'req') {
            isRequired = true;
        } else if (VALID_FIELD_TYPES.has(segment as FieldType)) {
            fieldType = segment as FieldType;
        } else if (VALID_TEXT_MODS.has(segment)) {
            modifiers.push(segment);
        } else {
            const pipeParts = segment.split('|');
            pipeParts.forEach((part) => {
                const trimmed = part.trim();
                if (trimmed === 'full') isFullWidth = true;
                else if (trimmed === 'req') isRequired = true;
                else if (VALID_TEXT_MODS.has(trimmed)) modifiers.push(trimmed);
                else if (trimmed) modifiers.push(trimmed);
            });
        }
    });

    return { fieldId, fieldType, modifiers, isFullWidth, isRequired };
}

/**
 * Parses a token stream into a structured TemplateParserResult
 */
export function parse(tokens: Token[]): TemplateParserResult {
    const sections: SectionConfig[] = [];
    const layout: string[] = [];
    const fieldNames = new Set<string>();
    const fieldTypes = new Map<string, FieldType>();
    const templateOptions = new Map<string, SnippetOption[]>();
    const fieldModifiers = new Map<string, string[]>();
    const fieldWidths = new Map<string, boolean>();
    const requiredFields = new Map<string, boolean>();
    const globalRenderedFields = new Set<string>();

    // Refactored internal parser for recursion
    function parseInternal(tokenList: Token[]): {
        subLayout: string[];
        subSections: SectionConfig[];
        subFieldNames: Set<string>;
    } {
        const subLayout: string[] = [];
        const subSections: SectionConfig[] = [];
        const subFieldNames = new Set<string>();

        let idx = 0;
        while (idx < tokenList.length) {
            const token = tokenList[idx];
            if (!token) {
                idx++;
                continue;
            }

            if (token.type === 'field') {
                const config = parseFieldTag(token.raw.slice(1, -1), templateOptions);
                const fieldId = config.fieldId;
                if (!fieldId) {
                    idx++;
                    continue;
                }
                subFieldNames.add(fieldId);
                fieldNames.add(fieldId);

                const currentType = fieldTypes.get(fieldId);
                if (!currentType || (currentType === 'text' && config.fieldType !== 'text')) {
                    fieldTypes.set(fieldId, config.fieldType);
                }
                if (config.modifiers.length > 0) fieldModifiers.set(fieldId, config.modifiers);
                if (config.isFullWidth) fieldWidths.set(fieldId, true);
                if (config.isRequired) requiredFields.set(fieldId, true);

                if (token.raw.endsWith('}*')) {
                    const sectionId = generateSectionId(fieldId, [...sections, ...subSections]);
                    const sec: SectionConfig = {
                        id: sectionId,
                        label: fieldId,
                        isRepeatable: true,
                        fieldIds: [fieldId],
                        layout: [fieldId],
                        repeatableItemLabel: fieldId.toUpperCase(),
                        originalContent: `{${fieldId}}`,
                    };

                    if (!globalRenderedFields.has(sectionId)) {
                        subSections.push(sec);
                        subLayout.push(sectionId);
                        globalRenderedFields.add(sectionId);
                    }
                } else {
                    if (!globalRenderedFields.has(fieldId)) {
                        subLayout.push(fieldId);
                        globalRenderedFields.add(fieldId);
                    }
                }
                idx++;
            } else if (token.type === 'section_start') {
                let inner: Token[] = [];
                let isRepeatable = token.raw?.endsWith('*') || false;
                let isSelfContained = false;
                let baseLabel = token.label || '';

                // Detection of inline/self-contained sections: ["Title" {Field}] OR separator [""]
                const firstBraceIdx = baseLabel.indexOf('{');
                const isSeparator = baseLabel === '""';

                if ((firstBraceIdx !== -1 && !token.condition) || isSeparator) {
                    isSelfContained = true;
                    if (isSeparator) {
                        baseLabel = 'separator';
                        inner = [];
                    } else {
                        const inlineContent = baseLabel.substring(firstBraceIdx);
                        baseLabel = baseLabel.substring(0, firstBraceIdx).trim();
                        inner = tokenize(inlineContent);
                    }
                }
                idx++;
                if (!isSelfContained) {
                    let depth = 1;
                    while (idx < tokenList.length && depth > 0) {
                        const currentToken = tokenList[idx];
                        if (!currentToken) {
                            idx++;
                            continue;
                        }

                        if (currentToken.type === 'section_start') depth++;
                        if (currentToken.type === 'section_end') depth--;

                        if (depth > 0) {
                            inner.push(currentToken);
                        }
                        idx++;
                    }
                }

                // Parse attributes from label: [singular="X" plural="Y" sub="Z"]
                let singularTitle = '';
                let pluralTitle = '';
                let subLabel = '';
                if (baseLabel) {
                    const singularMatch = baseLabel.match(/singular\s*=\s*"([^"]*)"/i);
                    const pluralMatch = baseLabel.match(/plural\s*=\s*"([^"]*)"/i);
                    const subMatch = baseLabel.match(/sub\s*=\s*"([^"]*)"/i);

                    if (singularMatch) singularTitle = singularMatch[1] || '';
                    if (pluralMatch) pluralTitle = pluralMatch[1] || '';
                    if (subMatch) subLabel = subMatch[1] || '';

                    // If it has attributes, the label itself shouldn't be used as title directly 
                    // unless no attributes were found.
                    if (singularMatch || pluralMatch || subMatch) {
                        baseLabel = singularTitle || '';
                    }
                }

                const innerResult = parseInternal(inner);

                // Implicit dropdown options extraction from mapping conditionals
                const isMappingConditional = token.condition && token.condition.value === '' && inner.length > 0;

                if (isMappingConditional) {
                    const fieldId = token.condition!.fieldId;
                    const options: SnippetOption[] = [];
                    inner.forEach((t, i) => {
                        if (t.type === 'text') {
                            const lines = t.raw.split('\n');
                            lines.forEach((line) => {
                                const eqIdx = line.indexOf('=');
                                if (eqIdx > -1) {
                                    const key = line.substring(0, eqIdx).trim();
                                    const val = line.substring(eqIdx + 1).trim();
                                    if (key) {
                                        options.push({
                                            id: `tpl_opt_${fieldId}_implicit_${i}_${options.length}`,
                                            label: key, // The Key: what the user selects in the dropdown
                                            value: val, // The Value: what goes into the report (long text)
                                        });
                                    }
                                }
                            });
                        }
                    });
                    if (options.length > 0) {
                        const existing = templateOptions.get(fieldId) || [];
                        const merged = [...existing];
                        options.forEach(opt => {
                            if (!merged.some(m => m.label === opt.label)) {
                                merged.push(opt);
                            }
                        });
                        templateOptions.set(fieldId, merged);
                        fieldTypes.set(fieldId, 'dropdown');
                    }
                }

                const baseId = baseLabel || (token.condition ? `cond_${token.condition.fieldId}` : 'section');
                const sectionId = generateSectionId(baseId, [...sections, ...subSections, ...innerResult.subSections]);

                subSections.push(...innerResult.subSections);

                const section: SectionConfig = {
                    id: sectionId,
                    label: (isSeparator || token.condition) ? '' : (baseLabel || `Secci├│n ${subSections.length + 1}`),
                    isRepeatable,
                    fieldIds: Array.from(innerResult.subFieldNames),
                    layout: innerResult.subLayout,
                    condition: token.condition,
                    originalContent: inner.map(t => t.raw).join(''),
                    isSeparator: isSeparator,
                    isMapping: isMappingConditional || false,
                };

                if (singularTitle) section.singularTitle = singularTitle;
                if (pluralTitle) section.pluralTitle = pluralTitle;
                if (subLabel) section.repeatableItemLabel = subLabel;

                subSections.push(section);
                subLayout.push(sectionId);
                innerResult.subFieldNames.forEach(fn => subFieldNames.add(fn));
            } else {
                idx++;
            }
        }
        return { subLayout: subLayout, subSections: subSections, subFieldNames: subFieldNames };
    }

    const finalResult = parseInternal(tokens);
    sections.push(...finalResult.subSections);
    layout.push(...finalResult.subLayout);
    finalResult.subFieldNames.forEach(fn => fieldNames.add(fn));

    return {
        sections,
        layout,
        fieldNames,
        fieldTypes,
        templateOptions,
        fieldModifiers,
        fieldWidths,
        requiredFields,
        errors: [],
    };
}

/**
 * Generates a unique, stable section ID
 */
function generateSectionId(base: string, existingSections: SectionConfig[]): string {
    const prefix = base.startsWith('cond_') || base.startsWith('sec_') ? '' : 'sec_';
    let id = `${prefix}${base.toLowerCase().replace(/[^a-z0-9]/g, '_')}`;

    let counter = 1;
    const originalId = id;
    while (existingSections.some(s => s.id === id)) {
        id = `${originalId}_${counter++}`;
    }
    return id;
}

/**
 * Template Renderer - Content Rendering
 *
 * Handles rendering of templates with data substitution
 */

import { format } from 'date-fns';
import { es } from 'date-fns/locale';
import type { TemplateParserResult, SectionConfig, FieldConfig, FieldType, SnippetOption, FormDataRecord, FormDataValue } from '@/types';
import { formatStaffMember } from '../formatters';
/** Inline type for semantic resolution results (previously in integration-engine.ts) */
export interface ResolutionResult {
    concept: string;
    value: string;
    source: string;
}

/** Inline stub: resolves a semantic concept to its string value */
function resolveSemanticConcept(concept: string): ResolutionResult {
    return { concept, value: concept, source: 'inline' };
}
import { evaluateCondition, applyModifiers as applyTextModifier } from './evaluator';
import { parseFieldTag } from './parser';
import { logger } from '../logger';

/** Internal config shape used during rendering (combines parsed template + field definitions) */
interface TemplateRenderConfig {
    fields: Record<string, FieldConfig>;
    sections: SectionConfig[];
    layout: string[];
    templateOptions: Map<string, SnippetOption[]>;
    fieldModifiers: Map<string, string[]>;
}

/**
 * Renders template content with data substitution
 * 
 * Logic flow:
 * 1. Pass 1: Scan for mapping conditionals [?{Field}] Key=Value [/]
 *    - These are definition-only blocks (don't produce output).
 *    - Used to build a translation map for {Field} tags.
 * 2. Pass 2: Global substitution
 *    - {Field} tags: Use the translation map from Pass 1 if a match is found.
 *    - Standard Conditionals: Evaluation strictly for visibility logic.
 *    - Mapping Blocks: Removed (return empty string) to avoid duplication.
 * 
 * @param content - Template content string
 * @param data - Data object for substitution
 * @param config - Parsed template configuration
 * @returns Rendered string
 */
export function renderContent(
    content: string,
    data: unknown,
    config: TemplateParserResult
): string {
    if (!content) return '';
    const localData = (data || {}) as FormDataRecord;

    // First, pass: collect all mapping results for fields
    const mappingResults: Record<string, string> = {};
    const mappingRegex = /\[\?\s*\{[\s\S]+?\}\s*(?:(?:!=|>=|<=|>|<|=)\s*(?:"[^"]*"|\S+?))?\s*\]([\s\S]*?)\[\/\s*\]/g;

    let mappingMatch;
    while ((mappingMatch = mappingRegex.exec(content)) !== null) {
        const block = mappingMatch[0];
        const innerContent = mappingMatch[1];
        const condMatch = block.match(/^\[\?\s*\{\s*([\s\S]+?)\s*\}\s*(?:(!=|>=|<=|>|<|=)\s*("(.*?)"|(\S+?)))?\s*\]/);

        if (condMatch && condMatch[1]) {
            const condFieldId = condMatch[1].trim();
            const operator = condMatch[2];
            const actualValue = localData[condFieldId];
            const options = config.templateOptions.get(condFieldId);

            if (!operator) {
                let keyToCompare = actualValue;
                if (options) {
                    const opt = options.find((o: SnippetOption) => o.value === actualValue || o.label === actualValue);
                    if (opt) keyToCompare = opt.label;
                }

                const lines = (innerContent || '').split('\n');
                for (const line of lines) {
                    const eqIdx = line.indexOf('=');
                    if (eqIdx > -1) {
                        const key = line.substring(0, eqIdx).trim();
                        const val = line.substring(eqIdx + 1).trim();
                        if (evaluateCondition(keyToCompare, '=', key)) {
                            mappingResults[condFieldId] = val;
                            break;
                        }
                    }
                }
            }
        }
    }

    const blockRegex =
        /(\{[\s\S]+?\}|\[\?\s*\{[\s\S]+?\}\s*(?:(?:!=|>=|<=|>|<|=)\s*(?:"[^"]*"|\S+?))?\s*\][\s\S]*?\[\/\s*\])/g;

    return content.replace(blockRegex, (block) => {
        if (block.startsWith('{')) {
            const tag = block.slice(1, -1);
            const { fieldId, modifiers } = parseFieldTag(tag, new Map());

            // If we have a mapping result for this field, use it
            let val = mappingResults[fieldId] !== undefined ? mappingResults[fieldId] : localData[fieldId];

            // If not already mapped, handle standard dropdown value conversion
            if (mappingResults[fieldId] === undefined) {
                const options = config.templateOptions.get(fieldId);
                if (options && typeof val === 'string' && /^\d+$/.test(val)) {
                    const idx = parseInt(val, 10);
                    if (options[idx]) val = options[idx].value;
                }
            }

            // Unir modificadores de la etiqueta con los modificadores detectados globalmente
            const globalModifiers = config.fieldModifiers.get(fieldId) || [];
            const allModifiers = [...globalModifiers, ...modifiers];

            return applyTextModifier(val, allModifiers);
        } else if (block.startsWith('[?')) {
            const condMatch = block.match(
                /^\[\?\s*\{\s*([\s\S]+?)\s*\}\s*(?:(!=|>=|<=|>|<|=)\s*("(.*?)"|(\S+?)))?\s*\]([\s\S]*?)\[\/\s*\]$/
            );
            if (condMatch && condMatch[1] && condMatch[6]) {
                const operator = condMatch[2];
                if (operator) {
                    // Standard condition
                    const condFieldId = condMatch[1].trim();
                    const targetValue = condMatch[4] || condMatch[5] || '';
                    const innerContent = condMatch[6];
                    const actualValue = localData[condFieldId];

                    let valToCompare = actualValue;
                    const options = config.templateOptions.get(condFieldId);
                    if (options && /^\d+$/.test(String(actualValue))) {
                        const idx = parseInt(String(actualValue), 10);
                        const opt = options[idx];
                        if (opt) valToCompare = opt.value;
                    }

                    if (evaluateCondition(valToCompare, operator, targetValue)) {
                        return renderContent(innerContent, data, config);
                    }
                } else {
                    // Mapping conditional is now handled by the {Field} tag
                    // We return empty string here so the definition doesn't print itself.
                    return '';
                }
            }
            return '';
        }
        return block;
    });
}

/**
 * Helper: Escapes special regex characters
 */
function escapeRegExp(string: string): string {
    return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/**
 * Helper: Finds value for a field with fallback logic
 */
function findValueForField(
    fieldId: string,
    data: FormDataRecord,
    sections: SectionConfig[],
    predefinedValues: Record<string, string>,
    dynamicPredefinedValues: Record<string, string>,
    itemData?: FormDataRecord
): FormDataValue {
    const source = itemData || data;
    const lowerCaseFieldId = fieldId.toLowerCase();

    // 1. Check dynamic predefined values
    if (dynamicPredefinedValues[fieldId] !== undefined) return dynamicPredefinedValues[fieldId];
    const foundKeyInDynamic = Object.keys(dynamicPredefinedValues).find(
        (k) => k.toLowerCase() === lowerCaseFieldId
    );
    if (foundKeyInDynamic) return dynamicPredefinedValues[foundKeyInDynamic];

    // 2. Check item data (for repeatable sections)
    if (itemData && itemData[fieldId] !== undefined) return itemData[fieldId];
    if (itemData) {
        const foundKeyInItem = Object.keys(itemData).find(
            (k) => k.toLowerCase() === lowerCaseFieldId
        );
        if (foundKeyInItem) return itemData[foundKeyInItem];
    }

    // 3. Check root data
    if (data[fieldId] !== undefined) return data[fieldId];
    const foundKeyInRoot = Object.keys(data).find((k) => k.toLowerCase() === lowerCaseFieldId);
    if (foundKeyInRoot) return data[foundKeyInRoot];

    // 4. Check non-repeatable section data
    for (const section of sections.filter((s) => !s.isRepeatable && s.id in data)) {
        const sectionData = data[section.id];
        if (sectionData && typeof sectionData === 'object' && !Array.isArray(sectionData)) {
            if (sectionData[fieldId] !== undefined) return sectionData[fieldId];
            const foundKeyInSection = Object.keys(sectionData).find(
                (k) => k.toLowerCase() === lowerCaseFieldId
            );
            if (foundKeyInSection) return sectionData[foundKeyInSection];
        }
    }

    // 5. Check predefined values
    if (predefinedValues[fieldId] !== undefined) return predefinedValues[fieldId];
    const foundKeyInPredefined = Object.keys(predefinedValues).find(
        (k) => k.toLowerCase() === lowerCaseFieldId
    );
    if (foundKeyInPredefined) return predefinedValues[foundKeyInPredefined];

    return undefined;
}

/**
 * Helper: Renders a value based on its type and field config
 */
function renderValue(
    value: FormDataValue,
    fieldId: string,
    fields: Record<string, FieldConfig>,
    config: TemplateRenderConfig
): string {
    if (value === undefined || value === null) return '';

    const fieldConfig = fields[fieldId];

    // Dropdown rendering
    if (fieldConfig?.type === 'dropdown' && typeof value === 'string') {
        if (fieldConfig.targetField) return '';
        const allOptions = [
            ...(fieldConfig.snippetOptions || []),
            ...(config.templateOptions?.get(fieldId) || []),
        ];
        const selectedOption = allOptions.find((opt: SnippetOption) => opt && opt.label === value);
        if (selectedOption && typeof selectedOption === 'object' && 'value' in selectedOption) {
            return String(selectedOption.value);
        }
        return '';
    }

    // Date rendering
    if (
        fieldConfig?.type === 'date' &&
        typeof value === 'string' &&
        value.match(/^\d{4}-\d{2}-\d{2}$/)
    ) {
        try {
            const date = new Date(value + 'T00:00:00');
            if (isNaN(date.getTime())) return value;

            const formattedDate = format(date, 'dd/MMMM/yyyy', { locale: es });
            const parts = formattedDate.split('/');
            const monthName = parts[1];
            if (parts.length === 3 && monthName) {
                parts[1] = monthName.charAt(0).toUpperCase() + monthName.slice(1);
                return parts.join('/');
            }
            return formattedDate;
        } catch (e) {
            return value;
        }
    }

    // Array rendering
    if (Array.isArray(value)) {
        if (value.length > 0) {
            if (typeof value[0] === 'object' && value[0] !== null && 'name' in value[0]) {
                const showCedula =
                    fieldId.toLowerCase() === 'reporta' || fieldId.toLowerCase() === 'analista';
                return value.map((member) => formatStaffMember(member as import('@/types').StaffMember, showCedula)).join(', ');
            }
        }
        return value.join(', ');
    }

    // Semantic field rendering
    if (fieldConfig?.type === 'semantic') {
        const result = resolveSemanticConcept(fieldId);
        return String(result.value);
    }

    // Apply text modifiers
    const modifiers = config.fieldModifiers?.get(fieldId) || [];
    return applyTextModifier(String(value), modifiers);
}

/**
 * Helper: Checks if a value has content
 */
function hasContent(value: FormDataValue): boolean {
    if (value === undefined || value === null) return false;
    if (typeof value === 'string' && value.trim() === '') return false;
    if (Array.isArray(value) && value.length === 0) return false;
    return true;
}

/**
 * Helper: Checks if a section has any values
 */
function sectionHasValues(
    section: SectionConfig,
    data: FormDataRecord,
    sections: SectionConfig[],
    predefinedValues: Record<string, string>,
    dynamicPredefinedValues: Record<string, string>,
    dataContext?: FormDataRecord
): boolean {
    const checkFieldsForContent = (fieldIds: string[], context: FormDataRecord): boolean => {
        return fieldIds.some((fieldId) => {
            const value = findValueForField(
                fieldId,
                data,
                sections,
                predefinedValues,
                dynamicPredefinedValues,
                context
            );
            return hasContent(value);
        });
    };

    const checkSectionRecursive = (s: SectionConfig, context: FormDataRecord): boolean => {
        if (s.isRepeatable) {
            const sectionData = context[s.id] as FormDataValue[];
            if (!Array.isArray(sectionData) || sectionData.length === 0) return false;
            return sectionData.some(
                (item) =>
                    checkFieldsForContent(s.fieldIds, item as FormDataRecord) ||
                    (s.layout || []).some(
                        (id) =>
                            (id.startsWith('section_') || id.startsWith('sec_') || id.startsWith('cond_')) &&
                            checkSectionRecursive(sections.find((sec) => sec.id === id)!, item as FormDataRecord)
                    )
            );
        } else {
            const nestedContext = (context[s.id] || context) as FormDataRecord;
            return (
                checkFieldsForContent(s.fieldIds, nestedContext) ||
                (s.layout || []).some(
                    (id) =>
                        (id.startsWith('section_') || id.startsWith('sec_') || id.startsWith('cond_')) &&
                        checkSectionRecursive(sections.find((sec) => sec.id === id)!, nestedContext)
                )
            );
        }
    };

    const context = dataContext || (data[section.id] ? data[section.id] as FormDataRecord : data);
    return checkSectionRecursive(section, context);
}

/**
 * Renders a section recursively with its nested content
 */
function renderSection(
    sectionId: string,
    data: FormDataRecord,
    sections: SectionConfig[],
    fields: Record<string, FieldConfig>,
    config: TemplateRenderConfig,
    predefinedValues: Record<string, string>,
    dynamicPredefinedValues: Record<string, string>,
    currentData: FormDataRecord
): string {
    const section = sections.find((s) => s.id === sectionId);
    if (!section) return '';

    // Evaluate condition if present
    if (section.condition) {
        const valToCompare = findValueForField(
            section.condition.fieldId,
            data,
            sections,
            predefinedValues,
            dynamicPredefinedValues,
            currentData
        );

        if (section.isMapping) {
            const options = config.templateOptions.get(section.condition.fieldId);
            // We just perform the evaluation to ensure logic works if needed,
            // but we return empty string because {Tag} will handle the actual output.
            return '';
        }

        if (!evaluateCondition(valToCompare, section.condition.operator || '=', section.condition.value)) {
            return '';
        }
    }

    let renderedItems = '';
    const itemsToProcess = section.isRepeatable
        ? Array.isArray(currentData[section.id])
            ? currentData[section.id]
            : Array.isArray(data[section.id])
                ? data[section.id]
                : []
        : [currentData[section.id] || (data[section.id] ? data[section.id] : currentData)];

    const itemsWithContent = (itemsToProcess as FormDataRecord[]).filter(
        (item: FormDataRecord) =>
            section.fieldIds.some((fid: string) =>
                hasContent(findValueForField(fid, data, sections, predefinedValues, dynamicPredefinedValues, item))
            ) ||
            (section.layout || []).some(
                (id: string) =>
                    (id.startsWith('section_') || id.startsWith('sec_') || id.startsWith('cond_')) &&
                    sectionHasValues(
                        sections.find((s) => s.id === id)!,
                        data,
                        sections,
                        predefinedValues,
                        dynamicPredefinedValues,
                        item
                    )
            )
    );

    if (itemsWithContent.length === 0) return '';

    renderedItems = itemsWithContent
        .map((item: FormDataRecord, index: number) => {
            let itemContent = section.originalContent || '';
            const itemLayout = section.layout || section.fieldIds;

            itemLayout.forEach((id: string) => {
                if (id.startsWith('section_') || id.startsWith('sec_') || id.startsWith('cond_')) {
                    const nestedSection = sections.find((s) => s.id === id);
                    if (nestedSection) {
                        const isVirtual = nestedSection.originalContent?.startsWith('{');
                        let nestedRegex;
                        if (isVirtual) {
                            nestedRegex = new RegExp(`${escapeRegExp(nestedSection.originalContent || '')}\\*`, 'g');
                        } else {
                            let header = '';
                            if (nestedSection.condition) {
                                const cond = nestedSection.condition;
                                const opPart = cond.operator && cond.value
                                    ? `\\s*${escapeRegExp(cond.operator)}\\s*(?:"${escapeRegExp(cond.value)}"|${escapeRegExp(cond.value)})`
                                    : '';
                                header = `\\?\\s*\\{\\s*${escapeRegExp(cond.fieldId)}\\s*\\}${opPart}`;
                            } else if (
                                nestedSection.singularTitle ||
                                nestedSection.pluralTitle ||
                                nestedSection.repeatableItemLabel
                            ) {
                                header += nestedSection.singularTitle
                                    ? `singular="${escapeRegExp(nestedSection.singularTitle)}"\\s*`
                                    : '';
                                header += nestedSection.pluralTitle ? `plural="${escapeRegExp(nestedSection.pluralTitle)}"\\s*` : '';
                                header += nestedSection.repeatableItemLabel
                                    ? `sub="${escapeRegExp(nestedSection.repeatableItemLabel)}"\\s*`
                                    : '';
                            } else if (nestedSection.label && nestedSection.label !== 'separator') {
                                header = `"${escapeRegExp(nestedSection.label)}"?\\s*`;
                            } else if (nestedSection.isSeparator || nestedSection.label === 'separator') {
                                header = '""';
                            }

                            const nestedBody = nestedSection.originalContent || '';
                            nestedRegex = new RegExp(
                                `\\[\\s*${header}\\s*\\]${escapeRegExp(nestedBody)}\\[\\/\\s*\\]${nestedSection.isRepeatable ? '\\s*\\*' : ''}`,
                                'g'
                            );
                        }
                        const renderedNested = renderSection(
                            id,
                            data,
                            sections,
                            fields,
                            config,
                            predefinedValues,
                            dynamicPredefinedValues,
                            item
                        );
                        itemContent = itemContent.replace(nestedRegex, renderedNested);
                    }
                } else {
                    const val = findValueForField(id, data, sections, predefinedValues, dynamicPredefinedValues, item);
                    itemContent = itemContent.replace(
                        new RegExp(`\\{${escapeRegExp(id)}(:dropdown\\(.*?\\)|:[a-zA-Z-]+)?\\}(\\*)?`, 'g'),
                        renderValue(val, id, fields, config)
                    );
                }
            });

            if (section.repeatableItemLabel) {
                const labelPrefix = `${section.repeatableItemLabel} #${String(index + 1).padStart(2, '0')}`;
                itemContent = `${labelPrefix}\n${itemContent}`;
            }
            return itemContent;
        })
        .join('\n');

    let title = '';
    if (itemsWithContent.length > 1 && section.pluralTitle) {
        title = section.pluralTitle;
    } else if (itemsWithContent.length === 1 && section.singularTitle) {
        title = section.singularTitle;
    } else if (section.label && section.label !== '""') {
        title = section.label;
    }

    if (title) {
        renderedItems = `*${title}*\n${renderedItems}`;
    }

    return renderedItems;
}

/**
 * Renders content with full section handling
 * 
 * Main rendering function with support for repeatable sections,
 * conditional sections, and complex nested structures
 */
export function renderContentWithSections(
    template: string,
    data: FormDataRecord,
    config: TemplateRenderConfig,
    predefinedValues: Record<string, string>,
    dynamicPredefinedValues: Record<string, string> = {}
): string {
    let finalContent = template;
    const { sections = [], fields = {} } = config;

    // Process top-level layout items
    const topLevelSections = sections.filter((s: SectionConfig) => {
        return config.layout.includes(s.id);
    });

    topLevelSections.forEach((section: SectionConfig) => {
        const isVirtual = section.originalContent?.startsWith('{');
        let sectionRegex;
        const baseContent = escapeRegExp(section.originalContent || '###NEVERMATCH###');

        if (isVirtual) {
            sectionRegex = new RegExp(`${escapeRegExp(section.originalContent || '')}\\*`, 'g');
        } else {
            let headerPart = '';
            if (section.condition) {
                const cond = section.condition;
                const opPart = cond.operator && cond.value
                    ? `\\s*${escapeRegExp(cond.operator)}\\s*(?:"${escapeRegExp(cond.value)}"|${escapeRegExp(cond.value)})`
                    : '';
                headerPart = `\\?\\s*\\{\\s*${escapeRegExp(cond.fieldId)}\\s*\\}${opPart}`;
            } else if (section.singularTitle || section.pluralTitle || section.repeatableItemLabel) {
                headerPart += section.singularTitle ? `singular="${escapeRegExp(section.singularTitle)}"\\s*` : '';
                headerPart += section.pluralTitle ? `plural="${escapeRegExp(section.pluralTitle)}"\\s*` : '';
                headerPart += section.repeatableItemLabel ? `sub="${escapeRegExp(section.repeatableItemLabel)}"\\s*` : '';
            } else if (section.label && section.label !== 'separator') {
                headerPart = `"${escapeRegExp(section.label)}"?\\s*`;
            } else if (section.isSeparator || section.label === 'separator') {
                headerPart = '""';
            }

            const bodyContent = section.originalContent || '';
            const fullBlockPattern = `\\[\\s*${headerPart}\\s*\\]${escapeRegExp(bodyContent)}\\[\\/\\s*\\]${section.isRepeatable ? '\\s*\\*' : ''}`;
            sectionRegex = new RegExp(fullBlockPattern, 'g');
        }

        const rendered = renderSection(
            section.id,
            data,
            sections,
            fields,
            config,
            predefinedValues,
            dynamicPredefinedValues,
            data
        );
        finalContent = finalContent.replace(sectionRegex, rendered);
    });

    // Final cleanup of loose tags (omit semantic tags for post-processing)
    finalContent = finalContent.replace(
        /\{([^:}]+?)(:dropdown\(.+?\)|:[a-zA-Z-]+)?(\|.+?)?\}/g,
        (match, fieldId) => {
            if (match.includes(':semantic')) return match;
            fieldId = fieldId.trim();
            const formValue = findValueForField(fieldId, data, sections, predefinedValues, dynamicPredefinedValues);
            return hasContent(formValue) ? renderValue(formValue, fieldId, fields, config) : '';
        }
    );

    return finalContent;
}

/**
 * Renders the final report with full template processing
 * 
 * Main entry point for template rendering. Handles:
 * - Template parsing
 * - Configuration building
 * - Full content rendering
 * - Summary extraction
 * - Semantic concept resolution
 * - Audit recording
 * 
 * @param template - Template string
 * @param data - Data for rendering
 * @param config - Field and section configuration
 * @param predefinedValues - Predefined values (e.g., global tags)
 * @param summaryOnly - If true, only extract summary markers
 * @param dynamicPredefinedValues - Runtime predefined values
 * @returns Rendered report string
 */
export function renderFinalReport(
    template: string,
    data: FormDataRecord,
    config: { fields: Record<string, FieldConfig>; sections: SectionConfig[]; layout: string[] },
    predefinedValues: Record<string, string>,
    summaryOnly: boolean = false,
    dynamicPredefinedValues: Record<string, string> = {},
    parseTemplate: (template: string) => TemplateParserResult,
    recordReportAudit: (reportId: string, audit: ResolutionResult[]) => void
): string {
    try {
        const { sections, layout, fieldNames, fieldTypes, templateOptions, fieldModifiers } =
            parseTemplate(template);

        // Build final config with all necessary data
        const finalConfig: TemplateRenderConfig = {
            fields: {} as Record<string, FieldConfig>,
            sections,
            layout,
            templateOptions,
            fieldModifiers,
        };

        fieldNames.forEach((fieldName: string) => {
            const fieldConfig: FieldConfig = config.fields[fieldName]
                ? { ...config.fields[fieldName] }
                : { type: 'text' as FieldType, label: fieldName };

            finalConfig.fields[fieldName] = fieldConfig;
            const options = templateOptions.get(fieldName);
            if (options) {
                fieldConfig.snippetOptions = options;
            }
            if (fieldTypes.has(fieldName)) {
                fieldConfig.type = fieldTypes.get(fieldName)!;
            }
        });

        // Render full content first
        let fullRenderedContent = renderContentWithSections(
            template,
            data,
            finalConfig,
            predefinedValues,
            dynamicPredefinedValues
        );

        // Extract summary if needed
        let summaryContent = '';
        if (summaryOnly) {
            const summaryRegex = /<<([\s\S]*?)>>/g;
            const matches = Array.from(fullRenderedContent.matchAll(summaryRegex));
            if (matches.length > 0) {
                summaryContent = matches.map((match) => match[1]).join('\n\n');
            }
            fullRenderedContent = summaryContent;
        }

        // Final cleanup and semantic post-processing
        let finalOutput = fullRenderedContent
            .replace(/<<|>>/g, '') // Remove summary markers
            .replace(/\[\?.*?\][\s\S]*?\[\/\s*\]/g, '') // Remove unprocessed conditional blocks
            .replace(/\[""\]\s*/g, '') // Remove separators
            .replace(/\[[\s\S]*?\](?:\s*)?(\*)?/g, ''); // Remove unprocessed section blocks

        // Resolve literal semantic tags
        const semanticRegex = /\{([\s\S]+?):semantic\}/g;
        const semanticAudit: ResolutionResult[] = [];

        finalOutput = finalOutput.replace(semanticRegex, (_, concept) => {
            const result = resolveSemanticConcept(concept.trim());
            semanticAudit.push(result);
            return String(result.value);
        });

        // Record audit if there's semantic data
        if (data.id && semanticAudit.length > 0) {
            recordReportAudit(String(data.id), semanticAudit);
        }

        finalOutput = finalOutput
            .replace(/\\\*/g, '*') // Convert escaped asterisks (\*) to literal asterisks (*)
            .replace(/\n{3,}/g, '\n\n') // Limit consecutive line breaks to max 2
            .replace(/\t/g, '    ') // Convert tabs to spaces
            .trim();

        return finalOutput;
    } catch (error) {
        logger.error('Error rendering report', error instanceof Error ? error : new Error(String(error)), {
            feature: 'TemplateRenderer',
            message: error instanceof Error ? error.message : String(error)
        });
        return 'Error al generar el reporte. La plantilla podr├¡a tener un formato incorrecto o faltan datos esenciales.';
    }
}

/**  
 * Template Validator - Semantic Validation
 * 
 * Validates parsed templates for semantic and syntax errors
 */

import type { ParseResult, ValidationResult } from './types';
import type { SectionConfig, FieldType, SnippetOption } from '@/types';

/**
 * Validates a template string for syntax errors
 * 
 * Checks for:
 * - Balanced braces { }
 * - Balanced brackets [ ]
 * - Properly closed conditionals [? ... [/]
 * 
 * @param template - The template string to validate
 * @returns Array of syntax error messages
 */
export function validateSyntax(template: string): string[] {
    const errors: string[] = [];

    // Check brace balance
    const openBraces = (template.match(/\{/g) || []).length;
    const closeBraces = (template.match(/\}/g) || []).length;
    if (openBraces !== closeBraces) {
        errors.push('Desbalance de llaves detectado.');
    }

    // Check bracket balance
    if (template.includes('[') && !template.includes(']')) {
        errors.push('Desbalance de Corchetes detectado.');
    }

    // Check unclosed conditionals
    if (template.includes('[?') && !template.includes('[/]')) {
        errors.push('Condicionales sin cerrar detectados.');
    }

    return errors;
}

/**
 * Validates semantic aspects of a parsed template
 * 
 * Checks for:
 * - Field references in conditionals that don't exist
 * - Invalid dropdown indices
 * - Other logical inconsistencies
 * 
 * @param sections - Parsed sections
 * @param fieldNames - Set of all field names in template
 * @param fieldTypes - Map of field types
 * @param templateOptions - Map of dropdown options
 * @returns Array of semantic error messages
 */
export function validateSemantics(
    sections: SectionConfig[],
    fieldNames: Set<string>,
    fieldTypes: Map<string, FieldType>,
    templateOptions: Map<string, SnippetOption[]>
): string[] {
    const errors: string[] = [];

    sections.forEach((section) => {
        if (section.condition) {
            const { fieldId, value, operator } = section.condition;

            // Verificar que el campo existe
            if (!fieldNames.has(fieldId)) {
                errors.push(
                    `El condicional hace referencia al campo '{${fieldId}}' que no est├í definido en la plantilla.`
                );
                return;
            }

            const fieldType = fieldTypes.get(fieldId);
            const options = templateOptions.get(fieldId);

            // Validar si es dropdown
            if (fieldType === 'dropdown' && options) {
                // Solo validar ├¡ndices num├®ricos para operador = (retrocompatibilidad)
                const isNumericIndex = (!operator || operator === '=') && /^\d+$/.test(value);
                if (isNumericIndex) {
                    const idx = parseInt(value, 10);
                    if (idx < 0 || idx >= options.length) {
                        errors.push(
                            `El condicional para '{${fieldId}}' usa ├¡ndice ${idx}, pero el dropdown solo tiene ${options.length} opciones (├¡ndices 0-${options.length - 1}).`
                        );
                    }
                }
            }
        }
    });

    return errors;
}

/**
 * Validates a parsed template for all types of errors
 * 
 * @param parseResult - The parsed template to validate
 * @param originalTemplate - Original template string for syntax validation
 * @returns Validation result with errors and warnings
 * 
 * @example
 * ```typescript
 * const result = parse(tokens);
 * const validation = validate(result, template);
 * if (!validation.isValid) {
 *   console.error('Template errors:', validation.errors);
 * }
 * ```
 */
export function validate(
    parseResult: ParseResult,
    originalTemplate?: string
): ValidationResult {
    const errors: string[] = [];
    const warnings: string[] = [];

    // Syntax validation if original template provided
    if (originalTemplate) {
        errors.push(...validateSyntax(originalTemplate));
    }

    // Semantic validation
    errors.push(
        ...validateSemantics(
            parseResult.sections,
            parseResult.fieldNames,
            parseResult.fieldTypes,
            parseResult.templateOptions
        )
    );

    // Check for duplicate field names (warning, not error)
    const fieldCount = new Map<string, number>();
    parseResult.fieldNames.forEach((name) => {
        fieldCount.set(name, (fieldCount.get(name) || 0) + 1);
    });

    fieldCount.forEach((count, name) => {
        if (count > 1) {
            warnings.push(
                `El campo '{${name}}' aparece ${count} veces en la plantilla. Esto puede causar comportamiento inesperado.`
            );
        }
    });

    return {
        isValid: errors.length === 0,
        errors,
        warnings,
    };
}

/**
 * Checks if a section has any fields defined
 */
export function sectionHasFields(section: SectionConfig): boolean {
    return section.fieldIds && section.fieldIds.length > 0;
}

/**
 * Checks if a field name is valid (not empty, no special chars)
 */
export function isValidFieldName(fieldName: string): boolean {
    if (!fieldName || fieldName.trim() === '') {
        return false;
    }

    // Field names should not contain template syntax characters
    if (fieldName.includes('{') || fieldName.includes('}') ||
        fieldName.includes('[') || fieldName.includes(']')) {
        return false;
    }

    return true;
}

/**
 * Validates that operator is valid for given field type
 */
export function isValidOperatorForType(
    operator: string,
    fieldType: FieldType
): boolean {
    const validOperators = ['=', '!=', '>', '<', '>=', '<='];

    if (!validOperators.includes(operator)) {
        return false;
    }

    // Numeric comparisons only make sense for certain types
    if (['>', '<', '>=', '<='].includes(operator)) {
        // These are fine for text (alphabetical) and dates
        return true;
    }

    return true;
}

